// ============================================================
// ANATOMÍA E HISTOLOGÍA FUNCIONAL · SEGUNDO PARCIAL
// FIUBA · CB110 · Cátedra Iurman · Bioingeniería
// Parcial del 24/11/2026 · clases 8 a 14 (hasta el 8/9 el campus decía 17/11)
// Las 13 preguntas de la sección 7 son REALES (parcialito de
// endocrinología + preguntas modelo). El resto son propias,
// al estilo de las 39 preguntas reales.
// ============================================================

// ---------- SECCIÓN 1 · QUÉ ENTRA Y CÓMO SE RINDE ----------
registerExercises('fiuba-anatomia-segundo-parcial', '1', [
  {st: '¿Qué clases del cronograma entran en el segundo parcial y en qué fecha se rinde?', opts: ['Clases 1 a 6, el 29/9', 'Clases 8 a 13, el 17/11', 'Clases 8 a 14, el 24/11', 'Todo el programa completo, el 24/11'], c: 2, ex: 'El segundo parcial es la <b>clase 15 del cronograma, el martes 24/11/2026</b>, y cubre las <b>clases 8 a 14</b>: esplacnología y respiratorio (6/10), cardiovascular (13/10), digestivo (20/10), urinario (27/10), endócrino (3/11) y nervioso en dos clases (10/11 y 17/11). → <b>Las otras:</b> (A) Clases 1 a 6 el 29/9 es el <b>primer</b> parcial: citología, embriología, tejidos, osteología, artrología y miología. → (B) Era la fecha vieja: hasta el 8/9 el campus decía parcial el 17/11 con las clases 8 a 13; en septiembre la cátedra agregó una segunda clase de nervioso (la 14, el 17/11) y corrió el parcial al 24/11. → (D) El segundo parcial <b>no es integrador</b>: el corte con el primero es limpio, lo microscópico y el aparato locomotor quedaron del otro lado.'},
  {st: "¿Cuántas preguntas reales hay del temario de este parcial y de dónde salen?", opts: ["13: las del campus (parcialito de Endocrinología y Preguntas modelo), todas de endocrinología, sin ninguna de anatomía", "33: las 13 que publicó la cátedra (11 de endocrinología, 1 del paper del ovario y 1 de nervioso) y las 20 del choice de anatomía", "39: las que publicó la cátedra en el campus sumando las del primer parcial, repartidas de forma pareja entre los seis sistemas vistos", "20: las del choice de repaso del docente de anatomía, 5 por cada uno de sus cuatro sistemas, sin ninguna del campus"], c: 1, ex: "Son <b>dos fuentes</b>. La cátedra publicó en el campus el <b>parcialito de Endocrinología</b> (8, todas endócrinas) y las <b>Preguntas modelo</b> (5: tres endócrinas, una del paper del constructo ovárico y una de lóbulo temporal). El docente de anatomía dio antes del segundo parcial de 2025 un <b>choice de repaso de 20 preguntas con las respuestas</b>: 5 de respiratorio, 5 de cardiovascular, 5 de digestivo y 5 de urinario. Total: <b>33</b>. → <b>Las otras:</b> (A) Faltan las 20 de anatomía, y entre las 13 hay una de sistema nervioso y una del paper, así que no son todas de endocrinología. → (C) 39 es lo que publicó la cátedra en el campus sumando el primer parcial; del temario de éste son 13, y no están parejas: 11 son endócrinas. → (D) Faltan las 13 del campus."},
  {st: "Las 20 preguntas del choice de repaso del docente de anatomía (respiratorio, cardiovascular, digestivo y urinario) se parecen entre sí. ¿Cuál es el patrón?", opts: ["Vienen envueltas en un escenario de diseño bioingenieril, como las de endocrinología", "Son de una línea y preguntan por una estructura con nombre propio: de dónde nace, dónde desemboca, en cuántas se divide o qué tiene adelante y atrás", "Piden cifras de fisiología: presiones, volúmenes pulmonares y gasto cardíaco", "Describen un corte histológico y piden reconocer el epitelio"], c: 1, ex: "Contadas sobre las 20: <b>9</b> preguntan un trayecto o una comunicación (de dónde nace la aorta, qué desemboca en el ciego, a qué vena va la testicular izquierda), <b>5</b> qué hace o qué es una estructura, dicho en una frase (el diafragma, la mitral, la fosa oval), <b>4</b> una posición o un orden (qué se ve en la laringe de frente, dónde queda el nodo aurículoventricular) y <b>2</b> en qué se divide o de qué está formada (los lobares del bronquio izquierdo, el colon izquierdo). → El distractor casi siempre es <b>la estructura de al lado</b> o <b>el lado contrario</b>: derecho por izquierdo, aurícula por ventrículo, uréter por uretra, cálices menores por mayores. → <b>Las otras:</b> (A) Ninguna de las 20 trae escenario: ése es el estilo de las preguntas de endócrino y nervioso. → (C) No hay ni un número de fisiología en las 20. → (D) Ninguna describe un corte: son todas de anatomía macroscópica."},
  {st: 'Los distractores de esta cátedra tienen una característica medida que cambia la forma de resolver: ¿cuál?', opts: ["Son afirmaciones disparatadas que se descartan de entrada, sin necesidad de conocer el tema", "Son categorías vecinas bien descriptas: la frase es verdadera, pero está en el casillero equivocado", "Siempre incluyen un error numérico o una unidad cambiada que alcanza para descartarlos", "Repiten la misma idea con distintas palabras, de modo que varias opciones dicen lo mismo"], c: 1, ex: "Es el rasgo que define el examen. El caso testigo está en el banco de parciales: en la pregunta de gonadotrofinas, el distractor es 'TSH y ACTH, porque tienen efectos estimulantes sobre otras glándulas endócrinas', <b>una definición correcta de las hormonas tróficas</b>, sólo que la pregunta pedía las <b>gonadotrofinas</b>. Confunde el género con la especie. → Consecuencia práctica: <b>no se puede eliminar por absurdo</b>. La pregunta real nunca es '¿esto es verdadero?' sino '¿verdadero <b>de qué</b>?'. → <b>Las otras:</b> (A) Justamente lo que no pasa: si pudieras descartar por absurdo, el examen sería mucho más fácil. → (C) Este parcial tiene poquísimos números: no es un examen de cálculo, y los distractores no se delatan por una cifra. → (D) Las opciones son claramente distintas entre sí; el problema es que varias son ciertas."},
  {st: 'La cátedra no usa microfotografías. ¿Qué habilidad concreta reemplaza a "reconocer la imagen"?', opts: ["Dibujar de memoria el corte histológico completo y rotular cada una de sus capas y de sus células", "Mapear una descripción textual (epitelio, citoplasma, luz) a la estructura que corresponde", "Memorizar los aumentos y las técnicas de tinción con que se observa cada tejido en el laboratorio", "Reconocer el tejido a partir del nombre de la estructura que el enunciado ya trae escrito"], c: 1, ex: "La identificación histológica <b>llega descripta en texto</b>. El enunciado dice 'epitelio cúbico simple <b>sin</b> borde en cepillo, con luz nítida' y vos tenés que responder <b>túbulo contorneado distal</b>; o 'epitelio plano simple extremadamente delgado que cubre el 95 % de la superficie' y responder <b>neumocito tipo I</b>. → Por eso la sección 3 de esta guía está armada en esa dirección: tapás la columna de la estructura y leés sólo las descripciones. → <b>Las otras:</b> (A) Nunca se pide dibujar ni rotular. → (C) Las tinciones aparecen apenas (Klüver-Barrera para mielina) y no como eje de pregunta. → (D) Es al revés: el enunciado trae la descripción y el nombre de la estructura es lo que hay que elegir; si ya viniera escrito no habría nada que identificar."},
  {st: 'De las 13 preguntas que publicó la cátedra para este parcial, el formato "decí en qué piso del eje endócrino está la falla" aparece:', opts: ['Una sola vez', 'Tres veces (23 % del banco)', 'En todas las preguntas de endocrinología', 'Nunca: es un formato de la carrera de Medicina'], c: 1, ex: 'Aparece <b>tres veces</b>: pregunta 8 del parcialito (definir primario vs secundario, sin panel) y preguntas 1 y 5 de las Preguntas modelo (las dos <b>sí</b> con panel de laboratorio explícito). Sobre 13, es el <b>23 %</b>. → Es el formato de mayor demanda del parcial y se resuelve con dos comparaciones, sin memorizar nada: periférica y trófica en <b>direcciones opuestas</b> → primario; en la <b>misma dirección</b> → central. → <b>Las otras:</b> (A) Subestima: si sólo apareciera una vez no valdría la pena dedicarle una sección entera. → (C) Las otras preguntas endócrinas son conceptuales (mecanismo, clasificación, blanco de cada hormona) y no piden localizar nada en el eje. → (D) Es un formato real y publicado por esta cátedra, con la salvedad de que el razonamiento clínico aparece <b>sólo</b> en endocrinología.'},
  {st: 'Hay una pregunta que aparece DOS veces dentro de las 13 de la cátedra, con enunciado distinto y el mismo fondo. ¿Cuál?', opts: ['La diferencia entre hormonas liposolubles e hidrosolubles', 'Qué hormonas son las gonadotrofinas', 'La localización de la lesión en el eje tiroideo', 'La función principal del sistema endócrino'], c: 1, ex: 'Es la pregunta 4 del parcialito y la pregunta 4 de las Preguntas modelo: distinta redacción, mismas cuatro familias de opciones (GH+PRL / TSH+ACTH / FSH+LH / oxitocina+ADH) y la misma clave, <b>FSH y LH</b>. Es el ítem con mayor frecuencia medida de todo el banco de este parcial. → Vale como dato de estudio: si hay <b>un</b> par de hormonas que tenés que tener grabado, es ése, junto con su distractor fijo (TSH+ACTH). → <b>Las otras:</b> (A) Aparece dos veces pero <b>desde ángulos distintos</b>: mecanismo de acción (parcialito 3) y vía de administración de la insulina (parcialito 5). Es la misma idea, no la misma pregunta. → (C) Aparece tres veces, pero con enunciados y respuestas distintos (parcialito 8: definir primario vs secundario, sin panel; modelo 1: primario; modelo 5: terciario). → (D) Aparece una sola vez, como pregunta 1 del parcialito.'},
  {st: 'Un compañero te dice: "en esta materia, la opción que dice \'exclusivamente\' o \'solo\' siempre está mal". ¿Qué le contestás?', opts: ["Que tiene razón: es una regla confiable en cualquier multiple choice, porque los absolutos casi siempre son falsos", "Que no: la clave de especificidad hormonal dice que solo afecta a las células con receptores", "Que da lo mismo: los absolutos no aparecen en este parcial, ni en las claves ni en los distractores", "Que la regla vale sólo para histología, porque en el parcialito de endocrinología ninguna clave trae absolutos"], c: 1, ex: "La pregunta 2 del parcialito real tiene como clave: 'Porque <b>solo</b> afecta a aquellas células que tienen receptores específicos para esa hormona en particular'. El absoluto está en la respuesta correcta. → La regla verdadera es más fina: el absoluto delata cuando <b>reduce indebidamente el alcance</b> de algo que en realidad es más amplio (como la opción 'regular el pH y el equilibrio hidroelectrolítico <b>exclusivamente</b>', que achica el sistema endócrino a una sola tarea), y <b>no</b> delata cuando enuncia una <b>restricción verdadera</b>, como la especificidad por receptor. → <b>Las otras:</b> (A) Es la heurística que la cátedra explota en las dos direcciones, así que no es confiable. → (C) Aparecen varias veces, tanto en distractores como en la clave. → (D) La regla no se estratifica por tema: ni vale sólo para histología ni queda excluida en endocrinología, donde está justo la clave de especificidad."},
  {st: "Según el plan de repaso contado hacia atrás desde el 24/11, ¿qué se estudia PRIMERO y por qué?", opts: ["Endocrinología, porque es el sistema del que hay más preguntas publicadas por la cátedra", "Respiratorio y cardiovascular, porque son las más lejanas y las que más se olvidan", "Nervioso, porque es la última clase y conviene arrancar con lo más fresco de la memoria", "El simulacro, para medir cómo estás parado antes de empezar a estudiar el resto"], c: 1, ex: "Respiratorio y cardiovascular se dictaron el <b>6/10 y el 13/10</b>: para el 24/11 hace más de un mes que no los ves, y son las que más se borraron. → El plan las pone el 8 y 9/11, antes incluso de las dos clases de nervioso, y les da una segunda pasada el 18 y 19/11, ya con las preguntas del docente de anatomía. → <b>Las otras:</b> (A) Endocrino se estudia D-4/D-3, pegado al parcial, justamente porque es de los más frescos (clase del 3/11) y el mejor documentado: rinde más repasarlo cerca. → (C) Nervioso se dicta en dos clases (10/11 y 17/11) y conviene <b>dejarlo decantar</b> unos días antes de estudiarlo a fondo; que sea la última clase no lo vuelve lo primero. → (D) El simulacro va en D-2, cuando ya repasaste todo: hacerlo antes de estudiar mide poco y desmoraliza sin dar información útil."},
  {st: 'Un enunciado del parcial arranca: "Un equipo desarrolla un dispositivo de asistencia respiratoria y necesita reproducir la interfaz donde ocurre el intercambio gaseoso...". ¿Cuál es el primer movimiento correcto?', opts: ["Buscar en las opciones cuál menciona materiales o polímeros, porque el enunciado es de ingeniería", "Tachar el decorado y aislar el requisito funcional (intercambio gaseoso), y recién ahí leer las opciones", "Descartar de entrada las opciones que no mencionan el pulmón o los alvéolos, porque el enunciado es de respiratorio", "Elegir la opción más larga y detallada, porque suele ser la que trae la justificación completa"], c: 1, ex: "El envoltorio de diseño aparece en el <b>26 %</b> de las preguntas reales y <b>no agrega contenido de ingeniería que haya que saber</b>: agrega un paso de traducción. El procedimiento es siempre el mismo: <b>1)</b> tachá el decorado; <b>2)</b> aislá el sustantivo que dice <i>qué tiene que hacer</i> (resistir tracción, absorber, aislar, conducir, intercambiar); <b>3)</b> traducí requisito → estructura; <b>4)</b> recién ahí mirá las opciones. → El orden importa: si mirás las opciones primero, los distractores (categorías vecinas correctas) te empujan a elegir por familiaridad. → <b>Las otras:</b> (A) Lo que se evalúa sigue siendo histología y anatomía; el vocabulario de materiales es decorado. → (C) Descartar por palabra clave es exactamente lo que explotan los distractores: la estructura pedida puede no nombrar el órgano. → (D) La longitud de la opción no correlaciona con nada; en el banco de parciales hay claves cortas y claves largas."},
]);

// ---------- SECCIÓN 2 · EL MÉTODO DE LOS EJES ENDÓCRINOS ----------
registerExercises('fiuba-anatomia-segundo-parcial', '2', [
  {st: 'Paciente con hipofunción tiroidea. Laboratorio: <b>T4 baja, TSH alta</b>. ¿Dónde está la lesión?', opts: ["En la hipófisis: no manda suficiente TSH, así que la tiroides no recibe el estímulo", "En la propia glándula tiroides: hipotiroidismo primario, y la TSH alta es la hipófisis compensando", "En el hipotálamo: falta TRH, así que la hipófisis no estimula a la tiroides como debería", "En los tejidos que no responden a la T4, con el eje hipotálamo, hipófisis y tiroides intacto"], c: 1, ex: "Periférica <b>baja</b> + trófica <b>alta</b> = se mueven en <b>direcciones opuestas</b> = falla la <b>glándula periférica</b> = <b>PRIMARIO</b>. La hipófisis está sana: ve poca T4, pierde el freno de la retroalimentación negativa y sube la TSH tratando de exprimir a una glándula que no puede responder. → Causas típicas: tiroiditis de Hashimoto, tiroidectomía, déficit de yodo, fármacos. → <b>Las otras:</b> (A) Si fallara la hipófisis, la TSH estaría <b>baja</b>, no alta: el dato de laboratorio la descarta sola. → (C) En el terciario también estaría baja la TSH, porque sin TRH la hipófisis no la secreta. → (D) Una resistencia periférica a la hormona daría T4 <b>normal o alta</b> con síntomas de déficit, no T4 baja; además no es una entidad que la cátedra desarrolle."},
  {st: 'Laboratorio: <b>T3/T4 muy bajas, TSH muy baja, TRH baja</b>. ¿Diagnóstico?', opts: ['Hipotiroidismo primario', 'Hipotiroidismo secundario (hipofisario)', 'Hipotiroidismo terciario (hipotalámico)', 'Enfermedad de Graves'], c: 2, ex: 'Los <b>tres</b> pisos están bajos, así que la lesión hay que ubicarla en el <b>escalón más alto deprimido</b>: cada nivel explica la caída del que le sigue. Sin TRH la hipófisis no secreta TSH; sin TSH la tiroides, que está sana, no produce T3/T4. Eso es <b>terciario o hipotalámico</b>. → <b>El dato que decide es la TRH.</b> Sin ese valor, secundario y terciario son indistinguibles: por eso el enunciado real te lo regala. → <b>Las otras:</b> (A) Un primario daría T4 baja con TSH y TRH <b>elevadas</b> por pérdida del freno. → (B) Si la rota fuera la hipófisis, el hipotálamo, sano y detectando la T4 baja, tendría la <b>TRH alta</b> compensando. Una TRH baja descarta el origen hipofisario. → (D) Graves es <b>hiper</b>tiroidismo: T3/T4 <b>altas</b> con TSH suprimida.'},
  {st: 'Mujer con pérdida de peso, taquicardia, intolerancia al calor y exoftalmia. <b>T3/T4 altas, TSH suprimida</b>. La afirmación correcta es:', opts: ["La TSH está alta porque el receptor de TSH está hiperestimulado y la glándula produce hormona de más", "Hiperfunción primaria: la glándula produce por su cuenta, frena a la hipófisis y el receptor lo estimulan anticuerpos", "Es un hipertiroidismo secundario, porque la hipófisis manda demasiada TSH y la glándula responde produciendo hormona de más", "Es un bocio, que por definición implica hiperfunción y se diagnostica por el aumento de tamaño de la glándula tiroides"], c: 1, ex: "Periférica <b>alta</b> + trófica <b>baja</b> = <b>hiperfunción primaria</b>. En la enfermedad de Graves hay anticuerpos que <b>estimulan el receptor de TSH</b> (TSI): la tiroides produce sin que nadie se lo pida, y ese exceso suprime la TSH por retroalimentación negativa. → <b>Las otras:</b> (A) Es exactamente el error que la cátedra usa como distractor en la pregunta modelo 1: confundir 'receptor hiperestimulado' con 'TSH alta'. El receptor está estimulado <b>por anticuerpos</b>; la TSH medida está baja. → (C) Un hipertiroidismo <b>secundario</b> (adenoma hipofisario secretor de TSH) daría T4 alta con TSH <b>alta</b>, y es rarísimo; el enunciado dice TSH suprimida. → (D) <b>Bocio</b> es simplemente <b>aumento de tamaño</b> de la tiroides: es un <b>signo</b>, no un diagnóstico funcional, y puede acompañar hiper o hipofunción."},
  {st: 'La regla general que permite localizar la lesión en cualquier eje endócrino se enuncia así:', opts: ["Si las dos hormonas están bajas, el fallo es periférico (primario); si se mueven en direcciones opuestas, el fallo es central", "Si trófica y periférica se mueven en direcciones opuestas, el fallo es periférico (primario); si van en la misma dirección, es central", "Siempre hay que dosar las tres hormonas del eje para poder decidir dónde está la lesión, sin excepciones", "La hormona hipotalámica sola alcanza para clasificar cualquier caso, porque es la que está más arriba en el eje"], c: 1, ex: "Es la regla de dos líneas y sirve para el eje tiroideo, el suprarrenal y el gonadal por igual, porque la arquitectura es la misma: tres pisos con retroalimentación negativa. → <b>Opuestas</b> (periférica baja, trófica alta) → la glándula final falla y el controlador compensa → <b>primario</b>. → <b>Misma dirección</b> (las dos bajas) → el controlador está roto → <b>central</b>, y ahí la hipotalámica desempata secundario de terciario. → <b>Las otras:</b> (A) Invierte la regla: las dos bajas indica <b>central</b>, y las direcciones opuestas indican primario. → (C) Con dos hormonas (trófica y periférica) ya distinguís primario de central; la tercera sólo hace falta para separar secundario de terciario. → (D) La hipotalámica sola no dice nada: una TRH alta es compatible tanto con primario como con secundario."},
  {st: 'Un paciente tiene <b>cortisol bajo y ACTH alta</b>. ¿Qué se puede afirmar?', opts: ["Falla la hipófisis: no produce ACTH suficiente para estimular la corteza suprarrenal", "Falla la corteza suprarrenal: es una insuficiencia suprarrenal primaria, con la ACTH alta compensando", "Falla la médula suprarrenal, que es la que produce el cortisol bajo el estímulo de la ACTH", "Es un exceso de retroalimentación positiva del hipotálamo sobre la hipófisis que eleva la ACTH"], c: 1, ex: "La lógica es idéntica a la del eje tiroideo, cambiando los nombres: <b>CRH → ACTH → corteza suprarrenal → cortisol</b>. Periférica (cortisol) <b>baja</b> + trófica (ACTH) <b>alta</b> → direcciones opuestas → falla la <b>glándula periférica</b> → <b>primario</b>. La hipófisis está viva y grita más fuerte. → <b>Las otras:</b> (A) Si fallara la hipófisis, la ACTH estaría <b>baja</b>. → (C) Error de compartimento y de producto: la <b>médula</b> suprarrenal produce <b>adrenalina y noradrenalina</b>, no cortisol, y no está regulada por ACTH sino por el <b>simpático</b> directo. El cortisol es de la <b>corteza</b>: ACTH es adreno<b>CORTICO</b>tropa. → (D) Los ejes endócrinos clásicos funcionan por retroalimentación <b>negativa</b>; la ACTH alta acá es justamente la <b>pérdida</b> del freno negativo, no una realimentación positiva."},
  {st: 'Un enunciado ofrece como respuesta: "Hipotiroidismo terciario: el problema es la falta de yodo en la dieta". El error es:', opts: ["Que el yodo no tiene nada que ver con la síntesis de hormonas tiroideas, así que su falta no puede causar hipotiroidismo", "Que el déficit de yodo da hipotiroidismo, pero primario: falla el sustrato en la glándula; el terciario es hipotalámico", "Que el yodo se relaciona con la calcitonina y no con T3/T4, así que su falta no altera el eje tiroideo principal", "Que el hipotiroidismo terciario no existe como categoría, porque sólo se clasifican primarios y secundarios"], c: 1, ex: "Es el <b>distractor de mitad verdadera</b>, el más peligroso del tema. La fisiopatología es correcta (sin yodo no hay síntesis de T3/T4 y aparece hipotiroidismo con TSH alta), pero la <b>etiqueta está mal</b>: el yodo es el sustrato de la síntesis <b>dentro de la tiroides</b>, así que la falla es de la glándula periférica y eso es <b>primario</b>. → <b>Terciario = hipotálamo = falta de TRH.</b> → Regla de lectura: media opción verdadera no es una opción verdadera. → <b>Las otras:</b> (A) El yodo es imprescindible: la T4 tiene cuatro átomos de yodo y la T3 tres. → (C) La calcitonina regula el <b>calcio</b> y la producen las células <b>parafoliculares</b>: no interviene en el eje T3/T4, y el yodo es justamente el sustrato de T3/T4. → (D) La categoría existe en las Preguntas modelo de la cátedra, aunque la clase de endocrinología sólo defina primario y secundario."},
  {st: 'Si una hormona actúa uniéndose a un receptor de membrana y activando un segundo mensajero como el AMPc, entonces:', opts: ["Es liposoluble: atraviesa la membrana, su efecto es lento y duradero y se administra por vía oral", "Es hidrosoluble: no atraviesa la membrana, su efecto es rápido y breve y va por vía parenteral", "Es una hormona tiroidea: atraviesa la membrana, su efecto es lento y duradero y se da por vía oral", "Actúa directamente sobre el ADN modificando la transcripción, con un efecto rápido y breve en segundos"], c: 1, ex: "La solubilidad determina todo lo demás. <b>Hidrosolubles</b> (peptídicas y proteicas como insulina, GH, TSH; y las catecolaminas): no cruzan la bicapa, se unen a un receptor de <b>superficie</b>, disparan un <b>segundo mensajero</b> (AMPc vía adenilato ciclasa, IP3/DAG, Ca²⁺) y una cascada de fosforilaciones que modifica <b>enzimas ya existentes</b>. Efecto en segundos a minutos, y breve. Por vía oral las hidrolizarían las proteasas digestivas: exigen vía parenteral. → <b>Las otras:</b> (A) y (C) invierten la clasificación: las liposolubles (esteroideas y tiroideas) <b>no usan segundo mensajero</b>, y un receptor de membrana con AMPc es justo lo que ellas no tienen; en la (C), además, las tiroideas son liposolubles y no cumplen la premisa. → (D) Actuar sobre el ADN como factor de transcripción es lo que hacen las <b>liposolubles</b>, y por eso su efecto tarda horas pero dura: hay que sintetizar proteínas nuevas; no es rápido ni breve."},
  {st: 'T3 y T4 derivan de la tirosina, un aminoácido. ¿Cómo las clasifica la cátedra y qué consecuencia práctica tiene?', opts: ["Como aminoacídicas e hidrosolubles: receptor de membrana, segundo mensajero y vía endovenosa, como las ampollas inyectables", "Como liposolubles: receptor intracelular, acción sobre el ADN y administración oral, por lo que se dan en comprimidos o cápsulas", "Como eicosanoides, derivados de lípidos de membrana: acción local, receptor de membrana y vía tópica, como las cremas", "Como peptídicas, por tener aminoácidos unidos: receptor de membrana, segundo mensajero y vía parenteral, como las inyecciones"], c: 1, ex: "Es la trampa de clasificación más rentable del tema. Aunque deriven de la tirosina, las tiroideas se comportan como <b>liposolubles</b>: atraviesan la membrana, tienen receptor <b>intracelular/nuclear</b> y actúan sobre la transcripción. La cátedra las pone explícitamente en el grupo <b>1b, liposolubles</b>, y por eso un fármaco como la levotiroxina se toma en comprimidos. → Las <b>aminoacídicas</b> de la clase son sólo <b>adrenalina, noradrenalina y melatonina</b>. → Consecuencia directa: si las clasificás mal contestás 'endovenosa' cuando la respuesta correcta es <b>oral</b>. → <b>Las otras:</b> (A) Es exactamente el error inducido: hidrosoluble, receptor de membrana y endovenosa son rasgos de otras hormonas; las tiroideas no los tienen. → (C) Los eicosanoides son prostaglandinas y leucotrienos, derivados del ácido araquidónico, de acción local; T3 y T4 son hormonas circulantes derivadas de la tirosina. → (D) No es un péptido: la T4 se forma acoplando <b>dos tirosinas yodadas</b> por un puente <b>éter</b>, no por enlaces peptídicos. Por eso las proteasas digestivas no la tocan y se puede dar por boca."},
  {st: 'Sobre las dos mitades de la hipófisis, la afirmación correcta es:', opts: ["La neurohipófisis es glandular y fabrica siete hormonas; la adenohipófisis es tejido nervioso y sólo almacena y libera las del hipotálamo", "La adenohipófisis es glandular y fabrica siete hormonas; la neurohipófisis es tejido nervioso y sólo almacena y libera las del hipotálamo", "La adenohipófisis es glandular y fabrica siete hormonas; la neurohipófisis es tejido nervioso y sintetiza ADH y oxitocina en sus células", "Las dos son tejido nervioso, y las dos sólo almacenan y liberan las hormonas que sintetiza el hipotálamo en sus núcleos"], c: 1, ex: "Son dos órganos de origen embriológico distinto pegados en la silla turca. La <b>adenohipófisis</b> es epitelial-glandular y produce <b>siete</b> hormonas: GH, prolactina, TSH, ACTH, FSH, LH y <b>MSH</b> (no te la comas al contar). La <b>neurohipófisis</b> es tejido <b>nervioso</b>: son los axones de las neuronas de los núcleos <b>supraóptico y paraventricular</b> del hipotálamo, que bajan por el tallo y sueltan ahí lo que fabricaron arriba. Por eso sólo <b>almacena y libera</b> ADH y oxitocina. → Consecuencia de examen: si preguntan qué glándula <b>sintetiza</b> la oxitocina, la respuesta involucra al <b>hipotálamo</b>, no a la neurohipófisis. → <b>Las otras:</b> (A) Invierte los dos lóbulos: la glandular con siete hormonas es la adenohipófisis y la nerviosa es la neurohipófisis. → (C) La neurohipófisis no sintetiza nada: ADH y oxitocina se fabrican en los núcleos supraóptico y paraventricular del hipotálamo, y ella sólo las almacena y libera. → (D) Sólo la neurohipófisis es nerviosa; la adenohipófisis es epitelial-glandular y fabrica sus siete hormonas propias."},
  {st: 'En el par que regula la calcemia:', opts: ["La PTH la producen las células parafoliculares de la tiroides y sube la calcemia; la calcitonina la producen las glándulas paratiroides y la baja", "La PTH la producen las células principales de las paratiroides y sube la calcemia; la calcitonina la producen las parafoliculares y la baja", "La PTH la producen las células principales de las paratiroides y baja la calcemia; la calcitonina la producen las parafoliculares y la sube", "La PTH la producen las células principales de las paratiroides y sube la calcemia; la calcitonina la producen las foliculares y la baja"], c: 1, ex: "Anclaje que no falla: la PTH la fabrican las glándulas paratiroides, que están <b>detrás</b> de la tiroides, y <b>sube</b> el calcio; la calcitonina la fabrican células parafoliculares que están <b>dentro</b> de la tiroides, y lo <b>baja</b>. → La <b>PTH</b> actúa en tres frentes: aumenta la <b>resorción ósea</b>, aumenta la reabsorción renal de Ca²⁺ y estimula el <b>calcitriol</b>, que a su vez aumenta la absorción intestinal. La <b>calcitonina</b> inhibe osteoclastos y mete Ca²⁺ al hueso. → Nota de diseño: el hueso es el <b>reservorio de calcio</b> del organismo, así que un andamio óseo se reabsorbe a una velocidad que depende del estado de este eje en el paciente. → <b>Las otras:</b> (A) Invierte las dos glándulas: la PTH es de las paratiroides y la calcitonina de las parafoliculares de la tiroides. → (C) Invierte los dos efectos: son antagónicas, la PTH sube el calcio y la calcitonina lo baja, en un control push-pull. → (D) Las células foliculares de la tiroides fabrican T3 y T4; la calcitonina es de las parafoliculares (células C)."},
  {st: '¿Por qué la médula suprarrenal, a diferencia de la corteza que tiene encima, no está controlada por ninguna hormona trófica hipofisaria?', opts: ["Porque está inervada por fibras parasimpáticas preganglionares: es el brazo hormonal del sistema parasimpático, y la orden le llega por vía nerviosa", "Porque está inervada por fibras simpáticas preganglionares: es el brazo hormonal del sistema simpático, y la orden le llega por vía nerviosa", "Porque está inervada por fibras simpáticas posganglionares: es un ganglio más del sistema simpático, y la orden le llega por vía nerviosa", "Porque la controla el hipotálamo con una hormona liberadora que llega directo por la sangre, sin pasar por la hipófisis, y no por un nervio"], c: 1, ex: "La médula suprarrenal es, embriológica y funcionalmente, un <b>ganglio simpático modificado</b> (deriva de la <b>cresta neural</b>): sus células son neuronas posganglionares que en vez de tener axón vuelcan su producto (<b>adrenalina y noradrenalina</b>) a la sangre. Por eso la orden le llega por <b>fibra preganglionar simpática</b> y no por una trófica hipofisaria. → Es lo que explica que la respuesta de estrés tenga dos velocidades: la nerviosa, instantánea, y la hormonal, que dura más porque las catecolaminas circulan. → No es la única glándula sin trófica (las paratiroides responden a la calcemia y los islotes a la glucemia), pero sí la única cuyo estímulo es una <b>fibra nerviosa preganglionar</b>, y es la que hace pareja con una corteza que <b>sí</b> tiene trófica. → <b>Las otras:</b> (A) El brazo hormonal del sistema nervioso autónomo es el <b>simpático</b>; la médula suprarrenal no recibe fibras parasimpáticas ni vagales. → (C) La médula se parece a un ganglio, pero no está inervada por fibras posganglionares: sus células cromafines ya son las posganglionares modificadas, y lo que les llega es la fibra <b>preganglionar</b> colinérgica. → (D) La médula no tiene eje hipotálamo-hipofisario propio: la CRH actúa sobre la adenohipófisis y la ACTH resultante controla la <b>corteza</b> únicamente, que es adreno<b>CORTICO</b>tropa."},
  {st: 'Un dispositivo de páncreas artificial combina un sensor continuo de glucosa con una bomba de insulina. Desde la fisiología del islote, ¿cuál es su limitación estructural?', opts: ["Que implementa sólo el brazo de la insulina: le falta el antagonista, el glucagón de la célula delta, y el lazo puede sobrecorregir hacia la hipoglucemia", "Que implementa sólo el brazo de la insulina: le falta el antagonista, el glucagón de la célula alfa, y el lazo puede sobrecorregir hacia la hipoglucemia", "Que implementa sólo el brazo de la insulina: le falta la somatostatina, que sube la glucemia, y el lazo puede sobrecorregir hacia la hipoglucemia", "Que implementa sólo el brazo de la insulina: le falta el antagonista, el glucagón de la célula alfa, y el lazo puede pasarse hacia la hiperglucemia"], c: 1, ex: "El islote es un <b>control push-pull</b> sobre una sola variable: la célula <b>beta</b> baja la glucemia (insulina) y la <b>alfa</b> la sube (glucagón), y la <b>D</b> (somatostatina) modula a las dos. Un páncreas artificial de un solo brazo puede empujar la glucemia hacia abajo pero no tiene con qué frenar el sobredisparo, y ahí es donde aparece la hipoglucemia iatrogénica. Los sistemas bihormonales existen justamente para cerrar ese hueco. → <b>Las otras:</b> (A) El glucagón es de la célula <b>alfa</b>; la célula delta (D) secreta somatostatina. → (C) La somatostatina es un modulador <b>paracrino</b> que inhibe a la insulina y al glucagón: no sube la glucemia, el antagonista es el glucagón. → (D) Sin brazo del glucagón el error de sobrecorrección es hacia la <b>hipoglucemia</b>, no hacia la hiperglucemia, porque nada frena la bajada."},
]);

// ---------- SECCIÓN 3 · LAS DISCRIMINACIONES QUE DECIDEN EL PARCIAL ----------
registerExercises('fiuba-anatomia-segundo-parcial', '3', [
  {st: 'Un enunciado describe: "célula cúbica con microvellosidades, menos numerosa que su vecina, intercalada entre las células que tapizan el alvéolo". ¿De qué célula habla y qué hace?', opts: ["Neumocito tipo I: es plano, cubre casi toda la pared y es el sitio del intercambio gaseoso", "Neumocito tipo II: secreta surfactante y es la progenitora que repone a los tipo I", "Macrófago alveolar: fagocita partículas inhaladas y se desplaza sobre la pared alveolar", "Célula caliciforme: secreta moco y se intercala en el epitelio alveolar"], c: 1, ex: "Tres pistas apuntan al mismo lado: <b>cúbica</b> (no plana), <b>con microvellosidades</b> y <b>menos numerosa</b>. Es el <b>neumocito tipo II</b> o célula septal, que secreta el <b>surfactante</b> (fosfolípidos y lipoproteínas que bajan la tensión superficial del líquido alveolar) y además es la <b>célula progenitora</b> que repone a los tipo I después de una lesión. → <b>Las otras:</b> (A) El tipo I es <b>plano simple, extremadamente delgado</b> y cubre el <b>~95 %</b> de la superficie: su delgadez es su función, porque minimiza la distancia de difusión. Es la inversión más cobrada del respiratorio. → (C) El macrófago está <b>libre en la luz</b>, no es cúbico ni forma parte del epitelio, y su disparador en el enunciado sería fagocitar o defender. → (D) No hay células caliciformes en el alvéolo: desaparecen mucho antes, en el árbol bronquial, junto con el cartílago."},
  {st: 'Ordená las capas de la membrana alveolocapilar desde el aire alveolar hasta la sangre.', opts: ["Líquido con surfactante y epitelio alveolar → membrana basal del endotelio capilar → membrana basal del epitelio → endotelio capilar", "Líquido con surfactante y epitelio alveolar → membrana basal del epitelio → membrana basal del endotelio → endotelio capilar", "Endotelio capilar → membrana basal del endotelio → membrana basal del epitelio → epitelio alveolar con líquido y surfactante", "Líquido con surfactante y epitelio alveolar → endotelio capilar → membrana basal del endotelio → membrana basal del epitelio"], c: 1, ex: "Son cuatro capas y el orden es el que recorre una molécula de O<sub>2</sub>: primero la película de <b>líquido alveolar con surfactante</b> más el <b>epitelio alveolar</b> (neumocitos I y II), después la <b>membrana basal del epitelio</b>, después la <b>membrana basal del endotelio</b> (muy a menudo fusionada con la anterior) y por último el <b>endotelio</b> del capilar pulmonar. Espesor total ~<b>0,5 µm</b> sobre ~<b>70 m²</b> de superficie. → <b>Las otras:</b> (A) Cambia el orden de las dos basales: cada una está pegada a su propia célula, así que la del epitelio va primero, del lado del aire. → (C) Es el orden invertido: sería el recorrido del CO<sub>2</sub>, no el que pide el enunciado. → (D) Pone el endotelio antes que las basales, cuando éstas van <b>entre</b> el epitelio alveolar y el endotelio."},
  {st: '¿Cuál de los siguientes NO es uno de los cuatro factores que determinan la velocidad del intercambio gaseoso?', opts: ['La diferencia de presión parcial del gas', 'La superficie disponible para el intercambio', 'La fuerza de contracción del diafragma', 'La distancia de difusión'], c: 2, ex: 'Los cuatro factores son: <b>diferencia de presión parcial</b>, <b>superficie</b>, <b>distancia de difusión</b> y <b>peso molecular y solubilidad</b> del gas. La contracción del diafragma determina la <b>ventilación</b> (cuánto aire entra y sale) pero no la <b>difusión</b> a través de la membrana, que es lo que pregunta el enunciado. → Es la distinción que separa un problema de bomba de un problema de intercambiador, y es exactamente el listado que un oxigenador de membrana (ECMO) usa como variables de diseño: gradiente, superficie de membrana, espesor y elección del material según la solubilidad de cada gas. → <b>Las otras tres</b> son factores legítimos, y cada una tiene su patología asociada: el enfisema ataca la <b>superficie</b>, el edema pulmonar la <b>distancia</b>, la altura el <b>gradiente</b>.'},
  {st: 'Un vaso tiene la túnica media dominada por láminas elásticas fenestradas. ¿Qué vaso es y qué función le da esa estructura?', opts: ["Arteria muscular: regula el flujo hacia cada órgano con la contracción del músculo liso de su media", "Arteria elástica: se dilata en sístole y retrocede en diástole, alisando el flujo pulsátil", "Arteriola: ofrece la mayor resistencia periférica con una o pocas capas de músculo liso en su media", "Vena de gran calibre: almacena buena parte del volumen sanguíneo con una media delgada y mucha adventicia"], c: 1, ex: "Las <b>láminas elásticas fenestradas</b> en la media son la firma de la <b>arteria elástica</b> o de conducción: aorta, tronco pulmonar, carótidas comunes, subclavias e ilíacas comunes. La elasticidad almacena energía en sístole y la devuelve en diástole, convirtiendo el flujo pulsátil en uno más continuo, que es lo que sostiene el flujo entre latidos. → Es un dato de diseño directo: un injerto vascular rígido en posición aórtica <b>no amortigua</b> y transmite el pulso entero a la periferia. → <b>Las otras:</b> (A) La arteria muscular (braquial, radial, femoral) tiene la media de <b>músculo liso</b> con lámina elástica interna neta y es <b>vaso de distribución</b>: su media no está dominada por láminas elásticas. → (C) La arteriola tiene de una a pocas capas de músculo liso y es donde se regula la presión arterial: es el sitio principal de <b>resistencia</b>, y no tiene láminas elásticas fenestradas. → (D) La vena tiene media <b>delgada</b>, adventicia gruesa y luz amplia, y contiene el 60-65 % del volumen sanguíneo; no tiene láminas elásticas en la media."},
  {st: 'Verdadero o falso: "las arterias siempre llevan sangre oxigenada". Elegí la justificación correcta.', opts: ["Verdadero: por definición, arteria es el vaso que lleva sangre oxigenada desde el corazón hacia el resto del cuerpo", "Falso: arteria es el vaso que sale del corazón, y las arterias pulmonares llevan sangre desoxigenada al pulmón", "Falso: arteria es el vaso que llega al corazón, y las arterias pulmonares llevan sangre oxigenada hacia el pulmón", "Verdadero, salvo en el feto, donde las arterias umbilicales llevan sangre desoxigenada hacia la placenta"], c: 1, ex: "La definición es <b>direccional</b>, no bioquímica: <b>arteria = sale del corazón, vena = llega al corazón</b>. Las dos excepciones son las del circuito pulmonar y son exactamente lo que se pregunta: las <b>arterias pulmonares</b> llevan sangre <b>desoxigenada</b> desde el ventrículo derecho al pulmón, y las <b>cuatro venas pulmonares</b> llevan sangre <b>oxigenada</b> del pulmón a la aurícula izquierda. → Corolario: las cámaras con sangre desoxigenada son <b>aurícula y ventrículo derechos</b>; las oxigenadas, las dos izquierdas. → <b>Las otras:</b> (A) Parte de una definición equivocada: arteria no es el vaso con sangre oxigenada sino el que sale del corazón. → (C) Invierte la definición: el vaso que llega al corazón es la vena, y la sangre del pulmón vuelve oxigenada por las venas pulmonares. → (D) En el feto hay además cortocircuitos y las umbilicales llevan sangre desoxigenada, pero la excepción pulmonar existe toda la vida, así que no es verdadero salvo en el feto."},
  {st: 'Un capilar tiene poros de 70-100 nm en la propia célula endotelial pero la lámina basal continua. ¿Qué tipo es y qué implica?', opts: ["Continuo: está en el SNC y en el músculo, pasa plasma por transcitosis y la lámina basal continua retiene todas las proteínas del plasma", "Fenestrado: está en el glomérulo renal y en las glándulas endócrinas, pasa plasma y la lámina basal continua retiene las proteínas", "Sinusoide: está en el hígado y en el bazo, pasa plasma y proteínas porque la lámina basal es discontinua o falta", "Fenestrado: está en el hígado y en la médula ósea, pasa plasma y la lámina basal continua retiene las proteínas"], c: 1, ex: "La discriminación en una línea: <b>fenestrado = agujeros en la célula, lámina basal ENTERA</b>. Por eso filtra plasma y retiene proteínas, y por eso es el capilar del <b>glomérulo renal</b> (tiene que retener albúmina), del intestino delgado, de los plexos coroideos y de las <b>glándulas endócrinas</b> (la hormona tiene que salir rápido a la sangre). → <b>Las otras:</b> (A) El continuo <b>no tiene poros</b>: endotelio unido por uniones estrechas y lámina basal continua; pasa lo que pasa por transcitosis. Es el del SNC, músculo, piel y pulmón, y no el que describe el enunciado. → (C) El sinusoide tiene aberturas grandes <b>y además</b> lámina basal ausente o discontinua: pasan proteínas y células enteras. Está en hígado, bazo, médula ósea roja, adenohipófisis y suprarrenales. → (D) Ubica mal al fenestrado: el hígado y la médula ósea tienen capilar <b>sinusoide</b>, porque necesitan intercambiar proteínas plasmáticas y hasta células."},
  {st: 'Un enunciado dice: "tejido conectivo que fija la mucosa a la muscular, con vasos de grueso calibre y un plexo nervioso propio". ¿Qué túnica es y qué plexo aloja?', opts: ["Lámina propia, con el plexo de Auerbach", "Submucosa, con el plexo submucoso de Meissner", "Muscular, con el plexo submucoso de Meissner", "Serosa, con el plexo mientérico de Auerbach"], c: 1, ex: "La frase <b>fija la mucosa a la muscular</b> es la definición operativa de la <b>submucosa</b>, y el plexo que aloja es el <b>submucoso o de Meissner</b>, que regula <b>secreción glandular, movimiento de la mucosa y vasoconstricción</b>. → Regla mnemotécnica: el plexo que está <b>dentro del músculo</b> (mientérico o de Auerbach, entre la capa circular interna y la longitudinal externa) es el que maneja el <b>músculo</b>, o sea la motilidad. → <b>Las otras:</b> (A) La <b>lámina propia</b> es <b>parte de la mucosa</b>: conectivo areolar con vasos, linfáticos y <b>MALT</b>. No fija nada a la muscular y no aloja plexos; además Auerbach no está ahí. → (C) La muscular no es tejido conectivo (son dos capas de músculo) y su plexo es el de Auerbach, no el de Meissner. → (D) La serosa es un mesotelio con conectivo laxo y no aloja el de Auerbach, que está entre las dos capas de la muscular."},
  {st: '¿En qué se diferencian, funcionalmente, los pliegues circulares del intestino delgado y las rugosidades del estómago?', opts: ["Las rugosidades son permanentes y enlentecen el quimo y amplían la superficie; los pliegues circulares se borran al llenarse el intestino para permitir la distensión", "Los pliegues circulares son permanentes y enlentecen el quimo y amplían la superficie de absorción; las rugosidades se borran al llenarse el estómago para permitir la distensión", "Los pliegues circulares son permanentes y permiten la distensión del intestino; las rugosidades se borran al llenarse el estómago para enlentecer el quimo", "Los pliegues circulares son permanentes y están formados sólo por mucosa; las rugosidades se borran al llenarse el estómago para permitir la distensión"], c: 1, ex: "Es una inversión que da vuelta las dos funciones de un saque. Los <b>pliegues circulares</b> del intestino son <b>permanentes</b>, están formados por <b>mucosa + submucosa</b> y obligan al quimo a hacer espiral: enlentecen el tránsito y amplían el área de absorción. Las <b>rugosidades gástricas</b> <b>se borran</b> cuando el estómago se llena, porque su función es exactamente esa: <b>permitir la distensión</b> para almacenar. → Un órgano diseñado para <b>almacenar</b> pliega su pared de forma reversible; uno diseñado para <b>absorber</b> la pliega de forma permanente. → <b>Las otras:</b> (A) Es la inversión completa: los permanentes son los pliegues circulares y los que se borran son las rugosidades. → (C) Intercambia las funciones: los pliegues circulares enlentecen el quimo y amplían superficie, y las rugosidades existen para permitir la distensión gástrica. → (D) Los pliegues circulares incluyen <b>submucosa</b>; las estructuras formadas sólo por mucosa son las <b>vellosidades</b>."},
  {st: 'Una gastritis atrófica destruye selectivamente las células parietales. ¿Qué dos consecuencias se esperan?', opts: ["Hipoclorhidria por falta de HCl y anemia perniciosa por falta de factor intrínseco y de absorción de B12 en el duodeno", "Hipoclorhidria por falta de HCl y anemia perniciosa por falta de factor intrínseco y de B12 en el íleon", "Hipoclorhidria por falta de HCl y anemia perniciosa por falta de gastrina y de absorción de vitamina B12 en el íleon", "Falta de moco alcalino por pérdida de la célula parietal y anemia perniciosa por falta de factor intrínseco y de B12 en el íleon"], c: 1, ex: "La célula parietal (u oxíntica) secreta <b>dos cosas que no tienen nada que ver entre sí</b> y las dos se preguntan: <b>HCl</b> y <b>factor intrínseco</b>. Perder la célula pierde las dos funciones: sin HCl no se desnaturalizan las proteínas ni se activa el pepsinógeno; sin factor intrínseco no se absorbe <b>vitamina B<sub>12</sub></b> en el íleon, y aparece la <b>anemia perniciosa</b>. → <b>Las otras:</b> (A) La vitamina B12 unida al factor intrínseco se absorbe en el <b>íleon</b>, no en el duodeno. → (C) La falta que produce la anemia perniciosa es la del <b>factor intrínseco</b>, de la parietal; la <b>gastrina</b> es una hormona de la célula <b>G</b> del antro y no interviene en la absorción de B12. → (D) El moco alcalino lo secretan las células <b>mucosas</b> superficiales y del cuello, no la parietal, así que no se pierde."},
  {st: 'El enunciado describe: "epitelio cúbico simple SIN borde en cepillo, luz nítida, más núcleos por corte transversal, ubicado en la corteza renal". ¿Qué segmento es?', opts: ['Túbulo contorneado proximal', 'Túbulo contorneado distal', 'Rama descendente delgada del asa de Henle', 'Conducto colector'], c: 1, ex: 'Los cuatro adjetivos apuntan al <b>túbulo contorneado distal</b>. El mapeo que hay que tener automatizado, porque la cátedra no usa microfotografías y describe todo en texto: <b>"borde en cepillo denso, citoplasma acidófilo, luz borrosa"</b> → TCP; <b>"cúbico sin borde en cepillo, luz nítida"</b> → TCD; <b>"plano simple en plena médula"</b> → asa delgada; <b>"límites celulares muy marcados, citoplasma pálido"</b> → colector. → Función del TCD: <b>ajuste fino</b> de Na⁺ y Cl⁻, y reabsorción de Ca²⁺ regulada por la <b>PTH</b>. → <b>Las otras:</b> (A) El TCP tiene borde en cepillo denso (el que le borronea la luz) y muchas mitocondrias, porque reabsorbe ~65 % del agua y del Na⁺ y prácticamente el 100 % de la glucosa y de los aminoácidos. → (C) El asa delgada es <b>plano simple</b> y está en la <b>médula</b>, no en la corteza. → (D) El colector tiene límites celulares nítidos y baja a la médula.'},
  {st: '¿Cuál es la diferencia funcional entre la rama descendente delgada y la rama ascendente del asa de Henle?', opts: ["La descendente es impermeable al agua y bombea NaCl, así que el líquido se diluye; la ascendente deja salir agua, concentra el líquido e hipertoniza el intersticio", "La descendente es permeable al agua, así que el líquido se concentra; la ascendente es impermeable al agua y bombea NaCl, diluye el líquido e hipertoniza el intersticio", "La descendente es permeable al agua, así que el líquido se concentra; la ascendente también es permeable al agua y bombea NaCl, así que el intersticio se hace hipertónico", "Las dos ramas son permeables al agua y la ascendente bombea NaCl, así que el líquido sale isotónico y no se forma gradiente medular"], c: 1, ex: "Es el motor del <b>multiplicador de contracorriente</b>, y las dos ramas hacen cosas <b>opuestas</b> a propósito: la descendente deja salir <b>agua</b> (el líquido tubular se concentra) y la ascendente saca <b>sal sin agua</b> (el líquido se diluye y el intersticio queda hipertónico). Ese intersticio hipertónico es lo que después permite que la ADH concentre la orina en el colector. → <b>Consecuencia de diseño:</b> sin <b>nefronas yuxtamedulares</b> (asas largas más <b>vasos rectos</b> como intercambiador de contracorriente) no hay gradiente medular, y un riñón artificial que repueble sólo la corteza <b>filtra pero produce orina diluida</b>. Es exactamente lo que se observa en el paper del riñón bioingenierizado. → <b>Las otras:</b> (A) Invierte las dos ramas: la descendente es la permeable al agua y la ascendente la que bombea NaCl sin agua. → (C) Si la ascendente fuera permeable al agua, el agua seguiría a la sal y no se diluiría el líquido ni se formaría el gradiente: la ascendente es <b>impermeable</b> al agua. → (D) Anula el gradiente, que es todo el punto del asa: la impermeabilidad de la ascendente al agua es lo que permite diluir el líquido y concentrar el intersticio."},
  {st: 'Un enunciado dice: "célula del SNC, de origen mesodérmico, que fagocita desechos y estructuras lesionadas". ¿Cuál es, y por qué el dato del origen importa?', opts: ["Astrocito: es la única glía mesodérmica (médula ósea), y un organoide sólo ectodérmico no lo tiene", "Microglía: única glía mesodérmica (médula ósea), y un organoide sólo ectodérmico no la tiene", "Oligodendrocito: es mesodérmico y fagocita mielina, y un organoide sólo ectodérmico no lo tiene", "Célula de Schwann: deriva de la cresta neural, que es mesodérmica, y un organoide ectodérmico no la tiene"], c: 1, ex: "Todo el tejido nervioso es de origen <b>ectodérmico</b>… salvo la <b>microglía</b>, que viene de la <b>médula ósea</b> y es el componente inmunitario residente del SNC. La cátedra remarca esa excepción, y tiene una consecuencia concreta y preguntable: un <b>organoide neural</b> derivado sólo de precursores ectodérmicos <b>no tiene microglía</b>, así que no tiene componente fagocítico ni respuesta inmune innata. Hay que agregarla desde linaje hematopoyético para modelar neuroinflamación. → <b>Las otras:</b> (A) El astrocito es <b>ectodérmico</b> como el resto del tejido nervioso, y sus disparadores son <b>cicatriz</b> y <b>barrera hematoencefálica</b>, no fagocitosis. → (C) El oligodendrocito es <b>ectodérmico</b> y hace la <b>mielina del SNC</b>; no es el fagocito. → (D) La <b>cresta neural</b> es <b>ectodérmica</b>, no mesodérmica, aunque sus células migren por todo el embrión, y la célula de Schwann es del SNP. La excepción es <b>una sola</b>."},
  {st: 'Hay que diseñar un conducto de guía para regenerar un nervio ciático seccionado. ¿Con qué célula se siembra y por qué?', opts: ["Con oligodendrocitos, porque el ciático es del SNC y la mielina central la hace el oligodendrocito", "Con células de Schwann, porque el ciático es del SNP y la mielina periférica la hace la célula de Schwann", "Con astrocitos, porque el ciático es del SNP y forman el tejido que guía el crecimiento de los axones", "Con ependimarias, porque el ciático es del SNP y revisten los conductos por donde crecen los axones"], c: 1, ex: "La respuesta a quién hace la mielina <b>no es única</b>: depende del compartimento. <b>SNC → oligodendrocito. SNP → célula de Schwann.</b> El ciático es un nervio periférico, así que el linaje correcto es Schwann, que además, siendo derivado de <b>cresta neural</b>, es lo que hay que pedirle a un protocolo de diferenciación. → Detalle que suma: una Schwann mieliniza <b>un segmento de un solo axón</b>; en las fibras <b>amielínicas</b> la misma célula envuelve <b>muchos</b> axones sin formar vaina. Un andamio que alinee axones pero no favorezca la mielinización no recupera velocidad de conducción, porque sin nodos de Ranvier no hay <b>conducción saltatoria</b>. → <b>Las otras:</b> (A) Error de compartimento: el ciático es periférico y el oligodendrocito mieliniza en el SNC. → (C) El astrocito forma la cicatriz glial, que en el SNC es justamente una <b>barrera</b> a la regeneración, y no es una célula del SNP. → (D) Las ependimarias revisten ventrículos y canal del epéndimo, son del SNC y no guían axones periféricos."},
  {st: 'Sobre la sustancia gris y la blanca, la afirmación correcta es:', opts: ["En la médula la gris es periférica y la blanca central, en H; en el cerebro la gris es la corteza externa y la blanca queda adentro", "En la médula espinal la gris es central, en H, y la blanca periférica; en el cerebro la gris es la corteza externa y la blanca queda por dentro", "En la médula la gris es central, en H, y la blanca periférica; en el cerebro es igual: la gris queda al centro y la blanca en la corteza", "En la médula la gris es central, en H, y la blanca periférica; en el cerebro la gris es la corteza y contiene los axones mielinizados"], c: 1, ex: "La distribución se invierte entre los dos niveles y es exactamente lo que se pregunta: en la <b>médula espinal</b> la gris es <b>central</b>, con forma de H (asta dorsal sensitiva, asta ventral motora), y la blanca la rodea; en el <b>cerebro</b> la gris es la <b>corteza externa</b> y la blanca queda por dentro. → Dato de tinción: con <b>Klüver-Barrera</b> la sustancia <b>blanca se ve azul</b> porque la técnica tiñe la <b>mielina</b>; la gris se ve rosada o violácea y contiene los pericariones. → <b>Las otras:</b> (A) Invierte la médula: allí la gris es central, en H, y la blanca es periférica. → (C) Ignora la inversión: en el cerebro la gris es la corteza externa y la blanca está por dentro, no igual que en la médula. → (D) La gris tiene los cuerpos neuronales (pericariones) y la <b>blanca</b> los axones mielinizados, y de ahí viene el color, porque la mielina es lipídica y blanquecina en fresco."},
]);

// ---------- SECCIÓN 4 · REPASO RELÁMPAGO · RESPIRATORIO Y CARDIOVASCULAR ----------
registerExercises('fiuba-anatomia-segundo-parcial', '4', [
  {st: '¿Por qué los anillos de la tráquea son incompletos por detrás?', opts: ["Porque el cartílago anterior permite que la tráquea se alargue al inspirar y la abertura posterior deja que el esófago se expanda al tragar", "Porque el cartílago anterior evita el colapso de la vía aérea durante la inspiración y la abertura posterior deja que el esófago se expanda al tragar", "Porque el cartílago posterior evita el colapso de la vía aérea al inspirar y la abertura anterior deja que el esófago se expanda al tragar", "Porque el cartílago anterior evita el colapso de la vía aérea durante la inspiración y la abertura posterior aloja las cuerdas vocales al tensarse"], c: 1, ex: "Es un <b>compromiso de diseño</b> explícito y por eso se pregunta. El cartílago <b>por delante</b> impide que la tráquea colapse cuando la presión intratorácica cae en la inspiración; la <b>abertura posterior</b> (donde hay conectivo denso y el <b>músculo traqueal</b>) permite que el <b>esófago se expanda hacia adelante</b> con el bolo, y deja que el músculo ajuste el calibre. Un diseño con anillos completos resolvería el colapso pero bloquearía la deglución. → <b>Las otras:</b> (A) El alargamiento traqueal existe pero no es la razón de la forma en C, y no es el cartílago el que lo permite sino el conectivo. → (C) Invierte los lados: el cartílago está por <b>delante</b> y el esófago, que está por detrás, es el que necesita la abertura posterior. → (D) Las cuerdas vocales están en la <b>laringe</b>, por encima de la tráquea."},
  {st: 'A medida que el árbol bronquial se ramifica hacia la periferia:', opts: ["Aumenta el cartílago, disminuye la proporción de músculo liso y el epitelio pasa de cilíndrico seudoestratificado ciliado a plano simple", "Desaparece el cartílago, aumenta la proporción de músculo liso y el epitelio pasa de cilíndrico seudoestratificado ciliado a plano simple", "Desaparece el cartílago, aumenta la proporción de músculo liso y el epitelio pasa de plano simple a cilíndrico seudoestratificado ciliado", "Desaparece el cartílago, aumenta la proporción de músculo liso y el epitelio sigue cilíndrico seudoestratificado ciliado con caliciformes hasta el alvéolo"], c: 1, ex: "Tres gradientes simultáneos, y cada uno tiene su consecuencia preguntable. <b>Cartílago:</b> anillos en C → placas irregulares → desaparece en los bronquiolos. Por eso el bronquiolo no tiene esqueleto y se cierra si el músculo se contrae. <b>Músculo liso:</b> sube su proporción relativa. Por eso el <b>asma</b> cierra bronquiolos y no la tráquea. <b>Epitelio:</b> cilíndrico seudoestratificado ciliado con caliciformes → cúbico ciliado → cúbico sin cilios → <b>plano simple</b> en el alvéolo, porque el requisito cambia de <b>barrer moco</b> a <b>dejarse atravesar</b>. → <b>Las otras:</b> (A) Es la inversión exacta: hacia la periferia el cartílago desaparece y el músculo liso gana proporción. → (C) Invierte el epitelio: va de cilíndrico seudoestratificado ciliado (bronquios) a plano simple (alvéolo), no al revés. → (D) Las caliciformes y los cilios desaparecen mucho antes del alvéolo, y el epitelio se adelgaza; moco en el alvéolo sería fatal para la difusión."},
  {st: 'Un neumotórax hace que el pulmón colapse aunque la vía aérea esté perfectamente permeable. ¿Por qué?', opts: ["Porque el aire que entra a la cavidad pleural obstruye los bronquios y el pulmón se retrae por su propio retroceso elástico", "Porque se pierde la adherencia entre las hojas pleurales y el pulmón se retrae por su propio retroceso elástico", "Porque el aire en la pleura destruye el surfactante de los alvéolos y el pulmón se retrae por su propio retroceso", "Porque el diafragma deja de contraerse del lado afectado y el pulmón se retrae por su propio retroceso elástico"], c: 1, ex: "El pulmón es un órgano <b>elástico y estirado</b>: su estado natural es colapsado, y lo que lo mantiene abierto es que sigue a la pared torácica. Esa unión es <b>física, no anatómica</b>: la película de <b>líquido pleural</b> pega las dos hojas por <b>tensión superficial</b>, y la presión intrapleural <b>subatmosférica</b> tracciona hacia afuera. Si entra aire (neumotórax) o sangre (hemotórax), se pierde la adherencia y el pulmón se retrae solo. → Es la mejor demostración de que la respiración es un problema de <b>acoplamiento mecánico</b>, no de permeabilidad de tubos. → <b>Las otras:</b> (A) El aire queda en la cavidad pleural, afuera del pulmón: la vía aérea no se obstruye. → (C) El surfactante sigue estando, porque lo producen los neumocitos tipo II y el aire pleural no lo destruye; falla el acoplamiento a la pared. → (D) El diafragma sigue contrayéndose: mueve la pared, pero el pulmón ya no la sigue."},
  {st: 'Verdadero o falso: "la espiración tranquila es un proceso activo que requiere contracción de los músculos espiratorios". Elegí la justificación.', opts: ["Verdadero: se contraen los intercostales internos y los abdominales, que empujan el aire hacia afuera en cada ciclo", "Falso: la espiración tranquila es pasiva, se relajan los inspiratorios y actúa el retroceso elástico", "Verdadero: hay actividad muscular, porque el diafragma y los intercostales externos también se contraen al espirar", "Falso: la espiración tranquila es pasiva, se contrae el diafragma y el retroceso elástico eleva su cúpula"], c: 1, ex: "La espiración tranquila no gasta trabajo muscular: se <b>relajan</b> los inspiratorios (diafragma e intercostales externos) y el <b>retroceso elástico</b> del pulmón y de la pared torácica devuelve el volumen. La presión alveolar sube ~2 mmHg por encima de la atmosférica (760 → 762) y el aire sale. → El retroceso elástico tiene <b>dos componentes</b>: las fibras elásticas estiradas durante la inspiración <b>más</b> la tracción de la tensión superficial del líquido alveolar. → Los <b>abdominales</b> y los <b>intercostales internos</b> entran sólo en la espiración <b>forzada</b>. → <b>Las otras:</b> (A) Esos músculos intervienen sólo en la espiración forzada; en la tranquila no se contraen. → (C) Los inspiratorios se contraen al inspirar y se relajan al espirar: no hay actividad muscular espiratoria en reposo. → (D) Dice que es pasiva pero pone al diafragma contrayéndose: el diafragma es <b>inspiratorio</b>, su contracción lo aplana y aumenta el volumen torácico. Inervación, nervio frénico (C3-C5)."},
  {st: 'De los siguientes, ¿cuál NO forma parte de la capacidad vital?', opts: ['Volumen corriente', 'Volumen de reserva inspiratoria', 'Volumen residual', 'Volumen de reserva espiratoria'], c: 2, ex: '<b>Capacidad vital = VRI + VC + VRE = 4.800 mL</b>: todo el aire <b>movilizable</b>. El <b>volumen residual</b> (1.200 mL) es justamente lo que <b>queda</b> tras una espiración forzada y por definición no se puede movilizar; ni siquiera se puede medir con espirometría. → Las dos confusiones clásicas: <b>capacidad residual funcional = VR + VRE = 2.400</b> (lo que queda tras una espiración <b>normal</b>) y <b>capacidad pulmonar total = CV + VR = 6.000</b>, la única que incluye el residual. → Bonus: el <b>espacio muerto</b> (~150 mL) no es un volumen pulmonar más, es la porción del corriente que se queda en las vías de conducción. Por eso respirar rápido y superficial ventila peor que lento y profundo con el mismo volumen minuto: la <b>ventilación alveolar</b> es (500 − 150) × 12 = 4.200 mL/min, contra 6.000 de volumen minuto.'},
  {st: 'La afinidad de la hemoglobina por el oxígeno DISMINUYE (se entrega más O2 a los tejidos) cuando:', opts: ["Sube el pH, baja la PCO2 y baja la temperatura corporal", "Baja el pH, sube la PCO2 y sube la temperatura", "Baja el pH, baja la PCO2 y sube la temperatura", "Baja el pH, sube la PCO2 y baja la temperatura"], c: 1, ex: "Los tres factores (pH bajo, PCO<sub>2</sub> alta y temperatura alta) describen exactamente <b>un músculo trabajando</b>: ácido, caliente y con mucho CO<sub>2</sub>. La curva se desplaza a la derecha y la hemoglobina suelta más oxígeno justo donde más se necesita, <b>sin ninguna señal nerviosa</b>: es regulación local pura, y por eso es una pregunta favorita. El desplazamiento por pH tiene nombre propio: <b>efecto Bohr</b>. → <b>Las otras:</b> (A) Es el sentido inverso: pH alto, PCO<sub>2</sub> baja y frío <b>aumentan</b> la afinidad, la hemoglobina retiene. → (C) Una PCO<sub>2</sub> baja <b>aumenta</b> la afinidad; para disminuirla hace falta PCO<sub>2</sub> alta. → (D) El frío <b>aumenta</b> la afinidad; para disminuirla hace falta temperatura alta."},
  {st: '¿Cómo se transporta la mayor parte del CO2 en la sangre?', opts: ["Unido al hierro del hemo (~70 %), en competencia con el oxígeno por el mismo sitio del eritrocito", "Como ion bicarbonato en el plasma (~70 %), formado en el eritrocito por la anhidrasa carbónica", "Disuelto en el plasma (~70 %), en equilibrio con el CO2 que entra al eritrocito y la anhidrasa carbónica", "Unido a la albúmina plasmática (~70 %), formando un complejo que no pasa por el eritrocito"], c: 1, ex: "El reparto es <b>~70 % bicarbonato</b>, <b>~23 % carbaminohemoglobina</b> y <b>~7 % disuelto</b>. La conversión ocurre <b>dentro del glóbulo rojo</b> por la <b>anhidrasa carbónica</b>: CO<sub>2</sub> + H<sub>2</sub>O ⇄ H<sub>2</sub>CO<sub>3</sub> ⇄ H⁺ + HCO<sub>3</sub>⁻, y el bicarbonato sale al plasma intercambiándose por cloruro (<b>desplazamiento de cloruro</b>). → Esa reacción es la que conecta el aparato respiratorio con el <b>equilibrio ácido-base</b>: eliminar CO<sub>2</sub> es eliminar ácido volátil. → <b>Las otras:</b> (A) El CO<sub>2</sub> que viaja unido a la hemoglobina se une a la <b>globina</b>, no al hemo: el hemo es para el O<sub>2</sub>, y ese 23 % no es la mayoría. → (C) Sólo el 7 % viaja disuelto. → (D) La albúmina no es el transportador de CO<sub>2</sub>, y la mayor parte del transporte sí pasa por el eritrocito."},
  {st: 'Se está diseñando una válvula cardíaca de reemplazo para la posición mitral. ¿Qué propiedad de la válvula nativa hay que entender para no diseñar mal el aparato de sostén?', opts: ["Que las cuerdas tendinosas abren y cierran la válvula al tirar de las valvas cuando se contraen los músculos papilares durante la sístole", "Que la válvula se cierra por la presión ventricular y cuerdas y papilares impiden que las valvas se eviertan hacia la aurícula", "Que la válvula se cierra por la contracción de los músculos papilares y las cuerdas sólo transmiten esa fuerza a las valvas mitrales", "Que la válvula se cierra por la presión ventricular y cuerdas y papilares impiden que las valvas se eviertan hacia el ventrículo"], c: 1, ex: "El error de modelo más común del tema. La válvula auriculoventricular se cierra por la <b>presión</b> del ventrículo que se contrae; las <b>cuerdas tendinosas</b> y los <b>músculos papilares</b> funcionan como las cuerdas de un paracaídas: <b>impiden la eversión</b> de las valvas hacia la aurícula. Los papilares se contraen <b>junto con el resto del ventrículo</b> y tensan las cuerdas: no cierran la válvula, la sostienen cerrada. Si se rompe una cuerda, la valva prolapsa y aparece una insuficiencia. → Dato extra: las valvas son <b>avasculares</b> (conjuntivo denso revestido por endocardio, nutrido por difusión desde la sangre de la cámara), y la <b>mitral o bicúspide</b> tiene <b>dos</b> valvas; la tricúspide, tres. → <b>Las otras:</b> (A) Es el error de modelo: las cuerdas no abren ni cierran la válvula, sólo la sostienen una vez cerrada. → (C) Los papilares no cierran la válvula, que se cierra por la presión del ventrículo; cuerdas y papilares impiden la eversión. → (D) La eversión sería hacia la <b>aurícula</b>, que es el lado de menor presión; las valvas no pueden evertirse hacia el ventrículo, que es adonde las empuja la sangre al abrirse."},
  {st: 'El ventrículo izquierdo tiene un miocardio unas tres veces más grueso que el derecho porque:', opts: ["Debe expulsar más volumen sistólico que el derecho, porque el circuito sistémico es más largo que el pulmonar, de baja resistencia", "Debe generar más presión contra la resistencia del circuito sistémico, que es largo, mientras que el derecho empuja contra el pulmonar, de baja resistencia", "Debe generar más presión contra la resistencia del circuito pulmonar, mientras que el derecho empuja contra el sistémico, de baja resistencia", "Debe soportar más presión porque recibe sangre oxigenada, más viscosa, mientras que el derecho empuja contra el circuito pulmonar, de baja resistencia"], c: 1, ex: "Los dos ventrículos expulsan, en promedio, <b>exactamente el mismo volumen</b>: están <b>en serie</b>, y un desbalance sostenido de unos pocos mililitros por latido vaciaría un circuito y congestionaría el otro. Lo que cambia es la <b>presión</b>: el circuito sistémico es largo y de alta resistencia, el pulmonar es corto y de baja resistencia. <b>Espesor de pared = requisito de presión, no de volumen.</b> → Es el mismo razonamiento que aplica un dispositivo de asistencia ventricular: se dimensiona por la presión que tiene que generar del lado que asiste. → <b>Las otras:</b> (A) Es la confusión que la pregunta busca: el volumen sistólico es el mismo en los dos ventrículos. → (C) Invierte los circuitos: el de alta resistencia es el sistémico y el de baja resistencia es el pulmonar. → (D) La viscosidad no cambia de manera relevante con la oxigenación, y la razón del espesor es la presión, no la sangre que recibe."},
  {st: 'El orden correcto del sistema de conducción cardíaco es:', opts: ["Nódulo SA → haz de His → nódulo AV → ramas derecha e izquierda → red de fibras de Purkinje", "Nódulo SA → nódulo AV → haz de His → ramas derecha e izquierda → fibras de Purkinje", "Nódulo AV → nódulo SA → haz de His → ramas derecha e izquierda → fibras de Purkinje", "Nódulo SA → nódulo AV → fibras de Purkinje → ramas derecha e izquierda → haz His"], c: 1, ex: "El <b>nódulo sinoauricular</b> (pared de la aurícula derecha, junto a la desembocadura de la cava superior) es el <b>marcapasos natural</b>, con ritmo propio de ~100/min. El <b>nódulo AV</b> introduce el <b>retraso</b> que permite a las aurículas terminar de vaciarse antes de que arranque el ventrículo. El <b>haz de His</b> es la <b>única vía posible</b> de aurículas a ventrículos, porque el <b>esqueleto fibroso</b> los aísla eléctricamente. Después, ramas y <b>Purkinje</b> hasta las fibras contráctiles. → <b>Las otras:</b> (A) El haz de His no puede ir antes del nódulo AV: el impulso llega a él a través del AV, que es el que lo retrasa. → (C) Invierte el comienzo: el nódulo SA es el marcapasos y dispara primero; el AV sólo lo retransmite. → (D) Purkinje es el último eslabón, y el His va antes de las ramas. → Dato que confirma el ritmo propio: en el trasplante cardíaco se seccionan los vagos, y el corazón trasplantado late en reposo a <b>unos 100 por minuto</b>. La frecuencia normal más baja es el nódulo SA <i>frenado</i> por el tono vagal."},
  {st: 'En el ECG, la onda T corresponde a:', opts: ['La despolarización auricular', 'La despolarización ventricular', 'La repolarización ventricular', 'La repolarización auricular'], c: 2, ex: '<b>P</b> = despolarización auricular · <b>QRS</b> = despolarización ventricular · <b>T</b> = <b>repolarización ventricular</b> · segmento <b>ST</b> = ventrículos completamente despolarizados, o sea la <b>meseta</b> del potencial de acción. → La <b>repolarización auricular no se ve</b>: coincide en el tiempo con el QRS, que es mucho más grande, y queda enmascarada. Buscarla en el trazado es perder tiempo. → La <b>meseta</b> existe porque se abren <b>canales lentos de Ca²⁺ dependientes de voltaje</b>: la fibra cardíaca queda despolarizada mucho más tiempo que la esquelética, su período refractario es larguísimo y por eso el corazón <b>no puede tetanizar</b>. Es un requisito de diseño obvio: una bomba que se contrae y no se relaja no bombea.'},
  {st: 'Un atleta de resistencia bien entrenado, comparado con una persona sedentaria en reposo, tiene:', opts: ["Mayor volumen sistólico y mayor gasto cardíaco de reposo, con la misma frecuencia cardíaca", "Mayor volumen sistólico y bradicardia de reposo, con el mismo gasto cardíaco de reposo", "Menor volumen sistólico y taquicardia de reposo, con el mismo gasto cardíaco de reposo", "Mayor volumen sistólico y frecuencia cardíaca de reposo más alta, por la hipertrofia"], c: 1, ex: "En reposo el gasto cardíaco lo fija la <b>demanda metabólica</b>, que es la misma para los dos. Como <b>GC = VS × FC</b> y el atleta tiene un volumen sistólico mucho mayor, la única forma de dar el mismo producto es <b>bajar la frecuencia</b>. <b>La bradicardia del atleta es una consecuencia aritmética, no una patología.</b> → Lo que sí tiene aumentado es la <b>reserva cardíaca</b> (gasto máximo menos gasto de reposo), que es la variable que decide el rendimiento. → <b>Las otras:</b> (A) Es el error que la pregunta busca: el gasto de reposo no sube, porque lo fija la demanda; con más volumen sistólico y la misma frecuencia daría más gasto, y por eso la frecuencia tiene que bajar. → (C) Al revés: el entrenamiento y la hipertrofia aumentan el volumen sistólico, y con menos volumen y más frecuencia el cuadro sería el de un corazón insuficiente. → (D) La hipertrofia del atleta va con bradicardia: si subieran los dos factores, el gasto de reposo sería mayor que la demanda."},
  {st: 'Un parche de miocardio bioingenierizado se implanta sobre una zona infartada. Además de ser contráctil, ¿qué requisito no negociable tiene que cumplir?', opts: ["Generar su propio sistema de conducción, independiente del receptor, para latir a un ritmo propio estable", "Acoplarse eléctricamente al miocardio receptor por uniones de hendidura, para no latir como un foco aislado", "Ser avascular, para no competir con el miocardio receptor por el flujo de las arterias coronarias", "Tener fibras multinucleadas con núcleos periféricos, para contraerse como el músculo esquelético"], c: 1, ex: "El miocardio funciona como <b>sincitio funcional</b> gracias a los <b>discos intercalares</b>, que tienen dos componentes distintos: <b>desmosomas</b> (unión mecánica) y <b>uniones de hendidura</b> (acople eléctrico). Si una fibra se despolariza, se despolarizan todas. Un parche contráctil que no se acople por uniones de hendidura late a su propio ritmo: eso es un <b>foco ectópico</b>, o sea un generador de arritmias implantado a propósito. → El otro dato central: <b>el músculo cardíaco no se repara</b> (carece de células madre y las fibras maduras no hacen mitosis), así que en el corazón <b>no sirve estimular la reparación endógena</b>: hay que aportar tejido. → <b>Las otras:</b> (A) Es exactamente lo que hay que evitar: un sistema de conducción propio e independiente genera un ritmo que compite con el del receptor, y el parche tiene que seguir al del corazón. → (C) Sin vascularización el parche no sobrevive más allá del límite de difusión. → (D) Esa descripción es la del músculo <b>esquelético</b>; la fibra cardíaca es <b>ramificada</b>, con uno o dos núcleos <b>centrales</b>."},
  // ANATOMIA-DOCENTE propias inicio
  {st: "Las cavidades nasales se comunican con la nasofaringe a través de…", opts: ["Las coanas.", "El istmo de las fauces.", "Las narinas.", "La glotis."], c: 0, ex: "Las <b>coanas</b> son los dos orificios posteriores de las cavidades nasales: dan a la nasofaringe. → <b>Las otras:</b> (B) El istmo de las fauces comunica la <b>boca</b> con la orofaringe. → (C) Las narinas son los orificios anteriores: comunican la nariz con el exterior. → (D) La glotis es el espacio entre los pliegues vocales, dentro de la laringe."},
  {st: "¿Cuál de los siguientes cartílagos de la laringe es par?", opts: ["Tiroides.", "Cricoides.", "Epiglotis.", "Aritenoides."], c: 3, ex: "Los <b>aritenoides</b> son dos, uno a cada lado, apoyados sobre el borde superior del cricoides; en ellos se inserta el extremo posterior de los pliegues vocales. También son pares los corniculados y los cuneiformes, mucho más chicos. → <b>Las otras:</b> los impares de la laringe son tres. (A) El tiroides, que forma la nuez. → (B) El cricoides, debajo del tiroides. → (C) La epiglotis, que tapa la entrada de la laringe al tragar."},
  {st: "El único cartílago de la vía aérea que forma un anillo completo es…", opts: ["El cricoides.", "El tiroides.", "El primer anillo traqueal.", "La epiglotis."], c: 0, ex: "El <b>cricoides</b> tiene forma de anillo de sello: un arco fino adelante y una lámina alta atrás. → <b>Las otras:</b> (B) El tiroides está abierto hacia atrás: son dos láminas unidas adelante. → (C) Los anillos de la tráquea tienen forma de C, abiertos hacia atrás, donde se apoya el esófago. → (D) La epiglotis es una lámina con forma de hoja, no un anillo."},
  {st: "Con respecto al bronquio principal derecho, señale la opción correcta.", opts: ["Es más largo y horizontal que el bronquio principal izquierdo.", "Es más vertical, corto y ancho que el bronquio principal izquierdo.", "Se divide en dos bronquios lobares, uno superior y otro inferior.", "Pasa por debajo del arco de la aorta antes de entrar al hilio."], c: 1, ex: "El bronquio principal <b>derecho</b> sigue casi la dirección de la tráquea: es más vertical, más corto y más ancho. Por eso lo que se aspira suele terminar en el pulmón derecho. → <b>Las otras:</b> (A) Eso describe al izquierdo, que es más largo y más horizontal porque tiene que rodear el corazón. → (C) El derecho da el lobar superior y el bronquio intermedio, que se divide en medio e inferior: <b>tres</b> lobares, uno por lóbulo; los dos lobares son los del izquierdo. → (D) El que pasa por debajo del arco de la aorta es el izquierdo; el derecho pasa por debajo del cayado de la vena ácigos."},
  {st: "La tráquea se relaciona, hacia atrás, con…", opts: ["El esófago.", "La glándula tiroides.", "El arco de la aorta.", "El esternón."], c: 0, ex: "El <b>esófago</b> baja pegado a la cara posterior de la tráquea: por eso los anillos traqueales están abiertos hacia atrás. → <b>Las otras:</b> (B) La tiroides abraza a la tráquea por <b>delante</b> y por los costados, en el cuello. → (C) El arco de la aorta pasa por delante y a la izquierda de la tráquea. → (D) El esternón está adelante, separado de la tráquea por los grandes vasos."},
  {st: "La pleura que está adherida a la superficie del pulmón y se mete en las fisuras es…", opts: ["La pleura costal.", "La pleura visceral.", "La pleura diafragmática.", "La pleura mediastínica."], c: 1, ex: "La pleura <b>visceral</b> recubre al pulmón y entra en las fisuras que separan los lóbulos. → <b>Las otras:</b> son partes de la pleura <b>parietal</b>, que tapiza lo que rodea al pulmón. (A) La costal, las costillas. → (C) La diafragmática, el diafragma. → (D) La mediastínica, el mediastino."},
  {st: "¿Cuál de las siguientes estructuras entra o sale del pulmón por el hilio?", opts: ["La vena cava superior.", "El bronquio principal.", "El esófago.", "El nervio frénico."], c: 1, ex: "Por el <b>hilio</b> pasan el <b>bronquio principal</b>, la arteria pulmonar y las dos venas pulmonares de ese lado. → <b>Las otras:</b> (A) La cava superior baja por el mediastino y desemboca en la aurícula derecha: no entra al pulmón. → (C) El esófago baja por detrás de la tráquea y del corazón. → (D) El frénico pasa por delante del hilio, pegado al pericardio, camino al diafragma."},
  {st: "Un segmento broncopulmonar…", opts: ["Recibe un bronquio segmentario y una rama arterial propia.", "Equivale a un lóbulo, con su bronquio lobar y su rama arterial.", "Queda separado de los segmentos vecinos por las fisuras del pulmón.", "Recibe un bronquio lobar y una rama propia de la arteria pulmonar."], c: 0, ex: "Cada <b>segmento</b> tiene su bronquio <b>segmentario</b> y su rama arterial: por eso se puede sacar uno solo sin tocar los demás. → <b>Las otras:</b> (B) Cada lóbulo contiene varios segmentos: el bronquio lobar ventila un lóbulo entero, no un segmento. → (C) Las fisuras separan <b>lóbulos</b>; entre segmentos sólo hay tabiques finos de tejido conectivo. → (D) El bronquio lobar ventila un lóbulo entero; el que llega al segmento es el segmentario."},
  {st: "A la aurícula derecha llega sangre desde…", opts: ["Las cuatro venas pulmonares y el seno coronario.", "Las venas cavas superior e inferior y el seno coronario.", "El tronco pulmonar y las venas pulmonares superiores.", "Las arterias coronarias y la aorta ascendente."], c: 1, ex: "La aurícula derecha recibe la sangre de todo el cuerpo por las dos <b>venas cavas</b>, y la del propio corazón por el <b>seno coronario</b>. → <b>Las otras:</b> (A) Las venas pulmonares llegan a la aurícula <b>izquierda</b>; sólo el seno coronario es correcto en esta opción. → (C) El tronco pulmonar <b>sale</b> del ventrículo derecho, y las venas pulmonares van a la aurícula izquierda. → (D) La aorta <b>sale</b> del ventrículo izquierdo, y las coronarias son arterias que nacen de ella: llevan sangre al miocardio, no a la aurícula."},
  {st: "La válvula que separa la aurícula derecha del ventrículo derecho es…", opts: ["La mitral.", "La tricúspide.", "La pulmonar.", "La aórtica."], c: 1, ex: "La <b>tricúspide</b> es la válvula aurículoventricular derecha, de tres valvas. → <b>Las otras:</b> (A) La mitral es la aurículoventricular <b>izquierda</b>, de dos valvas. → (C) La pulmonar está entre el ventrículo derecho y el tronco pulmonar. → (D) La aórtica está entre el ventrículo izquierdo y la aorta."},
  {st: "Las cuerdas tendinosas y los músculos papilares pertenecen a…", opts: ["Las válvulas tricúspide y mitral, auriculoventriculares", "Las válvulas aórtica y pulmonar, entre ventrículos y arterias", "El nodo sinusal, en la pared de la aurícula derecha", "El pericardio, el saco fibroseroso que envuelve al corazón"], c: 0, ex: "Las cuerdas tendinosas unen el borde de las valvas <b>aurículoventriculares</b> con los músculos papilares del ventrículo: impiden que las valvas se den vuelta hacia la aurícula. → <b>Las otras:</b> (B) La aórtica y la pulmonar son <b>semilunares</b>: tienen tres valvas con forma de bolsillo, sin cuerdas ni papilares. → (C) El nodo sinusal es tejido de conducción, un marcapasos sin relación con las válvulas. → (D) El pericardio es el saco que envuelve al corazón, por fuera de las cavidades."},
  {st: "El marcapasos normal del corazón es…", opts: ["El nodo aurículoventricular.", "El haz de His.", "El nodo sinusal.", "Las fibras de Purkinje."], c: 2, ex: "El <b>nodo sinusal</b>, en la pared de la aurícula derecha junto a la vena cava superior, es el que descarga más rápido y por eso marca el ritmo. → <b>Las otras:</b> (A) El aurículoventricular recibe el impulso y lo retrasa. → (B) El haz de His lo lleva a los ventrículos. → (D) Las fibras de Purkinje lo reparten por las paredes ventriculares."},
  {st: "Las arterias coronarias nacen de…", opts: ["El arco de la aorta, apenas después de la aorta ascendente.", "La aorta ascendente, apenas por encima de la válvula aórtica.", "El tronco pulmonar, apenas por encima de la válvula pulmonar.", "El tronco braquiocefálico, primera rama del arco de la aorta."], c: 1, ex: "Las coronarias derecha e izquierda son las <b>primeras ramas de la aorta</b>: nacen de la aorta ascendente, justo arriba de la válvula. → <b>Las otras:</b> (A) Del arco nacen el tronco braquiocefálico, la carótida común izquierda y la subclavia izquierda, no las coronarias. → (C) El tronco pulmonar lleva sangre pobre en oxígeno a los pulmones y no da coronarias. → (D) El braquiocefálico es una rama del arco que da la subclavia y la carótida común derechas."},
  {st: "El seno coronario desemboca en…", opts: ["La aurícula izquierda.", "La aurícula derecha.", "La vena cava superior.", "El ventrículo derecho."], c: 1, ex: "El <b>seno coronario</b> junta casi toda la sangre venosa del corazón y la vuelca en la <b>aurícula derecha</b>, igual que las dos cavas. → <b>Las otras:</b> (A) A la aurícula izquierda sólo llegan las venas pulmonares. → (C) No pasa por la cava: tiene su propio orificio en la aurícula. → (D) A los ventrículos la sangre entra desde las aurículas, por las válvulas."},
  {st: "¿Cuál de las siguientes arterias nace directamente del arco de la aorta?", opts: ["La arteria carótida externa izquierda.", "La arteria carótida común izquierda.", "La arteria carótida interna izquierda.", "La arteria carótida común derecha."], c: 1, ex: "Del arco de la aorta nacen tres ramas: el tronco braquiocefálico, la <b>carótida común izquierda</b> y la subclavia izquierda. → <b>Las otras:</b> (A) La carótida externa nace de la bifurcación de la carótida común, a la altura del borde superior del tiroides. → (C) La carótida interna también sale de esa bifurcación, no del arco. → (D) La carótida común derecha nace del tronco braquiocefálico, no del arco. Las coronarias, en cambio, nacen antes, de la aorta ascendente, y la arteria pulmonar izquierda es rama del tronco pulmonar."},
  {st: "El ligamento arterioso es el vestigio de…", opts: ["El foramen oval.", "La vena umbilical.", "El conducto arterioso.", "Las arterias umbilicales."], c: 2, ex: "En el feto, el <b>conducto arterioso</b> desvía la sangre del tronco pulmonar a la aorta, salteando los pulmones. Al nacer se cierra y queda el ligamento arterioso. → <b>Las otras:</b> (A) El foramen oval deja la fosa oval, en el tabique entre las aurículas. → (B) La vena umbilical deja el ligamento redondo del hígado. → (D) Las arterias umbilicales dejan los ligamentos umbilicales, en la pared del abdomen."},
  // ANATOMIA-DOCENTE propias fin
]);

// ---------- SECCIÓN 5 · REPASO RELÁMPAGO · DIGESTIVO Y URINARIO ----------
registerExercises('fiuba-anatomia-segundo-parcial', '5', [
  {st: 'El hígado, la vesícula biliar y el páncreas se clasifican como órganos accesorios del aparato digestivo porque:', opts: ["Su función es prescindible: el tubo digiere igual sin ellos, y ellos sólo lo ayudan", "El alimento no pasa por su interior: vuelcan sus secreciones al tubo por medio de conductos", "Derivan de una hoja embrionaria distinta de la del tubo digestivo, que es el endodermo", "Sólo actúan cuando la comida es abundante: el resto del tiempo permanecen inactivos"], c: 1, ex: "La clasificación es <b>topográfica</b>, no jerárquica: el <b>tubo digestivo</b> (boca, faringe, esófago, estómago, intestino delgado y grueso) es por donde <b>pasa</b> el alimento; los <b>accesorios</b> (glándulas salivales, hígado, vesícula y páncreas) lo procesan sin que el alimento pase por ellos, mandando secreciones por conductos; dientes y lengua también son accesorios pero sí lo contactan, y lo que los define es no formar parte del tubo. → Que sean accesorios no los hace secundarios: sin lipasa y sales biliares no se absorbe una gota de grasa. → <b>Las otras:</b> (A) Es falso que sean prescindibles: sin páncreas, bilis y lipasa no se absorbe la grasa; la clasificación es topográfica, no de importancia funcional. → (C) El hígado y el páncreas derivan del mismo endodermo del intestino anterior que el tubo: no tienen otro origen embrionario. → (D) Actúan siempre: el hígado produce bilis de forma continua, y lo que cambia con la comida es el ritmo de la secreción."},
  {st: 'Los tres niveles de amplificación de superficie del intestino delgado son, de mayor a menor escala:', opts: ["Pliegues circulares, haustros colónicos y microvellosidades", "Pliegues circulares, vellosidades y microvellosidades", "Vellosidades, glándulas de Brunner y microvellosidades", "Vellosidades, placas de Peyer y borde en cepillo apical"], c: 1, ex: "<b>Pliegues circulares</b> (milímetros, permanentes, de mucosa + submucosa) → <b>vellosidades</b> (0,5-1 mm, digitiformes, sólo mucosa, cada una con un asa capilar y un <b>vaso quilífero</b>) → <b>microvellosidades</b> (~1 µm, evaginaciones de la membrana apical del enterocito, el <b>borde en cepillo</b> con las enzimas de membrana ancladas). → Los tres niveles se <b>multiplican</b>, no se suman: el efecto total es el producto de los tres factores. Es el criterio de diseño de cualquier intercambiador: si hay que maximizar transferencia en un volumen dado, se estructura la superficie en <b>escalas anidadas</b>. → <b>Las otras:</b> (A) Los haustros son saculaciones del <b>intestino grueso</b>, y no amplifican superficie de absorción. → (C) Las glándulas de Brunner están en la submucosa del duodeno y secretan moco alcalino: no amplifican superficie. → (D) Las placas de Peyer son folículos linfoides inmunitarios, y el borde en cepillo es el mismo nivel de las microvellosidades, no uno distinto."},
  {st: 'En el lobulillo hepático, la sangre y la bilis circulan:', opts: ["En el mismo sentido: la sangre y la bilis van de la tríada portal hacia la vena centrolobulillar", "En sentidos opuestos: la sangre de la periferia al centro y la bilis del centro a la periferia", "En el mismo sentido: la sangre y la bilis van del centro del lobulillo a la periferia", "En sentidos opuestos: la sangre del centro a la periferia y la bilis de la periferia al centro"], c: 1, ex: "Es un <b>intercambiador a contracorriente</b> y una de las preguntas más rendidoras del tema, porque casi todo el mundo asume que van juntas. La <b>sangre</b> entra por la <b>tríada portal</b> de los vértices (rama de la arteria hepática + rama de la vena porta + conductillo biliar) y va hacia la <b>vena centrolobulillar</b>; la <b>bilis</b> se forma en el hepatocito, sale a los <b>canalículos biliares</b> entre células y va <b>del centro a la periferia</b>, hasta los conductillos de la tríada. → Es el mismo principio de flujos opuestos por tubos paralelos que aparece en el asa de Henle con los vasos rectos. → <b>Las otras:</b> (A) La sangre sí va de la tríada al centro, pero la bilis no la acompaña: va en sentido contrario. → (C) La bilis sí sale del centro a la periferia, pero la sangre hace el camino inverso. → (D) Invierte los dos sentidos: la sangre llega por la periferia y la bilis nace en el centro. Aparte: la <b>vesícula</b> no fabrica bilis, la <b>almacena y concentra</b>, y la vacía cuando la colecistocinina la contrae."},
  {st: 'Verdadero o falso: "las sales biliares digieren las grasas". Elegí la justificación correcta.', opts: ["Verdadero: son las enzimas que cortan los triglicéridos en ácidos grasos y monoglicéridos", "Falso: las sales biliares emulsionan (digestión mecánica); la que rompe los enlaces es la lipasa pancreática", "Falso: las grasas no se digieren, sino que las sales biliares las dejan listas para absorberse enteras", "Verdadero: la bilis contiene lipasa propia, que actúa en el duodeno junto con la pancreática"], c: 1, ex: "Las sales biliares <b>no tienen actividad enzimática</b>. Fragmentan los glóbulos de grasa en gotitas: eso es <b>digestión mecánica</b>, y lo que consigue es multiplicar el área de contacto para que la <b>lipasa pancreática</b>, que sí es la enzima, pueda trabajar. Es exactamente el mismo criterio que la superficie del intestino: si el proceso ocurre en una interfaz, aumentar la interfaz aumenta la velocidad. → <b>Las otras:</b> (A) Las sales biliares no son enzimas y no cortan ningún enlace: la que forma ácidos grasos y monoglicéridos es la lipasa pancreática. → (C) Las grasas sí se digieren: la lipasa las lleva a <b>ácidos grasos + monoglicéridos</b>, que viajan en <b>micelas</b> hasta el borde en cepillo, y no se absorben como triglicéridos enteros. → (D) La bilis no tiene enzimas de ningún tipo: su pigmento principal es la <b>bilirrubina</b>, producto de la degradación del hemo."},
  {st: 'Una diferencia clave en la absorción de nutrientes es que:', opts: ["Hidratos, aminoácidos y lípidos viajan juntos por la vena porta, y llegan al hígado en el primer pasaje", "Hidratos y aminoácidos van por la vena porta al hígado, y los lípidos van por la linfa como quilomicrones", "Los lípidos van por la vena porta al hígado, y hidratos y aminoácidos van por la linfa como quilomicrones", "Todo se absorbe por vía linfática: hidratos, aminoácidos y lípidos salen por el vaso quilífero"], c: 1, ex: "La asimetría es real y tiene consecuencia farmacológica directa. Monosacáridos y aminoácidos entran al <b>capilar</b> de la vellosidad y de ahí a la <b>vena porta</b>: <b>todo pasa primero por el hígado</b>. Los lípidos, en cambio, se resintetizan como triglicéridos dentro del enterocito, se empaquetan en <b>quilomicrones</b> y salen por el <b>vaso quilífero</b> (linfático), llegando a la circulación general por el conducto torácico y salteándose el primer pasaje hepático. → Por eso un fármaco liposoluble absorbido por vía linfática <b>escapa al efecto de primer paso hepático</b>. → Única excepción: los ácidos grasos de <b>cadena corta</b> van a la sangre portal. → <b>Las otras:</b> (A) Borra la asimetría: los lípidos no viajan por la porta sino por la linfa. → (C) Invierte las dos vías: son los hidratos y aminoácidos los que van a la sangre portal, y los quilomicrones son de lípidos. → (D) Los hidratos y aminoácidos son hidrosolubles y entran al capilar, no al quilífero."},
  {st: '¿Por qué las proteasas pancreáticas se secretan en forma de zimógenos inactivos?', opts: ["Porque activas se degradarían en el conducto: por eso se activan en el estómago con la pepsina", "Porque activas digerirían a la célula: se activan en el duodeno por la enterocinasa", "Porque necesitan el pH ácido del estómago para plegarse: se activan al mezclarse con el HCl", "Porque la bilis las inactiva durante el transporte: se activan cuando la bilis se diluye en el duodeno"], c: 1, ex: "Es el mismo principio de seguridad que en el estómago con el pepsinógeno: una enzima que rompe uniones peptídicas no puede fabricarse activa dentro de una célula hecha de proteínas. Tripsinógeno, quimotripsinógeno y procarboxipeptidasa salen como <b>zimógenos</b> y se activan en cascada <b>en la luz duodenal</b>: la enterocinasa convierte el tripsinógeno en tripsina y la tripsina activa al resto. Si se activan antes, eso es una <b>pancreatitis</b>. → <b>Las otras:</b> (A) El motivo no es proteger al conducto de la degradación, sino a la célula; y la activación no ocurre en el estómago ni la hace la pepsina, sino la enterocinasa duodenal. → (C) El jugo pancreático es <b>alcalino</b>: es rico en <b>bicarbonato</b> para neutralizar el quimo ácido y llevar el pH al rango de las enzimas intestinales; el HCl no las activa. → (D) La bilis y el jugo pancreático confluyen en la ampolla, pero la bilis no inactiva nada, y la activación depende de la enterocinasa, no de una dilución."},
  {st: 'Las glándulas de Brunner están en:', opts: ["La mucosa del estómago, y secretan ácido clorhídrico que activa el pepsinógeno gástrico", "La submucosa del duodeno, y secretan moco alcalino que neutraliza el quimo ácido", "La lámina propia del íleon, y secretan lisozima que destruye a las bacterias del lumen", "La submucosa del colon, y secretan enzimas que digieren las fibras vegetales"], c: 1, ex: "El <b>duodeno</b> es el <b>único tramo intestinal con glándulas en la submucosa</b>, y su ubicación tiene lógica: el quimo llega ácido desde el píloro y hay que neutralizarlo <b>apenas entra</b>, antes de que dañe la mucosa. Por eso el moco de Brunner es <b>alcalino</b>. → Comparación útil: el <b>esófago</b> también tiene glándulas en la submucosa, pero mucosas de lubricación; en el resto del intestino las glándulas son criptas de la <b>mucosa</b>. → <b>Las otras:</b> (A) El HCl lo secretan las células parietales de las glándulas gástricas, que no son las de Brunner. → (C) La <b>lisozima</b> y las defensinas las secretan las células de <b>Paneth</b>, en el <b>fondo de las criptas</b>. → (D) El colon no tiene glándulas submucosas ni secreta enzimas propias: la digestión química que ocurre ahí es <b>bacteriana</b>."},
  {st: 'Los riñones reciben el 20-25 % del gasto cardíaco pesando apenas unos 150 g. ¿Cómo se interpreta ese dato?', opts: ["Es un flujo de nutrición: el riñón consume mucho oxígeno y lo necesita para trabajar", "Es un flujo de procesamiento: el riñón filtra el plasma sin parar, no lo consume para vivir", "Es un flujo de reserva: el riñón almacena sangre para repartirla luego, y no procesa nada", "Es un flujo de regulación: el riñón sólo mide el volumen y devuelve la sangre sin modificarla"], c: 1, ex: "El riñón es un <b>órgano de proceso</b>: la sangre no pasa por ahí para alimentarlo, pasa para ser <b>filtrada</b>. De ahí salen ~<b>180 L/día</b> de filtrado, de los cuales se reabsorbe el <b>99 %</b>. → Y ese proceso tiene una arquitectura única: el glomérulo es la <b>única red capilar del cuerpo intercalada entre dos arteriolas</b>. Como la <b>eferente</b> es de menor diámetro que la <b>aferente</b>, funciona como un estrangulamiento a la salida y sostiene una <b>presión hidrostática glomerular alta</b>. En términos de diseño: es un circuito con una <b>válvula de entrada y otra de salida regulables por separado</b>, así que el riñón puede fijar la presión de filtración casi independientemente del flujo. → <b>Las otras:</b> (A) El riñón consume oxígeno, pero ese consumo es una fracción mínima de lo que le llega: el flujo no se explica por nutrición. → (C) El riñón no almacena sangre para repartirla: el reservorio son las <b>venas</b> (60-65 % del volumen) y el riñón procesa. → (D) El riñón no se limita a medir: procesa la sangre, ya que la filtra y modifica el filtrado, y no la devuelve igual."},
  {st: 'La membrana de filtración glomerular retiene la albúmina gracias sobre todo a:', opts: ["Las fenestraciones del endotelio capilar, de menos de 5 nm, junto con las hendiduras entre los pedicelos", "La lámina basal glomerular, barrera de tamaño y de carga negativa, junto con las hendiduras entre pedicelos", "El músculo liso de la cápsula de Bowman, que comprime el ovillo capilar y frena a las proteínas grandes", "El epitelio plano simple de la hoja parietal de la cápsula de Bowman, que atrapa a las proteínas grandes"], c: 1, ex: "Las tres capas, de la luz del capilar al espacio capsular: <b>1)</b> endotelio <b>fenestrado</b> de 70-100 nm, que frena células pero deja pasar todo el plasma; <b>2)</b> <b>lámina basal glomerular</b>, colágeno y proteoglucanos con <b>carga negativa</b>: barrera de <b>tamaño y de carga</b>, y la albúmina es aniónica, así que la repele; <b>3)</b> <b>hendiduras de filtración</b> entre los <b>pedicelos</b> de los podocitos, el filtro más fino. → La prueba experimental está en el paper del riñón bioingenierizado: el andamio <b>descelularizado</b>, que conserva la membrana basal pero no tiene podocitos, retiene sólo el <b>23 %</b> de la albúmina contra el 89,9 % del riñón entero. La membrana basal sola <b>no alcanza</b>. → <b>Las otras:</b> (A) Las fenestraciones miden 70-100 nm, mucho más que la albúmina, así que el endotelio no la retiene: el que frena es lo que viene después. → (C) La cápsula de Bowman no tiene músculo liso: es epitelio plano simple (parietal) y podocitos (visceral). → (D) La hoja parietal no filtra: la filtración ocurre a través de la pared del capilar, y la hoja parietal sólo reviste la cápsula."},
  {st: 'Verdadero o falso: "la secreción tubular es el paso de sustancias desde el filtrado hacia la sangre". Elegí la justificación.', opts: ["Verdadero: la secreción devuelve a la sangre lo que el filtrado todavía tiene de útil, como la glucosa y los aminoácidos", "Falso: eso es la reabsorción; la secreción va de la sangre al filtrado ya formado y elimina H+, K+ y fármacos", "Falso: eso es la filtración; la secreción ocurre sólo en el glomérulo y elimina H+, K+ y fármacos del plasma sanguíneo", "Verdadero: es el mismo proceso que la reabsorción, y ocurre sobre todo en el túbulo contorneado proximal del nefrón"], c: 1, ex: "Los tres procesos hay que tenerlos separados por su <b>dirección</b>: <b>filtración</b> (sangre → espacio capsular, en el corpúsculo), <b>reabsorción</b> (filtrado → sangre, sobre todo en el TCP) y <b>secreción</b> (sangre → filtrado <b>ya formado</b>, en túbulo y colector). → El truco de lectura es <b>ya formado</b>: si la sustancia ingresa a un líquido que ya está en el túbulo, es secreción, aunque venga de la sangre igual que en la filtración. → Balance final: <b>excreción = filtrado − reabsorbido + secretado</b>. → <b>Las otras:</b> (A) Eso que describe es la reabsorción: la glucosa vuelve a la sangre por reabsorción, y la secreción hace lo contrario. → (C) La filtración sí es sangre → espacio capsular, pero ocurre en el glomérulo y no es la secreción, que se da en el túbulo y el colector, sobre filtrado ya formado. → (D) Secreción y reabsorción son procesos distintos, de sentidos opuestos. → Nota clínica que sale de acá: la hemodiálisis reproduce <b>sólo la filtración</b> y no hace ni reabsorción selectiva ni secreción."},
  {st: 'Un paciente en hemodiálisis crónica sigue anémico y con trastorno mineral óseo pese a estar bien dializado. ¿Por qué?', opts: ["Porque la diálisis elimina demasiada urea, y eso deprime la producción de eritropoyetina y calcitriol", "Porque la diálisis sólo reproduce la filtración: no fabrica eritropoyetina ni calcitriol, que dependen de células", "Porque el filtro retiene el hierro y el calcio de la dieta, que no llegan a formar glóbulos rojos ni hueso", "Porque la membrana es fenestrada y deja escapar la eritropoyetina y el calcitriol junto con el ultrafiltrado"], c: 1, ex: "Una membrana semipermeable <b>acelular</b> puede separar por tamaño, y nada más. Le faltan las tres funciones que dependen de <b>células</b>: la <b>reabsorción selectiva</b> (no distingue glucosa de urea, porque eso lo hacen transportadores de membrana del epitelio tubular polarizado), la <b>secreción</b> tubular, y la función <b>endócrina</b>: <b>eritropoyetina</b> (de ahí la anemia) y <b>calcitriol</b> (de ahí el trastorno mineral óseo, porque sin vitamina D activa no se absorbe calcio). → Ese vacío es el argumento entero del paper de riñón bioingenierizado que da la cátedra: un injerto que reemplace de verdad al riñón tiene que permitir <b>perfusión, filtración, secreción, absorción y drenaje de orina</b>. → <b>Las otras:</b> (A) Eliminar urea es el objetivo, no el problema, y no deprime esas hormonas: el déficit es porque el riñón que las hacía ya no está. → (C) El filtro no retiene nutrientes de la dieta, que ni siquiera pasan por él: la dieta se absorbe en el intestino. → (D) La membrana de diálisis es sintética; fenestrado es una categoría de capilares biológicos, y las hormonas no son lo que falta por escape."},
  {st: 'La renina, en el sistema renina-angiotensina-aldosterona:', opts: ["Es una hormona de las células yuxtaglomerulares de la arteriola aferente, que se convierte en angiotensina I", "Es una enzima de las células yuxtaglomerulares de la arteriola aferente, que actúa sobre el angiotensinógeno hepático", "Es una enzima de las células de la mácula densa del túbulo distal, que actúa sobre el angiotensinógeno hepático", "Es una hormona de la corteza suprarrenal, que actúa sobre el angiotensinógeno renal para dar aldosterona"], c: 1, ex: "El circuito completo: caída de volumen o presión → las <b>células yuxtaglomerulares</b> (músculo liso modificado de la <b>arteriola aferente</b>) detectan menos estiramiento y secretan <b>renina</b> → la renina, que es una <b>enzima</b>, actúa sobre el <b>angiotensinógeno</b> del <b>hígado</b> → <b>angiotensina I</b> → la <b>ECA de los pulmones</b> la convierte en <b>angiotensina II</b> → vasoconstricción + sed + <b>ADH</b> + <b>aldosterona</b> → se reabsorben Na⁺ y agua y se secretan K⁺ y H⁺ → sube la volemia y la presión. → <b>Ojo:</b> el texto de una diapositiva de la cátedra dice que la renina se convierte en angiotensina I y ubica las células yuxtaglomerulares en el túbulo contorneado distal. El <b>esquema de esa misma clase</b> muestra lo correcto, que es lo de arriba. → <b>Las otras:</b> (A) La renina no se convierte en angiotensina I: es la enzima que la genera a partir del angiotensinógeno. → (C) La <b>mácula densa</b> sí está en el túbulo, pero es el <b>sensor de NaCl</b>, no la que secreta renina. → (D) La renina la produce el riñón, no la corteza suprarrenal; de la corteza sale la aldosterona, y el angiotensinógeno es hepático."},
  // ANATOMIA-DOCENTE propias inicio
  {st: "El esófago atraviesa el diafragma y termina en…", opts: ["El píloro.", "El cardias.", "El fundus gástrico.", "El duodeno."], c: 1, ex: "El <b>cardias</b> es el orificio de entrada del estómago: ahí termina el esófago. → <b>Las otras:</b> (A) El píloro es la <b>salida</b> del estómago. → (C) El fundus es la cúpula del estómago, que queda por encima del cardias. → (D) El duodeno viene después del estómago."},
  {st: "¿Cuál es el orden correcto de las porciones del intestino delgado?", opts: ["Yeyuno, duodeno, íleon.", "Duodeno, íleon, yeyuno.", "Duodeno, yeyuno, íleon.", "Íleon, yeyuno, duodeno."], c: 2, ex: "Después del píloro viene el <b>duodeno</b>, después el <b>yeyuno</b> y al final el <b>íleon</b>, que desemboca en el ciego. → <b>Las otras:</b> (A) El duodeno es el primero, no el segundo. → (B) Invierte yeyuno e íleon. → (D) Es el orden al revés."},
  {st: "El conducto colédoco se forma por la unión de…", opts: ["Los conductos hepáticos derecho e izquierdo.", "El conducto hepático común y el conducto cístico.", "El conducto cístico y el conducto pancreático.", "El conducto hepático común y el conducto pancreático."], c: 1, ex: "El <b>hepático común</b> baja del hígado, el <b>cístico</b> viene de la vesícula, y donde se juntan empieza el <b>colédoco</b>. → <b>Las otras:</b> (A) Esos dos forman el hepático común, un paso antes. → (C) El cístico no se une al pancreático. → (D) El pancreático se suma recién al final, junto al duodeno: se une con el colédoco ya formado."},
  {st: "La cabeza del páncreas se relaciona con…", opts: ["El hilio del bazo.", "El duodeno, que la rodea.", "La curvatura mayor del estómago.", "El colon sigmoides."], c: 1, ex: "La <b>cabeza</b> del páncreas queda encajada en la C que forma el <b>duodeno</b>. → <b>Las otras:</b> (A) Hacia el bazo va la <b>cola</b>, el extremo opuesto. → (C) El páncreas está por detrás del estómago, no colgado de su curvatura mayor (de ahí cuelga el omento mayor). → (D) El sigmoides está en la pelvis, lejos del páncreas."},
  {st: "El apéndice vermiforme se implanta en…", opts: ["El íleon.", "El ciego.", "El colon sigmoides.", "El recto."], c: 1, ex: "El <b>apéndice</b> es un tubo fino que cuelga del <b>ciego</b>, cerca de donde entra el íleon. → <b>Las otras:</b> (A) El íleon desemboca en el ciego, pero el apéndice no sale de él. → (C) El sigmoides está del lado izquierdo; el apéndice, del derecho. → (D) El recto es el tramo final, en la pelvis."},
  {st: "La vena porta lleva al hígado…", opts: ["Sangre oxigenada que llega desde la aorta, por la arteria hepática propia.", "Sangre que viene del tubo digestivo, el bazo y el páncreas.", "Bilis que viene de la vesícula, por el conducto cístico, hacia el hígado.", "Sangre que viene de los riñones y las suprarrenales, hacia el hígado."], c: 1, ex: "La <b>vena porta</b> junta la sangre del tubo digestivo, el bazo y el páncreas y la lleva al hígado antes de que pase al resto del cuerpo. → <b>Las otras:</b> (A) La sangre oxigenada llega al hígado por la arteria hepática, no por la porta. → (C) La bilis no viaja por vasos sino por conductos, y en sentido contrario: del hígado hacia el duodeno. → (D) Las venas renales, suprarrenales y gonadales desembocan en la cava inferior, no en la porta."},
  {st: "¿Cuál de las siguientes glándulas salivales es la de mayor tamaño?", opts: ["La sublingual.", "La submandibular.", "La parótida.", "Las glándulas del paladar."], c: 2, ex: "La <b>parótida</b> es la mayor de los tres pares de glándulas salivales: está delante y debajo de la oreja. → <b>Las otras:</b> (A) La sublingual es la más chica de las tres, bajo la lengua. → (B) La submandibular es intermedia, debajo de la mandíbula. → (D) Las del paladar son glándulas salivales menores, diminutas."},
  {st: "¿Cuál de los siguientes tramos del intestino grueso se continúa directamente con el recto?", opts: ["El colon descendente.", "El colon transverso.", "El colon sigmoides.", "El ciego."], c: 2, ex: "Orden del intestino grueso: ciego, colon ascendente, transverso, descendente, <b>sigmoides</b>, <b>recto</b> y conducto anal. → <b>Las otras:</b> (A) El descendente se continúa con el sigmoides. → (B) El transverso, con el descendente. → (D) El ciego es el primer tramo, del lado derecho."},
  {st: "Los riñones se ubican…", opts: ["Dentro de la cavidad peritoneal, por delante del estómago.", "En el retroperitoneo, a los lados de la columna vertebral.", "En la pelvis, por detrás de la vejiga.", "En el mediastino, por detrás del corazón."], c: 1, ex: "Los riñones son <b>retroperitoneales</b>: están contra la pared posterior del abdomen, a los lados de la columna, entre T12 y L3. El derecho queda un poco más bajo, por el hígado. → <b>Las otras:</b> (A) No están dentro del peritoneo sino por detrás. → (C) En la pelvis está la vejiga; los riñones están más arriba. → (D) El mediastino es del tórax."},
  {st: "En el hilio renal se encuentran, de adelante hacia atrás…", opts: ["Pelvis renal, arteria renal y vena renal.", "Arteria renal, vena renal y pelvis renal.", "Vena renal, arteria renal y pelvis renal.", "Vena renal, pelvis renal y arteria renal."], c: 2, ex: "El orden de adelante hacia atrás es <b>vena, arteria, pelvis</b>. → <b>Las otras:</b> (A) Es el orden al revés: la pelvis renal es lo más posterior. → (B) La vena va por delante de la arteria. → (D) La pelvis queda atrás de todo, no en el medio."},
  {st: "La punta de cada pirámide renal vuelca la orina en…", opts: ["Un cáliz mayor.", "Un cáliz menor.", "La pelvis renal.", "El uréter."], c: 1, ex: "La punta de la pirámide es la <b>papila</b>, y cada papila se abre en un <b>cáliz menor</b>. → <b>Las otras:</b> (A) Los cálices mayores se forman por la unión de varios menores. → (C) La pelvis renal se forma por la unión de los cálices mayores. → (D) El uréter es la continuación de la pelvis."},
  {st: "El uréter desemboca en…", opts: ["La pelvis renal.", "La uretra.", "La vejiga.", "El recto."], c: 2, ex: "Cada <b>uréter</b> baja del riñón y entra en la <b>vejiga</b> por atrás; sus dos orificios son los vértices posteriores del trígono. → <b>Las otras:</b> (A) En la pelvis renal el uréter <b>nace</b>. → (B) La uretra sale de la vejiga hacia el exterior: el uréter no llega a ella. → (D) El recto es del tubo digestivo."},
  {st: "El trígono vesical está delimitado por…", opts: ["Los dos orificios ureterales y el orificio interno de la uretra.", "Los dos orificios ureterales y los orificios de los conductos eyaculadores.", "Los dos orificios ureterales y el orificio externo de la uretra.", "Los dos orificios ureterales y la inserción del uraco en el vértice."], c: 0, ex: "El <b>trígono</b> es el triángulo liso del piso de la vejiga: atrás, los dos orificios por donde entran los uréteres; adelante, el orificio interno por donde sale la uretra. → <b>Las otras:</b> (B) Los conductos eyaculadores desembocan en la uretra prostática, debajo de la vejiga, no en su piso. → (C) El orificio externo de la uretra está en el extremo distal de la uretra, lejos de la vejiga: el vértice anterior del trígono es el orificio interno. → (D) El uraco (ligamento umbilical medio) se inserta en el vértice superior de la vejiga, fuera del trígono."},
  {st: "¿Cuál es el orden correcto de las porciones de la uretra masculina, desde la vejiga?", opts: ["Esponjosa, membranosa, prostática.", "Prostática, membranosa, esponjosa.", "Membranosa, prostática, esponjosa.", "Prostática, esponjosa, membranosa."], c: 1, ex: "Al salir de la vejiga la uretra atraviesa la próstata (<b>prostática</b>), después el piso de la pelvis (<b>membranosa</b>, la más corta) y por último recorre el pene (<b>esponjosa</b>). → <b>Las otras:</b> (A) Es el orden al revés. → (C) La próstata está pegada a la vejiga: la prostática va primero. → (D) La membranosa queda en el medio, entre las otras dos."},
  {st: "La vena renal izquierda, en su camino hacia la vena cava inferior…", opts: ["Pasa por detrás de la aorta.", "Pasa por delante de la aorta.", "Desemboca en la vena renal derecha.", "Desemboca en la vena porta."], c: 1, ex: "La cava inferior está a la derecha de la línea media, así que la vena renal <b>izquierda</b> es más larga y cruza <b>por delante de la aorta</b> para alcanzarla. → <b>Las otras:</b> (A) Lo normal es que cruce por delante de la aorta; lo que pasa por detrás de un gran vaso es la <b>arteria</b> renal derecha, que va por detrás de la cava. → (C) Cada vena renal desemboca por separado en la cava. → (D) La porta no recibe sangre de los riñones."},
  {st: "En la pelvis femenina, de adelante hacia atrás, se encuentran…", opts: ["El recto, el útero y la vagina, y luego la vejiga.", "La vejiga, el útero con la vagina y luego el recto.", "El útero, la vagina, la vejiga y luego el recto.", "La vejiga, el recto y luego el útero y la vagina."], c: 1, ex: "Detrás del pubis está la <b>vejiga</b> (con la uretra debajo), después el <b>útero y la vagina</b>, y atrás de todo el <b>recto</b>. → <b>Las otras:</b> (A) Es el orden al revés. → (C) El útero no es lo más anterior: se apoya sobre la vejiga, por detrás. → (D) El recto es lo más posterior, pegado al sacro: no queda entre la vejiga y el útero."},
  // ANATOMIA-DOCENTE propias fin
]);

// ---------- SECCIÓN 6 · REPASO RELÁMPAGO · ENDÓCRINO Y NERVIOSO ----------
registerExercises('fiuba-anatomia-segundo-parcial', '6', [
  {st: '¿Cuántas hormonas produce la adenohipófisis y cuáles son?', opts: ["Dos: ADH y oxitocina, almacenadas en el tallo", "Siete: GH, prolactina, TSH, ACTH, FSH, LH y MSH", "Siete: GH, TSH, ACTH, FSH, LH, MSH y oxitocina", "Nueve: las siete más la TRH y la GnRH"], c: 1, ex: "Son <b>siete</b>, y las dos que más se olvidan al contar son la <b>prolactina</b> y sobre todo la <b>MSH</b> (hormona melanocito-estimulante), cuyo blanco son los <b>melanocitos</b> de la piel y cuyo efecto es la producción de <b>melanina</b>. → <b>Las otras:</b> (A) ADH y oxitocina son <b>neurohipofisarias</b>, y ni siquiera se producen ahí: las sintetizan los núcleos <b>supraóptico y paraventricular</b> del hipotálamo, bajan por el tallo dentro de los axones y la neurohipófisis sólo las almacena y libera. Es tejido <b>nervioso</b>, no glandular. → (C) La oxitocina la sintetiza el hipotálamo y la libera la neurohipófisis, no la adenohipófisis; la que falta en esta lista es la <b>prolactina</b>. → (D) La TRH y la GnRH son hipotalámicas, de otro piso del eje: las libera el hipotálamo y las produce él, no la adenohipófisis."},
  {st: 'La distinción entre hormonas TRÓFICAS y GONADOTROFINAS es:', opts: ["Tróficas son las que estimulan la gónada (FSH y LH); gonadotrofinas son las que estimulan otras glándulas endócrinas (TSH y ACTH)", "Tróficas son las que estimulan otras glándulas (TSH y ACTH); gonadotrofinas son las que tienen la gónada como blanco (FSH y LH)", "Son sinónimos: ambas estimulan otras glándulas endócrinas, y por eso TSH, ACTH, FSH y LH son todas gonadotrofinas", "Tróficas son las que tienen a la gónada como blanco (FSH y LH); gonadotrofinas son las de la neurohipófisis (ADH y oxitocina)"], c: 1, ex: "Es <b>el</b> distractor del banco de parciales, y aparece en las <b>dos</b> preguntas de gonadotrofinas que publicó la cátedra. La clase define las <b>trópicas/tróficas</b> como las que \"tienen efecto estimulante sobre otras glándulas endócrinas\": <b>TSH</b> (tiroides) y <b>ACTH</b> (corteza suprarrenal). Las <b>gonadotrofinas</b> son <b>FSH</b> y <b>LH</b>, \"porque estimulan el crecimiento y mantenimiento de las gónadas\". → <b>Las otras:</b> (A) No es falsa en lo que dice: es una definición <b>correcta</b> puesta en el casillero equivocado. Confunde el <b>género</b> (trofinas) con la <b>especie</b> (gonadotrofinas). Etimología que resuelve la pregunta sola: <b>gonado-trofina</b> = gónada + <i>trofos</i> (nutrir, hacer crecer). → (C) No son sinónimos: sólo FSH y LH tienen a la gónada como blanco, y TSH y ACTH actúan sobre tiroides y suprarrenal. → (D) ADH y oxitocina no son gonadotrofinas: actúan sobre túbulo colector y músculo liso uterino/mioepitelio mamario; además la definición de trófica que se da es la de las gonadotrofinas."},
  {st: 'Además de la producción de leche, la prolactina tiene un efecto fisiológico que la cátedra toma explícitamente. ¿Cuál?', opts: ["Estimula la síntesis proteica y el crecimiento óseo a través de la IGF-1 hepática", "Aumenta la liberación de tiroxina al estimular las células foliculares", "Inhibe la GnRH y con ella FSH y LH, base de la amenorrea de la lactancia", "Activa la adenilato ciclasa y el AMPc como segundo mensajero en la célula blanco"], c: 2, ex: "La prolactina tiene un efecto <b>antigonadotrófico</b>: <b>suprime la ovulación</b>, porque inhibe la liberación pulsátil de <b>GnRH</b> hipotalámica, con lo cual caen FSH y LH y no hay pico ovulatorio. Es el mecanismo de la amenorrea de la lactancia. Su secreción es pulsátil con máximo durante el <b>sueño</b>, y el estímulo de succión la sube todavía más. → Es un ejemplo lindo de integración: una hormona hipofisaria que actúa <b>río arriba</b>, sobre el hipotálamo, para apagar otro eje. → <b>Las otras:</b> (A) Es el efecto de la <b>GH</b> vía IGF-1; comparte con la prolactina el pico nocturno, lo que hace al distractor razonable. → (B) Es el efecto de la <b>TSH</b>, no de la prolactina. → (D) Confunde el nivel de análisis (un mecanismo intracelular no es un \"efecto fisiológico\") y encima es incorrecto: el receptor de prolactina no señaliza por AMPc sino por la vía JAK2-STAT5."},
  {st: 'La cresta neural da origen a:', opts: ["Neuronas motoras de la médula espinal, astrocitos, oligodendrocitos y células ependimarias del encéfalo", "Neuronas de ganglios sensitivos y autónomos, células de Schwann, melanocitos y médula suprarrenal", "Neuronas de ganglios sensitivos, células de Schwann, microglía, melanocitos y médula suprarrenal del adulto", "Neuronas de ganglios autónomos, células de Schwann, melanocitos y la corteza suprarrenal del adulto"], c: 1, ex: "La división embriológica es limpia: <b>tubo neural → SNC</b> (encéfalo y médula) y <b>cresta neural → SNP</b>. La cresta es un caso raro: se desprende del borde del tubo, <b>migra por todo el embrión</b> y da neuronas sensitivas de los ganglios raquídeos, ganglios autónomos, <b>células de Schwann</b>, <b>células satélite</b>, melanocitos y la <b>médula suprarrenal</b> (que por eso se comporta como un ganglio simpático modificado). → Consecuencia práctica: si necesitás células de Schwann para un conducto de guía nerviosa, estás pidiendo derivados de <b>cresta neural</b>, no de tubo neural. → <b>Las otras:</b> (A) Son todos derivados del <b>tubo neural</b> (SNC): neuronas del encéfalo y la médula, astrocitos, oligodendrocitos y ependimocitos. → (C) La <b>microglía</b> es la excepción: viene de la <b>médula ósea</b> (mesodermo), ni del tubo ni de la cresta. → (D) La <b>corteza</b> suprarrenal es de origen mesodérmico; de la cresta es la <b>médula</b>."},
  {st: 'El SNA (sistema nervioso autónomo) es:', opts: ['Una tercera división, al mismo nivel que el SNC y el SNP', 'Una subdivisión del SNP, junto con el somático', 'Parte del SNC, porque sus centros están en el tronco encefálico', 'Sinónimo de sistema nervioso entérico'], c: 1, ex: 'El esquema correcto es: <b>SNC</b> (encéfalo + médula espinal) y <b>SNP</b> (nervios craneales y espinales, ganglios y plexos), y el SNP se divide en <b>somático</b> (voluntario, músculo esquelético) y <b>autónomo</b> (involuntario), que a su vez tiene simpático (salida <b>toracolumbar</b>), parasimpático (salida <b>craneal y sacra</b>) y entérico. → Una lámina de la cátedra habla de "la división en SNP y SNA" como si fueran paralelos, pero <b>dos renglones después dice lo correcto</b>. Quedate con el esquema. → Segundo error de la misma familia: meter la <b>médula espinal</b> dentro del SNP. La médula es <b>SNC</b>; lo periférico son los <b>nervios raquídeos</b> que salen de ella. → (D) El entérico es sólo <b>una</b> de las tres ramas del autónomo.'},
  {st: 'Un enunciado describe una prolongación neuronal de "diámetro constante, con ramificaciones escasas en ángulo recto y sin grumos de Nissl". ¿Qué es?', opts: ["Una dendrita, porque la ramificación y el ángulo recto son rasgos propios de las dendritas", "Un axón, porque el diámetro constante, el ángulo recto y la falta de Nissl son rasgos axonales", "Un pedicelo, porque es una prolongación fina de diámetro constante y ángulo recto", "Una espina dendrítica, porque es una prolongación corta de diámetro constante y sin Nissl"], c: 1, ex: "Los tres rasgos son de <b>axón</b>: diámetro <b>constante</b>, ramificaciones <b>pocas y en ángulo recto</b>, y <b>sin</b> grumos de Nissl ni espinas. Las <b>dendritas</b> son numerosas, de diámetro <b>variable</b>, se ramifican mucho y en <b>ángulo agudo</b>, y sí tienen Nissl y espinas. → La trampa es que \"se ramifica\" suena a dendrita: lo que define es el <b>ángulo</b> y la <b>constancia del diámetro</b>. → Y no confundas los extremos: <b>cono axónico = inicio</b> (nace del soma), <b>telodendrón = final</b> (arborización terminal). Invertirlos es el error más barato del tema. → <b>Las otras:</b> (A) La dendrita se ramifica mucho y en ángulo agudo, tiene diámetro variable y sí tiene grumos de Nissl: el ángulo recto no es dendrítico. → (C) El <b>pedicelo</b> es un pie del podocito renal, no una estructura neuronal. → (D) La <b>espina dendrítica</b> es una saliente corta de la dendrita, no una prolongación larga con ramificaciones."},
  {st: '¿Qué funciones se localizan predominantemente en el lóbulo temporal?', opts: ["Planificación, juicio e inhibición del comportamiento, junto con el área de Broca", "Audición, comprensión del lenguaje (área de Wernicke) y formación de la memoria", "Coordinación de movimientos voluntarios, equilibrio y control del tono muscular postural", "Procesamiento somatosensorial, cálculo matemático y orientación espacial"], c: 1, ex: "El temporal aloja la <b>corteza auditiva primaria</b>, el <b>área de Wernicke</b> (porción posterior de la circunvolución temporal superior del hemisferio dominante: <b>comprensión</b> del lenguaje) y, en su cara medial, el <b>hipocampo</b> y la amígdala, responsables de la consolidación de la memoria. → <b>Las otras:</b> (A) Son funciones <b>prefrontales</b>: funciones ejecutivas, juicio e inhibición de respuestas. El frontal tiene además el <b>área de Broca</b>, que es <b>producción</b> del lenguaje: si el enunciado dice \"entiende pero no logra formar las palabras\", es <b>Broca</b>. → (C) Es el <b>cerebelo</b>, que además <b>no es un lóbulo cortical</b>. La cátedra usa exactamente este distractor en la pregunta real, así que leé el sustantivo del enunciado, no sólo la función. → (D) Es el <b>parietal</b>: circunvolución poscentral, somatosensorial."},
  {st: 'Tálamo, hipotálamo y ganglios basales se confunden. La asignación correcta es:', opts: ["Tálamo: funciones vitales y control endócrino · hipotálamo: relevo sensorial hacia la corteza · ganglios basales: movimiento voluntario fino", "Tálamo: relevo sensorial hacia la corteza · hipotálamo: funciones vitales y control endócrino · ganglios basales: movimiento voluntario", "Tálamo: relevo sensorial hacia la corteza · hipotálamo: funciones vitales y control endócrino · ganglios basales: equilibrio y tono postural", "Tálamo: relevo sensorial hacia la corteza · hipotálamo: movimiento voluntario fino · ganglios basales: funciones vitales y control endócrino"], c: 1, ex: "Tres estructuras profundas con tres funciones distintas y dos pertenencias distintas: <b>tálamo</b> e <b>hipotálamo</b> son <b>diencéfalo</b>; los <b>ganglios basales</b> (caudado, putamen, pálido) son <b>telencéfalo</b>. El tálamo es la estación de relevo sensorial hacia la corteza; el hipotálamo regula las funciones vitales (temperatura, FC, presión, apetito); los ganglios basales intervienen en el movimiento voluntario y su coordinación. → El hipotálamo es además el <b>puente con el sistema endócrino</b>: es donde se sintetizan ADH y oxitocina y donde se generan las hormonas liberadoras que controlan la adenohipófisis. → <b>Las otras:</b> (A) Invierte tálamo e hipotálamo. → (C) El equilibrio y el tono postural dependen del <b>cerebelo</b> y del sistema vestibular, no de los ganglios basales. Y recordá que el tronco encefálico son <b>tres</b> piezas (mesencéfalo, protuberancia y bulbo): ninguna de estas tres estructuras es tronco, y el <b>cerebelo NO forma parte del tronco</b>. → (D) Cambia el hipotálamo por los ganglios basales: el movimiento voluntario no es del hipotálamo y las funciones vitales no son de los ganglios basales."},
  {st: 'Sobre la acción del sistema nervioso autónomo en la vejiga:', opts: ["El simpático contrae el detrusor y relaja el esfínter interno; el parasimpático lo relaja", "El parasimpático contrae el detrusor y relaja el esfínter interno; el simpático al revés", "El parasimpático relaja el detrusor y contrae el esfínter interno; el simpático hace lo inverso", "Ambos contraen el detrusor; el parasimpático relaja el esfínter interno y el simpático lo contrae"], c: 1, ex: "Vejiga y recto van <b>cruzados</b> respecto de la intuición de \"el simpático contrae todo\". El <b>parasimpático contrae el detrusor</b> y relaja el esfínter interno: por eso la micción es un reflejo espinal <b>sacro</b> parasimpático. El simpático hace lo inverso. → Anclaje: en modo <i>luchar o huir</i> no conviene ni orinar ni digerir, así que el simpático <b>retiene</b> (relaja el detrusor, contrae el esfínter interno de la vejiga, inhibe la motilidad rectal y mantiene cerrado el esfínter anal interno) y además <b>dilata los bronquios</b> para entrar más aire. → Ojo con la asimetría vecina: la inervación del <b>riñón</b> es <b>simpática</b> y el parasimpático no regula sus funciones; la de la <b>vejiga</b> sí es parasimpática fuerte. → <b>Las otras:</b> (A) Aplica la regla de \"la mayoría de los órganos\" (simpático contrae, parasimpático relaja) y deja la vejiga al revés: en la vejiga el que vacía es el parasimpático. → (C) Invierte los dos efectos: el parasimpático contrae el detrusor y relaja el esfínter, que es lo que permite orinar. → (D) Es falso que ambos contraigan el detrusor: el simpático lo relaja y contrae el esfínter interno, por eso retiene. El único componente somático es el <b>esfínter externo</b>, de músculo esquelético y control voluntario."},
  {st: 'En el estudio del constructo ovárico (cHRT), ¿por qué el estradiol se cayó a partir del día 40 en los constructos entrecruzados con calcio?', opts: ["Porque el Ca2+ liberado por el gel resultó tóxico para las células de la teca y las fue eliminando de a poco", "Porque el alginato entrecruzado con Ca2+ se mineralizó con el tiempo y la calcificación comprometió la difusión", "Porque el epiplón montó una respuesta inflamatoria que encapsuló el constructo e impidió la difusión", "Porque la granulosa se luteinizó de forma prematura y dejó de aromatizar andrógenos a estradiol"], c: 1, ex: "El modo de falla es <b>del material, no de las células</b>. El alginato gelifica por entrecruzamiento iónico con cationes divalentes, y el estándar es el Ca²⁺; el problema es que en un medio fisiológico rico en fosfato ese calcio precipita y el constructo <b>se mineraliza</b>. La cápsula endurecida bloquea la difusión de nutrientes, O<sub>2</sub> y hormona hacia afuera, y la secreción se cae, comprometiendo la función sostenida. El <b>Sr²⁺</b> entrecruza igual de bien y no participa de la mineralización de la misma manera: con Sr²⁺ el E<sub>2</sub> se mantiene estable los 90 días. → <b>Las otras:</b> (A) El Ca²⁺ es un ion fisiológico ubicuo y el entrecruzante estándar precisamente por su biocompatibilidad; además, la <b>LH sostenida</b> indica que la teca seguía funcionando. → (C) Los constructos explantados mostraron <b>mínima encapsulación fibrosa</b> y epiplón bien vascularizado. → (D) Es el distractor más fino, porque la luteinización es un fenómeno real del ovario, pero que el E<sub>2</sub> fuera <b>estable</b> con Sr²⁺ indica justamente que <b>no</b> hubo luteinización."},
  {st: 'La lógica de fondo de la terapia hormonal celular (cHRT) frente al reemplazo farmacológico (pHRT) es:', opts: ["Que las células implantadas producen la hormona a menor costo, mientras que un pellet obliga a reponerlo cada pocas semanas con una nueva cirugía", "Que las células implantadas quedan dentro del lazo del eje y regulan su producción, mientras que un pellet libera una dosis fija", "Que las células implantadas sobreviven sin vascularización, mientras que un pellet depende de una irrigación abundante", "Que el alginato libera estradiol a velocidad constante, mientras que un pellet responde a las gonadotrofinas circulantes"], c: 1, ex: "Es el argumento de <b>teoría de control</b> del paper, y es lo que lo conecta con la sección de los ejes. Un pellet farmacológico es un <b>lazo abierto</b>: libera la dosis programada sin importar qué pasa río arriba, pase lo que pase. Un constructo con <b>granulosa y teca</b> encapsuladas responde a las gonadotrofinas circulantes y devuelve hormona en función de ellas: queda <b>dentro del lazo de realimentación hipotálamo-hipófisis-ovario</b>, y por eso puede conseguir el efecto biológico con <b>niveles plasmáticos más bajos</b>. En el estudio, eso se tradujo en endometrio preservado sin hiperplasia (a diferencia de la dosis alta de estradiol del pHRT) y mejor salud ósea. → <b>Las otras:</b> (A) El argumento no es de costo: es de regulación por realimentación. → (C) Es al revés: las células necesitan vascularización, y por eso se implanta en el <b>epiplón</b>, un lecho muy vascularizado. → (D) Invierte los papeles: el pellet es el que libera una dosis fija sin responder a nada, y el que responde a las gonadotrofinas es el constructo celular; el alginato es sólo el encapsulante."},
  {st: 'Verdadero o falso: "las células de la neuroglía conducen el impulso nervioso junto con las neuronas". Elegí la justificación.', opts: ["Verdadero: los oligodendrocitos conducen el impulso por la mielina que fabrican, junto con el axón", "Falso: la glía protege, nutre y sostiene a las neuronas, y el impulso viaja por la membrana del axón", "Verdadero: los astrocitos conducen señales eléctricas lentas junto con las neuronas de su entorno", "Falso: la glía sólo existe en el sistema nervioso periférico, donde nutre al axón sin conducir"], c: 1, ex: "La definición de la cátedra es explícita: la neuroglía cumple funciones de <b>protección, nutrición y sostén</b> y <b>no conduce el impulso</b>. Lo que hace la mielina de oligodendrocitos y células de Schwann es <b>aislar</b> segmentos del axón, dejando expuestos los <b>nodos de Ranvier</b>: el impulso salta de nodo en nodo (<b>conducción saltatoria</b>), mucho más rápido que en una fibra amielínica donde la despolarización tiene que recorrer punto a punto toda la membrana. Pero la señal siempre viaja por la membrana del <b>axón</b>. → Regla asociada: <b>a mayor mielinización y mayor calibre, mayor velocidad</b>. → <b>Las otras:</b> (A) La mielina acelera la conducción, pero el impulso viaja por la membrana del axón, no por la mielina: el oligodendrocito aísla, no conduce. → (C) Los astrocitos sostienen, nutren y regulan el medio extracelular; no conducen el impulso nervioso junto con las neuronas. → (D) La conclusión es correcta pero la razón es falsa: la glía existe en los dos compartimentos, astrocito, oligodendrocito, microglía y ependimaria en el SNC; Schwann y satélite en el SNP."},
]);

// ---------- SECCION 7 - BANCO DE PARCIALES - 13 PREGUNTAS TEXTUALES DE LA CATEDRA ----------
// Parcialito de Endocrinologia (8) + Preguntas modelo para el parcial (5).
// Copiadas TAL CUAL de _fiuba_ingest/build/anatomia/banco_parcial_2.js
registerExercises('fiuba-anatomia-segundo-parcial', '7', [
  // 13 preguntas reales de la catedra, parcial 2

  // --- Parcialito de endocrinologia (8) ---
  {st: '¿Cuál es la función principal del sistema endocrino, según lo establecido en el texto? 2 <i>(Nota: el "2" al final está en el archivo original. Parece un resto de numeración/paginado pegado al enunciado. Lo dejo tal cual.)</i> <i>(Parcialito de Endocrinología · pregunta 1, real)</i>', opts: ['Controlar las funciones corporales mediante la transmisión rápida de impulsos nerviosos.', 'Controlar las funciones corporales mediante la liberación de mensajeros químicos (hormonas)', 'Regular el pH sanguíneo y el equilibrio hidroelectrolítico exclusivamente.', 'Estimular la contracción del músculo esquelético y regular la temperatura corporal.'], c: 1, ex: 'El sistema endocrino es uno de los dos grandes sistemas de integración y control del organismo. Su modo de operar es químico: glándulas sin conducto vierten hormonas a la sangre, que las distribuye a todo el cuerpo, y la respuesta aparece en las células que tienen el receptor. La contracara del sistema nervioso: éste transmite señales eléctricas por vías anatómicas definidas (rápido, localizado, breve); el endocrino difunde señales químicas por un medio compartido (lento en instalarse, generalizado, duradero). La opción B es la única que nombra el mecanismo (mensajeros químicos) y no un efecto puntual. → <b>Las otras:</b> (A) Describe al sistema nervioso, no al endocrino: confunde los dos sistemas de control. "Impulsos nerviosos" es potencial de acción, no hormona. → (C) Error por el "exclusivamente": el eje ADH-aldosterona sí regula hidroelectrolitos, pero eso es una función entre muchas (crecimiento, metabolismo, reproducción, respuesta al estrés). Reduce el sistema a una sola tarea. → (D) La contracción del músculo esquelético es control nervioso somático voluntario (placa motora, acetilcolina); el endocrino no inerva músculo estriado esquelético. La termorregulación sí tiene componente hormonal (tiroideas, calorigénesis) pero no es "la función principal".'},
  {st: '¿Por qué una hormona solo afecta a ciertas células diana y no a todas las células del organismo? <i>(Parcialito de Endocrinología · pregunta 2, real)</i>', opts: ['Porque la hormona es transportada únicamente a través de capilares sanguíneos específicos que irrigan el órgano diana.', 'Porque solo afecta a aquellas células que tienen receptores específicos para esa hormona en particular.', 'Porque las hormonas liposolubles son degradadas rápidamente en la sangre, impidiendo su acción generalizada.', 'Porque la concentración de la hormona se vuelve insignificante al circular por todo el cuerpo.'], c: 1, ex: 'El concepto clave es <b>especificidad por receptor</b>. La sangre es un medio de distribución no direccionado: la hormona baña por igual a todas las células del cuerpo. Lo que define el blanco es la expresión del receptor específico (de membrana para las hidrosolubles, citoplasmático/nuclear para las liposolubles), con complementariedad tipo llave-cerradura. Una célula sin ese receptor es "sorda" a la hormona aunque la tenga encima. Corolario útil: la sensibilidad de un tejido se regula subiendo o bajando el número de receptores (up/down-regulation), no cambiando la hormona. → <b>Las otras:</b> (A) Falso anatómica y funcionalmente: no existen capilares "dedicados" que lleven una hormona solo a su órgano blanco; una vez en circulación general la hormona llega a todos los lechos capilares. → (C) Doble error: las liposolubles son justamente las de vida media más larga, porque viajan unidas a proteínas transportadoras plasmáticas que las protegen de la degradación; y además la degradación explicaría duración, no selectividad. → (D) Confunde dilución con selectividad: las hormonas actúan a concentraciones ínfimas (nano/picomolares) precisamente porque el receptor amplifica la señal; la concentración plasmática baja es lo normal, no un mecanismo de exclusión.'},
  {st: '¿Cuál es la diferencia en el mecanismo de acción de las hormonas liposolubles (esteroideas) en comparación con las hormonas hidrosolubles (proteicas)? <i>(Parcialito de Endocrinología · pregunta 3, real)</i>', opts: ['Las hormonas liposolubles se unen a receptores en la membrana celular y utilizan segundos mensajeros, mientras que las hidrosolubles se unen a receptores internos.', 'Ambas utilizan el AMP cíclico (cAMP) como segundo mensajero en el núcleo celular.', 'Las hormonas liposolubles atraviesan la membrana celular y se unen a receptores internos, mientras que las hidrosolubles se unen a receptores de membrana y usan segundos mensajeros (como cAMP).', 'Las hormonas hidrosolubles regulan la transcripción de ADN, y las liposolubles solo modifican proteínas preexistentes.'], c: 2, ex: 'La solubilidad determina el mecanismo. Las <b>liposolubles</b> (esteroides: cortisol, aldosterona, andrógenos, estrógenos, progesterona; y las tiroideas, que se comportan igual) difunden por la bicapa lipídica, se unen a un receptor citoplasmático o nuclear y el complejo hormona-receptor actúa como factor de transcripción sobre el ADN: se sintetizan proteínas nuevas. Por eso el efecto tarda (horas) pero dura. Las <b>hidrosolubles</b> (peptídicas/proteicas como insulina, GH, TSH; y catecolaminas) no atraviesan la membrana: se unen a un receptor de superficie, que dispara un segundo mensajero intracelular (cAMP vía adenilato ciclasa, IP3/DAG, Ca²⁺) y una cascada de fosforilaciones que modifica enzimas ya existentes. Efecto rápido (segundos-minutos) y breve. → <b>Las otras:</b> (A) Es exactamente la inversión del mecanismo: le asigna receptor de membrana a las liposolubles y receptor interno a las hidrosolubles. → (B) Dos errores: el cAMP es un segundo mensajero <b>citoplasmático</b>, no nuclear; y las liposolubles no lo usan, actúan directamente sobre la transcripción sin necesidad de segundo mensajero. → (D) Vuelve a invertir: las que regulan transcripción de ADN son las liposolubles; las hidrosolubles son las que principalmente modifican proteínas/enzimas preexistentes por fosforilación.'},
  {st: '¿Qué hormonas se denominan gonadotrofinas y cuál es el significado de esta denominación? <i>(Parcialito de Endocrinología · pregunta 4, real)</i>', opts: ['Hormona del Crecimiento y Prolactina, porque estimulan el desarrollo mamario.', 'TSH y ACTH, porque tienen efectos estimulantes sobre otras glándulas endocrinas.', 'Hormona Foliculoestimulante (FSH) y Hormona Luteinizante (LH), porque estimulan el crecimiento y mantenimiento de las gónadas (ovarios y testículos).', 'Hormona Antidiurética y Oxitocina, porque son producidas por la neurohipófisis.'], c: 2, ex: '"Gonado-trofina" se lee literal: <i>gónada</i> (ovario/testículo) + <i>trofos</i> (nutrir, hacer crecer). Son hormonas de la <b>adenohipófisis</b> cuyo órgano blanco es la gónada. FSH: en la mujer estimula el crecimiento del folículo ovárico y la secreción de estrógenos; en el varón actúa sobre las células de Sertoli y la espermatogénesis. LH: dispara la ovulación y forma el cuerpo lúteo; en el varón estimula las células de Leydig y la producción de testosterona. La lógica del sufijo "-trofina" ordena toda la adenohipófisis: tirotrofina (TSH) → tiroides, corticotrofina (ACTH) → corteza suprarrenal, gonadotrofinas (FSH/LH) → gónadas. → <b>Las otras:</b> (A) GH y PRL no tienen a la gónada como blanco. Además la PRL, lejos de estimular la gónada, la frena indirectamente (ver Pregunta 6). El desarrollo mamario no es "gonadal". → (B) TSH y ACTH sí son trofinas hipofisarias (el razonamiento del "efecto estimulante sobre otras glándulas" es correcto en general), pero su blanco es tiroides y suprarrenal, no la gónada. Es la opción distractora más tentadora: confunde el género (trofinas) con la especie (gonadotrofinas). → (D) ADH y oxitocina son <b>neurohipofisarias</b> (se sintetizan en los núcleos supraóptico y paraventricular del hipotálamo y se almacenan en la neurohipófisis) y actúan sobre túbulo colector renal y músculo liso uterino/mioepitelio mamario. Que compartan origen no las hace gonadotrofinas.'},
  {st: 'Un paciente necesita recibir un fármaco que es un análogo de la Insulina. Considerando la clasificación química de la Insulina como hormona peptídica, ¿cuál es la vía de administración preferida y por qué? <i>(Parcialito de Endocrinología · pregunta 5, real)</i>', opts: ['Vía oral, porque al ser una hormona proteica, se absorbe fácilmente en el estómago sin alteración.', 'Vía transdérmica, porque las hormonas proteicas tienen afinidad por los lípidos de la piel.', 'Vía endovenosa/intravenosa, porque la Insulina es hidrosoluble y sería degradada por las enzimas digestivas si se administra vía oral.', 'Vía oral, ya que el único grupo que se degrada por vía oral son las hormonas tiroideas.'], c: 2, ex: 'La insulina es un polipéptido (51 aminoácidos, cadenas A y B unidas por puentes disulfuro). Por vía oral la atacarían la pepsina gástrica y la tripsina/quimotripsina intestinales, que la hidrolizan a aminoácidos sin actividad biológica: llegaría cero hormona a la sangre. Por eso toda hormona peptídica exige una <b>vía parenteral</b>, que saltea el tubo digestivo. De las cuatro opciones, C es la única parenteral y la única que da el fundamento correcto (degradación enzimática digestiva). <b>Salvedad importante:</b> en la práctica clínica la vía de elección para insulina y sus análogos es la <b>subcutánea</b> (lapicera, jeringa, bomba); la endovenosa se reserva para situaciones agudas como la cetoacidosis diabética o el paciente crítico. La opción C es imprecisa en ese punto, pero es la única defendible dentro del set y el concepto que evalúa la pregunta ("peptídica ⇒ no oral") está bien planteado. Enganche con bioingeniería: es exactamente este problema (una macromolécula hidrosoluble que no sobrevive al tracto digestivo ni cruza el estrato córneo) el que motiva el desarrollo de bombas de infusión, microagujas, insulina inhalada y sistemas de encapsulación/liberación controlada. → <b>Las otras:</b> (A) Falso en los dos términos: el estómago no absorbe proteínas intactas (las desnaturaliza con HCl y las hidroliza con pepsina), y la absorción de macromoléculas por mucosa gástrica es prácticamente nula. → (B) Invierte la fisicoquímica: la insulina es <b>hidrosoluble</b> y de alto peso molecular (~5.800 Da), justamente las dos características que impiden atravesar el estrato córneo, que es una barrera lipídica. La vía transdérmica sirve para moléculas pequeñas y lipofílicas (nicotina, estradiol, fentanilo). → (D) Doble error, y encima al revés: la insulina no puede darse por boca, y las hormonas tiroideas son precisamente el ejemplo clásico de hormona que <b>sí</b> se administra por vía oral (levotiroxina en comprimidos), porque son derivados aminoacídicos yodados, pequeños y liposolubles, resistentes a la digestión. → <i>Nota: el enunciado original admite alguna ambigüedad; ésta es la lectura más defendible.</i>'},
  {st: 'Durante el pico de la noche, se observa un aumento en la secreción de Prolactina. ¿Cuál es el efecto fisiológico asociado a este aumento, aparte de la estimulación de la producción de leche? <i>(Parcialito de Endocrinología · pregunta 6, real)</i>', opts: ['La estimulación de la síntesis de proteína y el crecimiento óseo.', 'El aumento de la secreción de tiroxina por la glándula tiroides.', 'La activación de la adenilato ciclasa como segundo mensajero.', 'La supresión de la ovulación (efecto anticonceptivo natural).'], c: 3, ex: 'La prolactina, además de la galactopoyesis, tiene un efecto <b>antigonadotrófico</b>: inhibe la liberación pulsátil de GnRH hipotalámica, con lo cual caen FSH y LH, no hay pico ovulatorio de LH y se suprime la ovulación. Ese es el mecanismo de la amenorrea de la lactancia (base del método MELA/LAM). La prolactina tiene secreción pulsátil con máximo durante el sueño, y el estímulo de succión del pezón la aumenta todavía más por vía neuroendocrina refleja, reforzando el bloqueo. Es un ejemplo lindo de integración: una hormona hipofisaria que actúa río arriba sobre el hipotálamo para apagar otro eje. → <b>Las otras:</b> (A) Es el efecto de la <b>hormona de crecimiento (GH/somatotrofina)</b>, mediada por IGF-1 hepática: balance nitrogenado positivo y crecimiento del cartílago de conjunción. Confunde dos hormonas adenohipofisarias que además comparten el patrón de pico nocturno durante el sueño, lo que hace al distractor razonable. → (B) Es el efecto de la <b>TSH (tirotrofina)</b>. La PRL no tiene acción tiroidea. (Sí existe la relación inversa: en el hipotiroidismo primario la TRH elevada puede subir la prolactina, pero eso es otra cosa y va en el sentido contrario al que plantea la opción.) → (C) Confunde nivel de análisis: describiría un mecanismo intracelular, no un "efecto fisiológico" como pide el enunciado. Y encima es incorrecto: el receptor de prolactina no está acoplado a proteína G/adenilato ciclasa, señaliza por la vía JAK2-STAT5.'},
  {st: 'En una situación de ayuno prolongado, la concentración de glucosa en sangre disminuye. ¿Qué hormona pancreática se libera para contrarrestar esta hipoglucemia, y cuál es su mecanismo de acción a nivel de órgano? <i>(Parcialito de Endocrinología · pregunta 7, real)</i>', opts: ['Insulina; permite la entrada de glucosa a las células.', 'Somatostatina; inhibe la secreción de Insulina y Glucagón.', 'Glucagón; permite la salida de glucosa del hígado a la sangre.', 'Adrenalina; aumenta la glucosa en sangre desde las suprarrenales.'], c: 2, ex: 'El páncreas endocrino (islotes de Langerhans) tiene células <b>beta</b> (insulina, hipoglucemiante) y células <b>alfa</b> (glucagón, hiperglucemiante), en relación antagónica. Ante hipoglucemia, la célula alfa secreta glucagón, que actúa fundamentalmente sobre el <b>hígado</b>: activa la glucogenólisis (degrada el glucógeno hepático a glucosa) y, en ayuno más prolongado, la gluconeogénesis. La glucosa sale del hepatocito a la sangre y se normaliza la glucemia. Detalle importante para la lógica del enunciado: el hígado es prácticamente el único órgano (junto con la corteza renal en ayuno prolongado) que puede exportar glucosa libre a la sangre (tiene glucosa-6-fosfatasa); el músculo, aunque almacena glucógeno, lo consume localmente y no lo devuelve a la circulación. → <b>Las otras:</b> (A) Invierte el sentido de la respuesta homeostática: la insulina es la hormona del estado posprandial, hace <b>bajar</b> la glucemia metiendo glucosa a músculo y tejido adiposo (GLUT-4). Administrarla en hipoglucemia la agravaría. → (B) La somatostatina (células delta) es un modulador local que frena tanto insulina como glucagón; es paracrina y reguladora, no corrige la hipoglucemia. Al inhibir el glucagón trabajaría incluso en contra. → (D) La adrenalina <b>sí</b> es hiperglucemiante y participa de la respuesta a la hipoglucemia, pero no cumple la condición del enunciado: no es una hormona pancreática, la secreta la <b>médula suprarrenal</b>. La propia opción se contradice al decir "desde las suprarrenales" cuando la pregunta pide hormona pancreática. Distractor de lectura.'},
  {st: 'El Hipotiroidismo es una condición clínica que resulta de la producción insuficiente de hormonas tiroideas. Según la localización del fallo en el eje Hipotálamo-Hipófisis-Tiroides, se clasifica en primario y secundario. ¿Cuál de las siguientes opciones describe correctamente dos posibles causas diferentes de Hipotiroidismo (primario y secundario)? <i>(Parcialito de Endocrinología · pregunta 8, real)</i>', opts: ['Producción excesiva de Calcitonina por las células parafoliculares (Hipotiroidismo Primario) y un aumento en la liberación de TSH (Hipotiroidismo Secundario).', 'Un fallo intrínseco de la glándula tiroides que impide la producción de T3 y T4 (Hipotiroidismo Primario) o la falta de estímulo de TSH debido a una disfunción hipofisaria (Hipotiroidismo Secundario)', 'Disfunción de la glándula pineal que inhibe la TSH (Hipotiroidismo Primario) y la secreción excesiva de T3 y T4 por la propia tiroides (Hipotiroidismo Secundario).', 'La glándula tiroides produce hormonas excesivas que suprimen la liberación de TSH (Hipotiroidismo Primario) y un defecto en la reabsorción de Ca++ (Hipotiroidismo Secundario).'], c: 1, ex: 'La regla de clasificación de cualquier eje endocrino es "dónde está la falla, contando desde la glándula efectora hacia arriba": <b>primario</b> = falla en la glándula periférica (la tiroides misma: tiroiditis de Hashimoto, tiroidectomía, déficit de yodo, fármacos). Como la T3/T4 baja, se libera el feedback negativo y la <b>TSH sube</b>. <b>Secundario</b> = falla en la hipófisis, que no manda TSH; entonces la tiroides está sana pero desestimulada, y aquí <b>T4 baja con TSH baja o inapropiadamente normal</b>. (Y <b>terciario</b> = falla hipotalámica, no llega TRH.) La opción B es la única que respeta esa lógica de localización y además mantiene la coherencia interna: en los dos casos el resultado final es <i>menos</i> hormona tiroidea, que es lo que exige la definición de hipotiroidismo. Tip de examen: el par TSH/T4 es el que permite ubicar el nivel de la lesión. → <b>Las otras:</b> (A) Dos errores: la calcitonina (células parafoliculares o C) regula el calcio, no interviene en el eje T3/T4, así que su exceso no produce hipotiroidismo; y una TSH <b>aumentada</b> estimularía la tiroides. Es lo que se ve <i>como consecuencia</i> del hipotiroidismo primario, nunca la causa de uno secundario. → (C) La glándula pineal secreta melatonina y no controla la TSH (quien lo hace es la TRH hipotalámica sobre la adenohipófisis); y "secreción excesiva de T3 y T4" es por definición <b>hiper</b>tiroidismo, lo opuesto a lo que se pregunta. → (D) Describe hipertiroidismo primario con su feedback negativo esperable (T4 alta suprime TSH) y lo etiqueta como hipotiroidismo; el segundo término, defecto en la reabsorción de Ca²⁺, corresponde al eje paratohormona/calcitonina/vitamina D, ajeno a las hormonas tiroideas.'},

  // --- Preguntas modelo para el parcial (5) ---
  {st: 'Un paciente presenta síntomas de fatiga extrema y aumento de peso. Los análisis muestran bajos niveles de hormonas tiroideas (T3/T4) y altos niveles de Hormona Tiroideoestimulante (TSH). ¿Cuál es el diagnóstico de hipotiroidismo más probable y cuál es la causa subyacente de la TSH elevada? <i>(Preguntas modelo · pregunta 1, real)</i>', opts: ['Hipotiroidismo secundario: la Hipófisis no está estimulando la tiroides, por eso la TSH es baja.', 'Hipotiroidismo primario: la glándula tiroides no puede producir suficientes hormonas, por lo que la Hipófisis aumenta la liberación de TSH para compensar la falta de retroalimentación negativa.', 'Hipotiroidismo terciario: el problema es la falta de yodo en la dieta.', 'Enfermedad de Graves: la glándula está hiperestimulada, por eso la TSH es alta'], c: 1, ex: 'El patrón "T3/T4 bajas + TSH alta" es la firma de laboratorio del hipotiroidismo <b>primario</b>. El eje Hipotálamo-Hipófisis-Tiroides (HHT) funciona por retroalimentación negativa: la T3/T4 circulante frena la secreción de TRH hipotalámica y de TSH hipofisaria. Si la glándula efectora (tiroides) falla, cae la T3/T4, se pierde el freno sobre la hipófisis y la TSH sube tratando de compensar. La regla general para localizar la lesión en cualquier eje endocrino: la hormona <b>trófica</b> (TSH) y la hormona <b>efectora</b> (T3/T4) se mueven en direcciones <b>opuestas</b> cuando el fallo es en la glándula periférica, y en la <b>misma</b> dirección cuando el fallo es central (hipófisis o hipotálamo). → <b>Las otras:</b> (A) Se autocontradice: define correctamente el hipotiroidismo secundario (fallo hipofisario) pero dice "por eso la TSH es baja", cuando el enunciado informa TSH <b>alta</b>. El dato de laboratorio descarta la opción. → (C) Doble error: el "terciario" es fallo <b>hipotalámico</b> (déficit de TRH), no dietario; y la deficiencia de yodo es una causa de hipotiroidismo <b>primario</b> (falla el sustrato de la síntesis en la propia glándula), que igual cursaría con TSH alta. → (D) Graves es un <b>hiper</b>tiroidismo autoinmune por anticuerpos estimulantes del receptor de TSH (TSI): la T3/T4 está <b>alta</b> y la TSH <b>suprimida</b> por retroalimentación negativa. Confunde "receptor hiperestimulado" con "TSH alta".'},
  {st: 'En el estudio de cHRT, el primer lote de constructos ováricos entrecruzados con Calcio (Ca++) mostró un desempeño deficiente, con una caída marcada en los niveles de Estradiol (E2) después de 40 días. ¿Cuál fue el principal problema de biocompatibilidad identificado por los investigadores que condujo al uso posterior de Estroncio (Sr++) como alternativa? <i>(Preguntas modelo · pregunta 2, real)</i>', opts: ['El Ca++ generó una respuesta inflamatoria excesiva en el omento.', 'El Ca++ causó la luteinización prematura de las células de la granulosa.', 'El Ca++ calcificó (mineralizó) progresivamente del constructo de alginato, lo que comprometió su función sostenida.', 'El Ca++ fue tóxico para las células de la teca.'], c: 2, ex: 'En la terapia de reemplazo hormonal basada en células (cHRT) se encapsulan células de granulosa y teca en microcápsulas de alginato. El alginato gelifica por entrecruzamiento iónico con cationes divalentes: el estándar es Ca²⁺. El problema es que el constructo con Ca²⁺ queda inmerso en un medio fisiológico rico en fosfato, y el Ca²⁺ del gel nuclea <b>fosfato de calcio</b>: la cápsula se mineraliza/calcifica progresivamente. Esa mineralización endurece la matriz, bloquea la difusión de nutrientes, O₂ y de las hormonas hacia afuera, y termina la función secretora: de ahí la caída del E2 a los ~40 días. El Sr²⁺ entrecruza el alginato igual de bien (es divalente, del mismo grupo que el Ca) pero <b>no participa en la cascada de mineralización de la misma manera</b>, por lo que el constructo mantiene difusión y secreción sostenida en el tiempo. Es un problema clásico de <b>biomateriales</b>, no de biología celular: falla la matriz, no las células. → <b>Las otras:</b> (A) Confunde el mecanismo con una respuesta a cuerpo extraño del huésped. Justamente el punto del alginato es que es inmunoaislante y de baja inmunogenicidad; el fracaso fue intrínseco al gel, no una reacción inflamatoria del omento. → (B) Atribuye a un catión de entrecruzamiento un efecto de programación endocrina. La luteinización de la granulosa la dispara el pico de LH / la señalización de gonadotrofinas, no el Ca²⁺ estructural del andamio; además una luteinización daría un perfil de progesterona alterado, no la falla mecánica descrita. → (D) El Ca²⁺ no es citotóxico: es un ion fisiológico ubicuo y el entrecruzante estándar en encapsulación celular precisamente por su biocompatibilidad. Además, si hubiera toxicidad selectiva sobre la teca (productora de andrógenos precursores), el efecto habría sido inmediato, no una degradación progresiva a 40 días.'},
  {st: '¿Cuál de las siguientes funciones se localiza predominantemente en el Lóbulo Temporal del cerebro, según la segregación de funciones corticales? <i>(Preguntas modelo · pregunta 3, real)</i>', opts: ['Planificación, juicio e inhibición del comportamiento', 'Coordinación de movimientos voluntarios y equilibrio', 'Audición, comprensión del lenguaje (Área de Wernicke) y formación de la memoria', 'Recepción y procesamiento de la información somatosensorial (tacto)'], c: 2, ex: 'El lóbulo temporal aloja la <b>corteza auditiva primaria</b> (circunvolución temporal transversa / de Heschl, áreas 41-42 de Brodmann), el <b>área de Wernicke</b> en la porción posterior de la circunvolución temporal superior del hemisferio dominante (comprensión del lenguaje) y, en su cara medial, el <b>hipocampo</b> y el complejo amigdalino, responsables de la consolidación de la memoria declarativa. Los tres ítems de la opción C son temporales. → <b>Las otras:</b> (A) Son funciones <b>prefrontales</b> (lóbulo frontal, corteza prefrontal dorsolateral y orbitofrontal): funciones ejecutivas, juicio social e inhibición de respuestas (el síndrome que aparece en las lesiones frontales tipo Phineas Gage). → (B) Corresponde al <b>cerebelo</b> (y al circuito con ganglios de la base). Además, el enunciado pide un lóbulo del <b>cerebro</b>: el cerebelo no es un lóbulo cortical cerebral. → (D) Es el lóbulo <b>parietal</b>: circunvolución poscentral (áreas 3, 1, 2), corteza somatosensorial primaria, por detrás del surco central. El temporal está por debajo del surco lateral (de Silvio).'},
  {st: '¿Qué par de hormonas liberadas por la Adenohipófisis se clasifican como Gonadotrofinas debido a su función principal de estimular el crecimiento y mantenimiento de las gónadas? <i>(Preguntas modelo · pregunta 4, real)</i>', opts: ['Hormona del Crecimiento (GH) y Prolactina', 'Hormona Tiroideoestimulante (TSH) y Hormona Adrenocorticotropa (ACTH)', 'Hormona Foliculoestimulante (FSH) y Hormona Luteinizante (LH)', 'Oxitocina y Hormona Antidiurética (ADH)'], c: 2, ex: '"Gonadotrofina" = hormona cuyo órgano blanco es la gónada. FSH y LH son glucoproteínas secretadas por las células <b>gonadotropas</b> de la adenohipófisis (pars distalis), bajo control de la GnRH hipotalámica. La FSH estimula la maduración folicular en el ovario y la espermatogénesis (células de Sertoli) en el testículo; la LH dispara la ovulación y la formación del cuerpo lúteo, y estimula la producción de testosterona en las células de Leydig. Comparten con la TSH la misma subunidad α y se diferencian por la subunidad β. → <b>Las otras:</b> (A) Son adenohipofisarias, pero no gonadotrofinas: la GH (somatotropas) actúa sobre el hígado/hueso vía IGF-1 y la Prolactina (lactotropas) sobre la glándula mamaria. Ninguna tiene la gónada como blanco principal. → (B) También son trópicas adenohipofisarias, pero de otros ejes: la TSH sobre la tiroides y la ACTH sobre la corteza suprarrenal. Confunde "hormona trófica" con "gonadotrofina". → (D) Error de compartimento: oxitocina y ADH <b>no</b> se producen en la adenohipófisis. Se sintetizan en los núcleos supraóptico y paraventricular del hipotálamo y se almacenan/liberan en la <b>neurohipófisis</b> (origen neuroectodérmico, no de la bolsa de Rathke).'},
  {st: 'Un paciente es evaluado por síntomas de hipotiroidismo grave (fatiga, aumento de peso, baja tasa metabólica). Se realizan análisis de sangre que arrojan los siguientes resultados: Hormonas Tiroideas (T3 y T4): Niveles muy Bajos (Confirma el hipotiroidismo). Hormona Estimulante del Tiroides (TSH): Niveles muy Bajos (Contradice el hipotiroidismo primario, donde la TSH debería estar alta por compensación). Hormona Liberadora de Tirotropina (TRH) del Hipotálamo: Niveles Bajos. Basándose en estos datos y en el principio de retroalimentación negativa del eje Hipotálamo-Hipófisis-Tiroides (HHT), ¿dónde debe localizarse la causa primaria de la disfunción? <i>(Preguntas modelo · pregunta 5, real)</i>', opts: ['Fallo Primario: La glándula tiroides está fallando (Hipotiroidismo primario).', 'Fallo Terciario: La Hipófisis (pituitaria) está fallando (Hipotiroidismo secundario).', 'Fallo Primario: La glándula tiroides está fallando, pero existe una enfermedad tiroidea autoinmune que inhibe la TSH.', 'Fallo Terciario (Hipotálamo): El fallo está en la secreción de TRH por el Hipotálamo, lo que provoca la falta de estímulo a la Hipófisis, llevando a la baja TSH y, finalmente, a la baja T3/T4.'], c: 3, ex: 'Los <b>tres</b> niveles del eje están bajos: TRH baja → TSH baja → T3/T4 bajas. La lesión hay que ubicarla en el escalón <b>más alto</b> que esté deprimido, porque cada nivel explica la caída del que le sigue. Si el hipotálamo no secreta TRH, la hipófisis no recibe estímulo y no secreta TSH; sin TSH, la tiroides (que está sana) no produce T3/T4. Eso es hipotiroidismo <b>terciario</b> o hipotalámico. La clave de lectura, ya usada en la Pregunta modelo 1: cuando la hormona trófica y la efectora caen <b>juntas</b> (misma dirección), el fallo es <b>central</b>; y la TRH baja discrimina hipotálamo (terciario) de hipófisis (secundario, donde la TRH estaría <b>alta</b> por desinhibición). → <b>Las otras:</b> (A) Un fallo primario de la tiroides daría T3/T4 bajas con TSH y TRH <b>elevadas</b> por pérdida del freno negativo. El enunciado dice explícitamente que la TSH es muy baja: contradice el patrón. → (B) La opción está mal etiquetada en sí misma (llama "Fallo Terciario" a lo que después define como hipofisario/secundario), y de fondo es incorrecta: en un fallo hipofisario primario la TRH hipotalámica estaría <b>alta</b>, no baja, porque el hipotálamo detectaría la T3/T4 baja e intentaría compensar. La TRH baja del enunciado descarta el origen hipofisario. → (C) Inventa un mecanismo inexistente: no hay una enfermedad tiroidea autoinmune que suprima la TSH junto con T3/T4 bajas. La tiroiditis de Hashimoto (autoinmune) cursa con TSH <b>alta</b>; la única entidad autoinmune que suprime la TSH es Graves, y ahí la T3/T4 está <b>alta</b>. Además, tampoco explicaría la TRH baja.'},
  // CHOICE-DOCENTE reales (repaso de anatomia 2025) inicio
  {st: "<b>Choice de anatomía · 1.</b> ¿Cuál de las siguientes afirmaciones es correcta?", opts: ["El vértice pulmonar se extiende hasta la base del cuello.", "El pulmón derecho tiene dos bronquios lobares.", "La base del pulmón derecho desciende más que la del izquierdo.", "El pulmón izquierdo tiene tres lóbulos."], c: 0, ex: "El <b>vértice</b> del pulmón sobrepasa la primera costilla y la clavícula: asoma unos centímetros en la <b>base del cuello</b>. Es la única afirmación sin lados cambiados. → <b>Las otras:</b> (B) El pulmón derecho tiene <b>tres</b> lóbulos y por eso tres bronquios lobares; dos son los del izquierdo. → (C) Es al revés: la base derecha queda <b>más alta</b>, porque el hígado empuja hacia arriba la mitad derecha del diafragma. → (D) El izquierdo tiene <b>dos</b> lóbulos, superior e inferior; tres tiene el derecho."},
  {st: "<b>Choice de anatomía · 2.</b> El diafragma…", opts: ["Es el principal músculo de la espiración.", "Es el principal músculo de la inspiración.", "Se encuentra tapizado por pleura visceral.", "Se encuentra tapizado por pericardio visceral."], c: 1, ex: "Al contraerse, el diafragma <b>desciende</b> y agranda el tórax de arriba abajo: hace la mayor parte del trabajo de la <b>inspiración</b>. Lo inerva el nervio frénico. → <b>Las otras:</b> (A) La espiración tranquila es <b>pasiva</b>; en la forzada trabajan los abdominales y los intercostales internos. → (C) Su cara superior está cubierta por pleura <b>parietal</b> (la porción diafragmática); la visceral está pegada al pulmón. → (D) En el centro se apoya el pericardio <b>fibroso</b>; el pericardio visceral es el epicardio, que recubre al corazón."},
  {st: "<b>Choice de anatomía · 3.</b> El bronquio principal izquierdo…", opts: ["Se divide en dos bronquios principales.", "Se divide en tres bronquios segmentarios.", "Se divide en tres bronquios lobares.", "Se divide en dos bronquios lobares."], c: 3, ex: "Cada bronquio principal da <b>tantos bronquios lobares como lóbulos</b> tiene su pulmón: el izquierdo, <b>dos</b> (superior e inferior). → <b>Las otras:</b> (A) Principales son los dos que nacen de la tráquea: un principal no se divide en principales. → (B) Los segmentarios nacen de los lobares, un nivel más abajo, y son entre ocho y diez por pulmón, no tres. → (C) Tres lobares da el bronquio principal <b>derecho</b>."},
  {st: "<b>Choice de anatomía · 4.</b> En una vista anterior de la laringe, se pueden observar los cartílagos…", opts: ["Tiroides y aritenoides.", "Epiglotis y cricoides.", "Tiroides y cricoides.", "Aritenoides y cricoides."], c: 2, ex: "De frente, la laringe muestra el cartílago <b>tiroides</b> (con la prominencia laríngea, la nuez) y, debajo, el arco del <b>cricoides</b>. → <b>Las otras:</b> (A) Los aritenoides están <b>atrás</b>, apoyados sobre el cricoides: se ven en la vista posterior. → (B) La epiglotis se fija por dentro del tiroides y sube por detrás del hueso hioides: de frente queda tapada. → (D) Aritenoides otra vez: son posteriores."},
  {st: "<b>Choice de anatomía · 5.</b> La cavidad oral y la orofaringe se comunican a través de…", opts: ["Las coanas.", "La laringofaringe.", "La úvula.", "El istmo de las fauces."], c: 3, ex: "El <b>istmo de las fauces</b> es la abertura posterior de la boca: arriba el paladar blando con la úvula, a los lados los arcos del paladar y abajo la raíz de la lengua. Por ahí se pasa a la orofaringe. → <b>Las otras:</b> (A) Las coanas comunican las cavidades <b>nasales</b> con la nasofaringe. → (B) La laringofaringe es el piso más bajo de la faringe, no un pasaje entre la boca y la faringe. → (C) La úvula cuelga del paladar blando y forma parte del borde del istmo: es un límite, no la comunicación."},
  {st: "<b>Choice de anatomía · 6.</b> La arteria aorta se origina de…", opts: ["El ventrículo derecho.", "El ventrículo izquierdo.", "La aurícula derecha.", "La aurícula izquierda."], c: 1, ex: "La aorta nace del <b>ventrículo izquierdo</b>, pasando por la válvula aórtica. Regla: de los ventrículos salen arterias y a las aurículas llegan venas. → <b>Las otras:</b> (A) Del ventrículo derecho sale el <b>tronco pulmonar</b>. → (C) La aurícula derecha recibe las venas cavas y el seno coronario: no da arterias. → (D) La aurícula izquierda recibe las cuatro venas pulmonares."},
  {st: "<b>Choice de anatomía · 7.</b> El nodo aurículoventricular…", opts: ["Se encuentra por encima del nodo sinusal.", "Se encuentra luego del haz de His.", "Se encuentra entre el nodo sinusal y el haz de His.", "Se encuentra luego de las fibras de Purkinje."], c: 2, ex: "El impulso sigue este orden: <b>nodo sinusal</b> → <b>nodo aurículoventricular</b> → <b>haz de His</b> → ramas derecha e izquierda → fibras de Purkinje. El aurículoventricular queda entre el sinusal y el haz de His, y además está más abajo: en la parte baja del tabique entre las dos aurículas. → <b>Las otras:</b> (A) El sinusal está arriba, junto a la desembocadura de la vena cava superior. → (B) El haz de His viene <b>después</b> del nodo aurículoventricular. → (D) Las fibras de Purkinje son el último tramo."},
  {st: "<b>Choice de anatomía · 8.</b> La sangre eyectada a través de la arteria pulmonar…", opts: ["Retorna al corazón por las venas cavas superior e inferior.", "Retorna a la aurícula izquierda.", "Proviene del ventrículo izquierdo.", "Proviene de la aurícula izquierda."], c: 1, ex: "Es el <b>circuito menor</b>: ventrículo derecho → tronco y arterias pulmonares → pulmones → cuatro venas pulmonares → <b>aurícula izquierda</b>. → <b>Las otras:</b> (A) Por las cavas vuelve la sangre del circuito mayor, y a la aurícula <b>derecha</b>. → (C) La arteria pulmonar sale del ventrículo <b>derecho</b>; el izquierdo eyecta en la aorta. → (D) La aurícula izquierda es donde <b>termina</b> ese circuito, no donde empieza."},
  {st: "<b>Choice de anatomía · 9.</b> La válvula mitral…", opts: ["Impide el reflujo desde el ventrículo derecho hacia la aurícula derecha.", "Impide el reflujo desde el ventrículo izquierdo hacia la aurícula izquierda.", "Impide el reflujo desde la aorta hacia el ventrículo izquierdo.", "Impide el reflujo desde la arteria pulmonar hacia el ventrículo derecho."], c: 1, ex: "La mitral está entre la aurícula y el ventrículo <b>izquierdos</b>: se cierra cuando el ventrículo se contrae y evita que la sangre vuelva a la aurícula. → <b>Las otras:</b> (A) Eso lo hace la <b>tricúspide</b>, del lado derecho. → (C) Eso lo hace la válvula <b>aórtica</b>. → (D) Eso lo hace la válvula <b>pulmonar</b>."},
  {st: "<b>Choice de anatomía · 10.</b> La fosa oval representa…", opts: ["Un vestigio de la comunicación embriológica entre ambos ventrículos.", "Un vestigio de la comunicación embriológica entre ambas aurículas.", "Un vestigio de la comunicación embriológica entre las arterias aorta y pulmonar.", "Un vestigio de la comunicación embriológica entre la aurícula y el ventrículo izquierdos."], c: 1, ex: "En el feto, la sangre pasa de la aurícula derecha a la izquierda por el <b>foramen oval</b>, salteando los pulmones. Al nacer se cierra y queda la <b>fosa oval</b>, una depresión en el tabique entre las dos aurículas. → <b>Las otras:</b> (A) Entre los ventrículos no hay comunicación normal en el feto. → (C) Entre el tronco pulmonar y la aorta está el <b>conducto arterioso</b>, que deja el ligamento arterioso. → (D) Aurícula y ventrículo izquierdos se comunican siempre, por el orificio de la válvula mitral: no es un vestigio."},
  {st: "<b>Choice de anatomía · 11.</b> ¿Cuál de las siguientes estructuras anatómicas desemboca en el ciego?", opts: ["Ileon.", "Yeyuno.", "Duodeno.", "Píloro."], c: 0, ex: "El <b>íleon</b>, último tramo del intestino delgado, se abre en el <b>ciego</b> por la válvula ileocecal. → <b>Las otras:</b> (B) El yeyuno se continúa con el íleon. → (C) El duodeno se continúa con el yeyuno. → (D) El píloro es la salida del estómago hacia el duodeno."},
  {st: "<b>Choice de anatomía · 12.</b> En la segunda porción del duodeno desembocan…", opts: ["El conducto hepático y el cístico.", "El conducto colédoco y el cístico.", "El conducto colédoco y el pancreático.", "El conducto pancreático y el hepático."], c: 2, ex: "En la <b>segunda porción</b> (descendente) del duodeno está la <b>papila duodenal mayor</b>, donde desembocan juntos el <b>colédoco</b> y el <b>conducto pancreático</b>. → <b>Las otras:</b> (A) Ni el hepático ni el cístico llegan al duodeno: se unen entre sí más arriba y forman el colédoco. → (B) El cístico no llega: une la vesícula con el conducto hepático común. → (D) El hepático no llega: termina al unirse con el cístico."},
  {st: "<b>Choice de anatomía · 13.</b> El colon izquierdo está representado por…", opts: ["El ciego y el colon ascendente.", "El colon transverso y el colon ascendente.", "El colon descendente y el sigmoides.", "El colon ascendente y el sigmoides."], c: 2, ex: "El colon izquierdo es el <b>descendente más el sigmoides</b> (con el tramo final del transverso). El derecho es el <b>ciego más el ascendente</b> (con la mayor parte del transverso). → <b>Las otras:</b> (A) Ése es el colon derecho. → (B) El ascendente es del lado derecho. → (D) Mezcla un tramo derecho, el ascendente, con uno izquierdo, el sigmoides."},
  {st: "<b>Choice de anatomía · 14.</b> Con respecto al bazo…", opts: ["Es parte de la vía biliar extrahepática.", "Participa en la eliminación de los eritrocitos.", "Tiene un conducto que desemboca en el colédoco.", "Se encuentra por delante del cuerpo del estómago."], c: 1, ex: "El bazo filtra la sangre: sus macrófagos retiran los <b>eritrocitos viejos o dañados</b>. Es un órgano linfático, no digestivo. → <b>Las otras:</b> (A) La vía biliar extrahepática son los conductos hepáticos, el cístico, la vesícula y el colédoco. → (C) No tiene conducto: no fabrica ninguna secreción digestiva. → (D) Está en el hipocondrio izquierdo, <b>por detrás</b> del estómago, contra el diafragma."},
  {st: "<b>Choice de anatomía · 15.</b> El páncreas…", opts: ["Sólo tiene función endócrina.", "Sólo tiene función exócrina.", "Tiene función endócrina y exócrina.", "Participa en la eliminación de los eritrocitos."], c: 2, ex: "El páncreas es una glándula <b>mixta</b>. Exócrina: sus acinos fabrican el jugo pancreático, que llega al duodeno por el conducto pancreático. Endócrina: sus islotes vuelcan insulina y glucagón a la sangre. → <b>Las otras:</b> (A) Deja afuera la mitad exócrina. → (B) Deja afuera la mitad endócrina. → (D) Eso lo hace el bazo."},
  {st: "<b>Choice de anatomía · 16.</b> Con respecto a la vía urinaria…", opts: ["La uretra desemboca en la vejiga.", "La uretra se origina en la vejiga.", "El uréter se origina en la vejiga.", "El uréter desemboca en la uretra."], c: 1, ex: "Orden de la vía urinaria: riñón → cálices → pelvis renal → <b>uréter</b> → <b>vejiga</b> → <b>uretra</b> → exterior. La uretra <b>nace</b> en la vejiga. → <b>Las otras:</b> (A) Es al revés: la uretra sale de la vejiga, no desemboca en ella. → (C) El uréter nace en la pelvis renal y <b>desemboca</b> en la vejiga. → (D) El uréter termina en la vejiga, nunca en la uretra."},
  {st: "<b>Choice de anatomía · 17.</b> La pelvis renal se forma por la unión de…", opts: ["Los cálices menores.", "Los uréteres.", "Los cálices mayores.", "Las uretras."], c: 2, ex: "Cada papila vuelca la orina en un <b>cáliz menor</b>; los menores se unen en dos o tres <b>cálices mayores</b>, y los mayores forman la <b>pelvis renal</b>, que se continúa con el uréter. → <b>Las otras:</b> (A) Los menores forman los mayores: están un paso antes. → (B) El uréter es la continuación de la pelvis, y hay uno solo por riñón. → (D) Uretra hay una sola y sale de la vejiga."},
  {st: "<b>Choice de anatomía · 18.</b> En una pelvis femenina, la uretra…", opts: ["Se encuentra por delante de la vagina.", "Se encuentra por detrás de la vagina.", "Desemboca en el orificio externo de la vagina.", "Desemboca por encima del clítoris."], c: 0, ex: "En la pelvis femenina, de adelante hacia atrás: pubis, <b>vejiga y uretra</b>, <b>útero y vagina</b>, recto. La uretra, de unos 4 cm, baja pegada a la pared anterior de la vagina. → <b>Las otras:</b> (B) Por detrás de la vagina está el recto. → (C) Tiene su propio orificio, por delante del orificio vaginal. → (D) Se abre por <b>debajo</b> del clítoris, entre el clítoris y el orificio vaginal."},
  {st: "<b>Choice de anatomía · 19.</b> En una pelvis masculina, la uretra…", opts: ["Atraviesa la próstata antes de atravesar la vejiga.", "Se encuentra por delante de la próstata.", "Presenta la desembocadura de los conductos eyaculadores.", "Finaliza en los cuerpos cavernosos."], c: 2, ex: "Después de un primer tramo muy corto en la pared de la vejiga, la uretra masculina tiene tres porciones: <b>prostática</b>, <b>membranosa</b> y <b>esponjosa</b>. En la prostática desembocan los dos <b>conductos eyaculadores</b>: desde ahí es vía urinaria y genital. → <b>Las otras:</b> (A) Nace en la vejiga y después atraviesa la próstata: no atraviesa la vejiga. → (B) Pasa <b>por dentro</b> de la próstata, no por delante. → (D) Recorre el cuerpo <b>esponjoso</b> y termina en el orificio externo, en el glande; los cuerpos cavernosos son los otros dos cilindros del pene."},
  {st: "<b>Choice de anatomía · 20.</b> La vena testicular del lado izquierdo desemboca en la vena…", opts: ["Cava inferior.", "Renal derecha.", "Porta.", "Renal izquierda."], c: 3, ex: "Es una asimetría: la vena testicular <b>derecha</b> desemboca directo en la <b>cava inferior</b>; la <b>izquierda</b>, en la <b>vena renal izquierda</b>. Lo mismo vale para las venas ováricas. → <b>Las otras:</b> (A) En la cava inferior desemboca la del lado derecho. → (B) La renal derecha no recibe venas gonadales. → (C) La vena porta recoge la sangre del tubo digestivo, el bazo y el páncreas."},
  // CHOICE-DOCENTE reales (repaso de anatomia 2025) fin
]);

// ---------- SECCIÓN 8 · SIMULACRO DE SEGUNDO PARCIAL ----------
// 20 preguntas PROPIAS. Respiratorio 3 · cardiovascular 3 · digestivo 3 ·
// urinario 3 · endócrino 4 · nervioso 4. Cinco vienen envueltas en escenario
// de diseño (25 %) y tres usan el formato "V o F, elegí la justificación".
registerExercises('fiuba-anatomia-segundo-parcial', '8', [
  {st: '<b>1 · RESPIRATORIO.</b> Un equipo desarrolla un oxigenador de membrana extracorpóreo y quiere maximizar la transferencia de O2 sin aumentar el volumen del dispositivo. ¿Qué estrategia reproduce el principio que usa el alvéolo?', opts: ["Aumentar el espesor de la membrana, porque una pared más gruesa resiste mayores presiones sin romperse", "Maximizar la superficie y reducir el espesor de la membrana, porque la difusión crece con el área y cae con la distancia", "Aumentar el flujo de sangre por encima de todo, porque la difusión depende sobre todo de la velocidad del flujo", "Usar un material permeable al agua pero no a los gases, porque la difusión depende de la solubilidad en agua"], c: 1, ex: "La membrana alveolocapilar es <b>~0,5 µm</b> de espesor sobre <b>~70 m²</b> de superficie: es la solución biológica al mismo problema. Los cuatro determinantes de la difusión son <b>gradiente de presión parcial, superficie, distancia de difusión y peso molecular/solubilidad</b>, y un oxigenador los usa como sus cuatro variables de diseño. → <b>Las otras:</b> (A) Aumentar el espesor es exactamente aumentar la distancia de difusión: es lo que hace el <b>edema pulmonar</b> y por eso empeora el intercambio. → (C) El flujo determina cuánta sangre se expone, no la velocidad de difusión a través de la membrana; y un flujo excesivo reduce el tiempo de contacto. → (D) Es un requisito invertido: una membrana de intercambio gaseoso tiene que ser permeable a los gases y estanca al líquido, no al revés."},
  {st: '<b>2 · RESPIRATORIO.</b> Verdadero o falso: "en un recién nacido prematuro con déficit de surfactante, el problema es que el pulmón no puede expandirse por falta de fuerza muscular". Elegí la justificación.', opts: ["Verdadero: el prematuro tiene el diafragma inmaduro y no genera la fuerza necesaria para expandir el pulmón", "Falso: sin surfactante sube la tensión superficial del líquido alveolar y los alvéolos colapsan al espirar", "Falso: el problema es que le falta hemoglobina fetal y la sangre no capta bien el oxígeno en el alvéolo pulmonar", "Verdadero: el pulmón prematuro tiene demasiado tejido elástico y por eso no logra expandirse"], c: 1, ex: "El <b>surfactante</b> es una mezcla de fosfolípidos y lipoproteínas que produce el <b>neumocito II</b>, y su función es puramente <b>fisicoquímica</b>: baja la <b>tensión superficial</b> del líquido que tapiza el alvéolo, que es la fuerza que tiende a colapsarlo. Sin surfactante, el alvéolo se cierra al final de cada espiración y hay que reabrirlo con cada inspiración: eso es el síndrome de dificultad respiratoria del prematuro. → Justamente porque la función es fisicoquímica y no metabólica, el fármaco funciona <b>instilado directo</b> en la vía aérea (surfactante exógeno): no hay que reemplazar una célula, hay que reponer una molécula tensioactiva. → <b>Las otras:</b> (A) La premisa es falsa: el problema no es la fuerza muscular del diafragma sino la tensión superficial del líquido alveolar. → (C) La hemoglobina fetal no es un déficit: tiene mayor afinidad por el O<sub>2</sub> que la del adulto, y el cuadro del prematuro no es de captación de oxígeno por la sangre sino de alvéolos colapsados. → (D) Es al revés en el sentido de la pregunta: el retroceso elástico tiene dos componentes, fibras elásticas <b>más</b> tensión superficial, y es el segundo el que está descontrolado."},
  {st: '<b>3 · RESPIRATORIO.</b> Un paciente con enfisema tiene alvéolos fusionados y tejido elástico reemplazado por conectivo fibroso. ¿Por qué falla a la vez la ventilación y la respiración externa?', opts: ["Porque sólo se pierde superficie de intercambio, y esa pérdida basta para trabar también la ventilación", "Porque falla el retroceso elástico y sube la resistencia, y cae la superficie y sube la distancia", "Porque se pierde el surfactante, sube la tensión superficial y los alvéolos colapsan al final de la espiración", "Porque se paraliza el diafragma, cae el volumen corriente y además se reduce la superficie de intercambio"], c: 1, ex: "El enfisema es el ejemplo del programa donde una sola lesión ataca los <b>dos</b> mecanismos. Perder tejido elástico arruina el <b>retroceso elástico</b> que hace la espiración pasiva y el aire queda atrapado (la distensibilidad no baja: el pulmón se estira fácil, lo que falla es que vuelva), y los bronquiolos inflamados suben la <b>resistencia</b>; eso es la falla de la ventilación. Perder tabiques <b>fusiona alvéolos</b> y con eso se pierde <b>superficie</b> de intercambio, mientras el tejido fibroso aumenta la <b>distancia de difusión</b>; eso es la falla de la respiración externa. → Los dos primeros son problemas de <b>bomba</b>; los dos últimos, de <b>intercambiador</b>. Poder separar esos dos planos es lo que la pregunta evalúa. → <b>Las otras:</b> (A) Ignora el plano de la bomba: la pérdida de retroceso elástico y el aumento de resistencia también están alterados y no se explican por la superficie. → (C) El surfactante lo sigue produciendo el neumocito II; el déficit de surfactante es otro cuadro (SDR del prematuro). → (D) El diafragma funciona; de hecho el paciente con enfisema lo usa de más."},
  {st: '<b>4 · CARDIOVASCULAR.</b> Ordená correctamente el trayecto de la sangre desde la aurícula derecha hasta la aurícula izquierda.', opts: ["AD → válvula mitral → VD → válvula sigmoidea pulmonar → tronco pulmonar → arterias pulmonares → capilares alveolares → venas pulmonares → AI", "AD → válvula tricúspide → VD → válvula sigmoidea pulmonar → tronco pulmonar → arterias pulmonares → capilares alveolares → venas pulmonares → AI", "AD → válvula tricúspide → VI → válvula sigmoidea aórtica → aorta ascendente → capilares sistémicos → venas cavas → AI", "AD → válvula sigmoidea aórtica → VD → tronco pulmonar → venas pulmonares → capilares alveolares → arterias pulmonares → AI"], c: 1, ex: "Es la <b>circulación menor</b>, y el examen exige que no te saltees ninguna válvula. Del lado derecho: <b>tricúspide</b> (AV) y <b>sigmoidea pulmonar</b> (salida). Del lado izquierdo, después: <b>mitral o bicúspide</b> y <b>sigmoidea aórtica</b>. → Recordá que las <b>arterias pulmonares llevan sangre desoxigenada</b> y las <b>cuatro venas pulmonares, oxigenada</b>: son las dos excepciones a la regla intuitiva, y arteria/vena se define por la <b>dirección</b> respecto del corazón, no por el contenido. → <b>Las otras:</b> (A) Pone la mitral, que es izquierda, entre la aurícula y el ventrículo derechos: del lado derecho la válvula AV es la tricúspide. → (C) Manda la sangre de la aurícula derecha al ventrículo izquierdo, cosa que el tabique impide, y recorre la circulación mayor en vez de pasar por el pulmón. → (D) Invierte arterias y venas pulmonares y pone la sigmoidea aórtica a la salida de la aurícula."},
  {st: '<b>5 · CARDIOVASCULAR.</b> Un paciente hipertenso tiene aumentada crónicamente la resistencia arterial sistémica. Sobre su volumen sistólico:', opts: ["Aumenta, porque lo que aumentó es la CONTRACTILIDAD, la fuerza con que se contrae el ventrículo", "Disminuye, porque lo que aumentó es la POSCARGA, que es la presión que hay que superar para abrir las válvulas sigmoideas", "No cambia, porque lo que aumentó es la RESISTENCIA y el volumen sistólico sólo depende del retorno venoso al corazón", "Aumenta, porque lo que aumentó es la PRECARGA, el estiramiento de las fibras al final de la diástole"], c: 1, ex: "Los tres determinantes del volumen sistólico y su signo: <b>precarga ↑ → VS ↑</b> (Frank-Starling: más estiramiento de las fibras al final de la diástole, más fuerza de contracción), <b>contractilidad ↑ → VS ↑</b>, y <b>poscarga ↑ → VS ↓</b>. La hipertensión sube la <b>poscarga</b>: el ventrículo tiene que generar más presión sólo para abrir la sigmoidea aórtica, y le queda menos energía para expulsar volumen. → La combinación que <b>maximiza</b> el volumen sistólico es la inversa exacta: ↑precarga + ↓poscarga + ↑contractilidad. → <b>Las otras:</b> (A) La contractilidad es una propiedad del miocardio que no cambia por tener mayor resistencia arterial: lo que se elevó es la poscarga, y contra una poscarga mayor el volumen sistólico baja. → (C) Ignora dos de los tres determinantes: el volumen sistólico depende de precarga, contractilidad y poscarga, no sólo del retorno venoso. → (D) Lo que aumentó no es la precarga: la hipertensión eleva la poscarga. Frank-Starling es el mecanismo de la <b>precarga</b>, y sirve para igualar automáticamente el gasto de los dos ventrículos."},
  {st: '<b>6 · CARDIOVASCULAR.</b> Se diseña un injerto vascular sintético para reemplazar un segmento de aorta ascendente. ¿Qué propiedad de la aorta nativa hay que reproducir y por qué?', opts: ["Su capacidad de vasoconstricción: reduce el calibre para redistribuir el flujo hacia los órganos que lo necesitan", "Su distensibilidad elástica: se dilata en sístole almacenando energía y retrocede en diástole, haciendo más continuo el flujo", "Su lámina basal fenestrada: permite el intercambio de nutrientes y gases con los tejidos vecinos en toda la pared", "Su contractilidad rítmica: se contrae en sincronía con el ventrículo y empuja la sangre en cada latido hacia toda la periferia del cuerpo"], c: 1, ex: "La aorta es una <b>arteria elástica</b> o de conducción: la túnica media está dominada por <b>láminas elásticas fenestradas</b>. Esa elasticidad (distensibilidad) amortigua el pico sistólico y devuelve energía en diástole, convirtiendo un flujo pulsátil en uno más continuo, que es lo que sostiene el flujo entre latidos. Un injerto rígido no amortigua y transmite el pulso entero a la periferia, con las consecuencias hemodinámicas conocidas. → <b>Las otras:</b> (A) La vasoconstricción para redistribuir flujo es de la arteria <b>muscular</b>, y la regulación fina de resistencia es de la <b>arteriola</b>. La aorta no cambia su calibre para repartir flujo. → (C) El intercambio ocurre en los <b>capilares</b>: una arteria grande es tan impermeable que necesita <b>vasa vasorum</b> para nutrir su propia pared. → (D) La aorta no se contrae activamente en sincronía: se deja distender y retrocede pasivamente, que es distinto."},
  {st: '<b>7 · DIGESTIVO.</b> Un enunciado describe un tramo del tubo digestivo con "epitelio cilíndrico simple con muchísimas células caliciformes, sin vellosidades, criptas rectas y profundas, y la capa longitudinal de la muscular condensada en tres bandas". ¿Qué tramo es?', opts: ["Duodeno", "Íleon", "Colon", "Esófago"], c: 2, ex: "Cuatro rasgos que sólo coexisten en el <b>colon</b> (intestino grueso): caliciformes abundantísimas (porque su trabajo es lubricar heces cada vez más deshidratadas), <b>ausencia de vellosidades</b> (no absorbe nutrientes, absorbe <b>agua, iones y las vitaminas K y del grupo B</b> que produce la microbiota), criptas rectas y profundas, y sobre todo las <b>tres tenias</b>, que son la capa longitudinal condensada en bandas. → Los tres rasgos exclusivos del grueso son <b>tenias</b>, <b>haustros</b> (porque las tenias son más cortas que el colon y lo fruncen) y <b>apéndices epiploicos</b>, y los tres <b>desaparecen en el recto</b>. → <b>Las otras:</b> (A) El duodeno tiene vellosidades y <b>glándulas de Brunner</b> en la submucosa. → (B) El íleon tiene vellosidades y <b>placas de Peyer</b>. → (D) El esófago es <b>plano estratificado no queratinizado</b> con adventicia."},
  {st: '<b>8 · DIGESTIVO.</b> Verdadero o falso: "la lámina propia es la túnica que fija la mucosa a la muscular". Elegí la justificación.', opts: ["Verdadero: la lámina propia es una túnica independiente que aloja los vasos grandes y el plexo de Meissner", "Falso: la lámina propia es parte de la mucosa; la que fija la mucosa a la muscular es la submucosa", "Falso: la lámina propia es parte de la submucosa, y la que fija la mucosa a la muscular es la serosa o adventicia", "Verdadero, pero sólo en el estómago, donde la lámina propia se continúa con la submucosa y la ancla"], c: 1, ex: "La <b>mucosa</b> tiene tres subcapas: <b>epitelio</b>, <b>lámina propia</b> (conectivo areolar con vasos, linfáticos y el <b>MALT</b>) y <b>muscular de la mucosa</b>. La <b>submucosa</b> es una túnica <b>aparte</b>, la que fija la mucosa a la muscular, aloja los vasos grandes y el <b>plexo de Meissner</b>. → Criterio de lectura para el examen: si el enunciado dice \"<b>fija la mucosa a la muscular</b>\", es submucosa; si dice \"conectivo areolar <b>de la mucosa</b> con vasos y tejido linfático\", es lámina propia. → <b>Las otras:</b> (A) Los vasos grandes y el plexo de Meissner están en la <b>submucosa</b>, que es la túnica independiente; la lámina propia es una subcapa de la mucosa. → (C) La lámina propia es parte de la <b>mucosa</b>, no de la submucosa, y la <b>serosa</b> o adventicia es la capa <b>más externa</b>: serosa (con mesotelio) si el órgano es intraperitoneal, adventicia (sin mesotelio) si es <b>retroperitoneal</b> o está fuera de la cavidad, como el esófago; no fija la mucosa a la muscular. → (D) En ningún tramo, tampoco en el estómago, la lámina propia cumple esa función: está dentro de la mucosa, y la que ancla es la submucosa."},
  {st: '<b>9 · DIGESTIVO.</b> Un fármaco liposoluble se absorbe en el intestino delgado y entra en los quilomicrones. ¿Qué consecuencia farmacocinética tiene?', opts: ["Llega antes al hígado que uno hidrosoluble, porque entra por la vena porta junto con los quilomicrones", "Se saltea el primer paso hepático, porque sale por el vaso quilífero y llega a la sangre por el conducto torácico", "No llega a la circulación sistémica, porque los quilomicrones quedan retenidos en el vaso quilífero de la vellosidad", "Se degrada en la vena porta, porque ahí los quilomicrones son hidrolizados antes de llegar al hígado"], c: 1, ex: "Es la <b>gran asimetría</b> de la absorción y tiene aplicación directa. Hidratos y aminoácidos entran a la <b>sangre</b> del capilar de la vellosidad y van directo al <b>hígado</b> por la vena porta: todo lo absorbido por esa vía pasa por el filtro hepático antes de llegar a la circulación general. Los lípidos (y lo que viaja con ellos) se resintetizan como triglicéridos dentro del enterocito, se empaquetan en <b>quilomicrones</b> y salen por el <b>vaso quilífero</b> del centro de la vellosidad, llegando a la sangre por el <b>conducto torácico</b>: se saltean el hígado en el primer pasaje, evitando el efecto de primer paso hepático. → Única excepción: los ácidos grasos de <b>cadena corta</b> van a la sangre portal. → <b>Las otras:</b> (A) Invierte la lógica: los quilomicrones no entran a la vena porta sino al vaso quilífero, y por vía linfática el fármaco llega <b>más tarde</b> al hígado, ya diluido en la circulación general. → (C) Sí llega a la circulación sistémica: los quilomicrones pasan del vaso quilífero a la linfa y de ahí a la sangre por el conducto torácico, no quedan retenidos. → (D) No pasa por la vena porta: la vía linfática la evita, y los quilomicrones no son hidrolizados ahí."},
  {st: '<b>10 · URINARIO.</b> Un andamio renal descelularizado, sin células, filtra MÁS que un riñón entero y retiene sólo el 23 % de la albúmina, contra el 89,9 % del riñón cadavérico. ¿Qué demuestra ese resultado?', opts: ["Que el andamio es mejor que el riñón nativo, porque filtra más y mantiene intacta la arquitectura glomerular", "Que la membrana basal sola no alcanza: la selectividad la aportan las células, en especial los podocitos y su carga", "Que la descelularización destruyó la membrana basal glomerular, y por eso dejó pasar la albúmina sin resistencia alguna", "Que el andamio conserva toda la función del glomérulo, y la fuga de albúmina se debe a la presión de perfusión usada en el ensayo"], c: 1, ex: "Es el resultado más didáctico del paper y por eso es material de pregunta. El andamio conserva la <b>arquitectura</b> (membrana basal glomerular y de la cápsula de Bowman intactas, colágeno y glucosaminoglucanos conservados) pero <b>filtra sin selectividad</b>: deja pasar albúmina y glucosa a lo bruto. → Conclusión: <b>la matriz aporta la geometría, la función la aportan las células</b> (sobre todo las hendiduras de filtración de los podocitos y la barrera de carga) cuando recuperan su polaridad en el compartimento correcto. Al resembrar, la retención de albúmina sube a 46,9 % y la reabsorción de glucosa de 2,8 % a 47,4 %: engraftaron células funcionales, pero apenas la mitad de las necesarias. → <b>Las otras:</b> (A) Filtrar más es justamente lo <b>malo</b>: perder proteínas y glucosa. → (C) Es lo contrario: los autores verifican explícitamente que la membrana basal se conserva. → (D) Si el problema fuera la presión de perfusión no mejoraría al resembrar: la retención de albúmina sube cuando se reponen células, lo que muestra que la fuga se debe a su ausencia y no a un artefacto de medición."},
  {st: '<b>11 · URINARIO.</b> ¿Qué segmento reabsorbe prácticamente el 100 % de la glucosa filtrada, y qué se observa si se supera su capacidad de transporte?', opts: ["El túbulo colector; si se supera su capacidad aparece proteinuria", "El túbulo contorneado proximal; si se supera aparece glucosuria", "El asa de Henle ascendente; si se supera su capacidad aparece cetonuria", "El glomérulo; si se supera su capacidad de filtración aparece hematuria"], c: 1, ex: "El <b>TCP</b> es el segmento de reabsorción masiva: ~65 % del agua y del Na⁺, prácticamente <b>el 100 % de la glucosa y de los aminoácidos</b> y el grueso del bicarbonato, y además <b>secreta</b> H⁺, amonio y fármacos. Su morfología lo delata: <b>borde en cepillo denso</b> (superficie) y <b>muchas mitocondrias</b> (transporte activo). → Como la reabsorción de glucosa depende de <b>transportadores saturables</b>, si la glucemia sube lo suficiente se supera el transporte máximo y aparece <b>glucosuria</b>: es lo que pasa en la diabetes. Normalmente la orina <b>no</b> tiene glucosa. → <b>Las otras:</b> (A) El colector ajusta agua y sales con la ADH y la aldosterona, no reabsorbe la glucosa; la proteinuria/albuminuria indica aumento de la permeabilidad de la <b>membrana de filtración</b>, no falla del colector. → (C) El asa de Henle reabsorbe agua y sales para concentrar la orina, no glucosa; la cetonuria aparece en ayuno, inanición o dieta muy baja en hidratos. → (D) El glomérulo filtra, no reabsorbe: la glucosa se filtra libremente y se recupera aguas abajo; la hematuria indica ruptura de la barrera de filtración, no saturación de un transportador."},
  {st: '<b>12 · URINARIO.</b> Se construye un reemplazo bioingenieril de vejiga usando un segmento de intestino. ¿Qué problema aparece y qué propiedad del urotelio lo explica?', opts: ["Ninguno, porque el epitelio intestinal también es impermeable y se distiende igual que el urotelio sin romperse ni filtrar", "Acidosis metabólica y litiasis, porque el intestino absorbe solutos de la orina y el urotelio es impermeable", "Rotura por la presión de llenado, porque el epitelio intestinal no soporta la distensión que sí soporta el urotelio", "Falta de irrigación, porque el epitelio intestinal no puede vascularizarse en esa posición como el urotelio"], c: 1, ex: "El <b>epitelio de transición</b> o urotelio tiene células apicales en sombrilla con placas rígidas y uniones estrechas: aísla al organismo de una orina <b>hipertónica y ácida</b> y a la vez <b>se deforma sin romperse</b> cuando la vejiga se llena. Son dos requisitos simultáneos (<b>impermeabilidad</b> y <b>distensibilidad</b>) que ningún otro epitelio cumple igual. → Un segmento de intestino aporta distensibilidad pero su epitelio está diseñado para lo contrario: <b>absorber</b>. Reabsorbe solutos de la orina y aparecen acidosis metabólica y litiasis. → Es el ejemplo perfecto de traducir requisito funcional a estructura: el requisito no es un saco flexible, es un saco flexible <b>estanco</b>. → <b>Las otras:</b> (A) El epitelio intestinal no es impermeable: está hecho para absorber, y ahí está el problema. → (C) La presión de llenado la tolera; el problema es químico, no mecánico. → (D) El segmento se trasplanta con su pedículo vascular del mesenterio, así que se irriga bien; el problema no es la irrigación."},
  {st: '<b>13 · ENDÓCRINO.</b> Una paciente tiene cortisol bajo, ACTH baja y CRH alta. ¿Dónde está la lesión?', opts: ["En la corteza suprarrenal: insuficiencia primaria, porque la periférica cae y la trófica baja por el freno que ejerce la CRH alta", "En la hipófisis: insuficiencia secundaria, porque la ACTH cae junto con el cortisol y la CRH alta muestra al hipotálamo sano", "En el hipotálamo: insuficiencia terciaria, porque la ACTH baja refleja que no logra estimular a la hipófisis", "En la médula suprarrenal: insuficiencia medular, porque sus catecolaminas son las que sostienen la secreción de cortisol"], c: 1, ex: "Aplicá el método sin memorizar. <b>Paso 1:</b> periférica (cortisol) <b>baja</b> → hay hipofunción. <b>Paso 2:</b> trófica (ACTH) <b>también baja</b> → misma dirección → el fallo es <b>central</b>. <b>Desempate:</b> la hipotalámica (CRH) está <b>alta</b>, o sea que el hipotálamo está sano y compensando → el piso roto es el <b>intermedio</b>: la hipófisis → <b>SECUNDARIO</b>. → <b>Las otras:</b> (A) Un primario daría cortisol bajo con <b>ACTH alta</b>, porque la hipófisis pierde el freno negativo; la CRH no frena nada, el que frena es el cortisol. → (C) En el terciario la <b>CRH estaría baja</b>, y sería el escalón más alto deprimido. La CRH alta descarta el hipotálamo. → (D) La <b>médula</b> suprarrenal produce <b>adrenalina y noradrenalina</b>, no cortisol, y no la regula la ACTH sino el simpático directo; sus catecolaminas no sostienen la secreción de cortisol."},
  {st: '<b>14 · ENDÓCRINO.</b> Se diseña un constructo que encapsula células productoras de una hormona peptídica para implantarlo. ¿Qué hay que verificar además de que el constructo secrete la hormona?', opts: ["Que la hormona sea liposoluble, para que difunda mejor por el andamio y llegue a todas las células sembradas", "Que las células blanco expresen el receptor específico, porque sin receptor no hay respuesta aunque la hormona abunde en el medio", "Que el constructo esté cerca del órgano blanco, porque las hormonas sólo actúan a corta distancia de quien las secreta", "Que el constructo tenga inervación propia, porque la liberación de cualquier hormona exige un control nervioso directo"], c: 1, ex: "El concepto que la cátedra toma textual es <b>distribución universal, acción específica</b>: la sangre lleva la hormona a todas las células por igual, y lo que define el blanco es la <b>expresión del receptor</b>. Una célula sin receptor es sorda a la hormona aunque la tenga encima. → En enunciado bioingenieril el error aparece disfrazado: <i>la hormona difunde por todo el andamio, entonces todas las células sembradas responden</i> (falso si no expresan el receptor). Validar un constructo endócrino es verificar <b>receptor en la célula blanco</b>, no sólo hormona en el sobrenadante. → Corolario: la sensibilidad de un tejido se regula subiendo o bajando el <b>número de receptores</b>, no cambiando la hormona. → <b>Las otras:</b> (A) Las hormonas peptídicas son <b>hidrosolubles</b> (no atraviesan la membrana) y actúan por receptor de membrana; la liposolubilidad es propia de las esteroides y las tiroideas, y no se pide para una peptídica. → (C) Es exactamente la confusión que la pregunta busca: las hormonas actúan a distancia por vía sanguínea; la acción a corta distancia es <b>paracrina</b>, otra categoría. → (D) La secreción endócrina no exige inervación: la regulan señales humorales (otras hormonas, glucemia, calcemia); sólo algunas glándulas, como la médula suprarrenal, dependen del sistema nervioso."},
  {st: '<b>15 · ENDÓCRINO.</b> Un paciente en ayuno prolongado mantiene la glucemia. ¿Qué hormona lo explica y sobre qué órgano actúa?', opts: ["Insulina, sobre el músculo: moviliza el glucógeno muscular y libera glucosa libre al plasma", "Glucagón, sobre el hígado: activa la glucogenólisis y la gluconeogénesis y libera glucosa", "Somatostatina, sobre el páncreas: estimula la secreción de glucagón para sostener la glucemia", "Calcitonina, sobre el hueso: moviliza glucosa almacenada en la matriz ósea hacia el plasma"], c: 1, ex: "Ante hipoglucemia la célula <b>alfa</b> del islote secreta <b>glucagón</b>, que actúa fundamentalmente sobre el <b>hígado</b>: degrada glucógeno (glucogenólisis) y, en ayuno más largo, fabrica glucosa nueva (gluconeogénesis). → El detalle que hace funcionar la lógica: el hígado es prácticamente el único órgano que puede <b>exportar glucosa libre</b> a la sangre, porque tiene <b>glucosa-6-fosfatasa</b>. El músculo almacena glucógeno pero lo consume localmente y no lo devuelve a la circulación. <i>(La corteza renal también tiene la enzima y gana peso en el ayuno prolongado.)</i> → <b>Las otras:</b> (A) La insulina es la hormona del estado <b>posprandial</b>: baja la glucemia. Administrarla acá agravaría el cuadro, y además el músculo no exporta glucosa libre. → (C) La somatostatina (célula D) <b>frena</b> a insulina y glucagón: no estimula a ninguno. → (D) La calcitonina regula el <b>calcio</b>, y el hueso no almacena glucosa."},
  {st: '<b>16 · ENDÓCRINO.</b> Verdadero o falso: "la neurohipófisis produce ADH y oxitocina". Elegí la justificación.', opts: ["Verdadero: las dos hormonas se sintetizan en las células secretoras de la neurohipófisis, que es una glándula", "Falso: las sintetizan neuronas hipotalámicas (núcleos supraóptico y paraventricular) y la neurohipófisis las libera", "Falso: las sintetizan las células de la adenohipófisis y la neurohipófisis las libera al torrente a través del tallo", "Verdadero: la neurohipófisis las sintetiza en sus pituicitos y las libera según la osmolaridad y las necesidades del parto"], c: 1, ex: "Es la trampa de compartimento del tema. La <b>neurohipófisis</b> no es glándula: son los <b>axones</b> de neuronas hipotalámicas (núcleos <b>supraóptico y paraventricular</b>) que bajan por el tallo y sueltan ahí su producto. Es un <b>andén</b>, no una fábrica. → Consecuencia de examen: si preguntan qué glándula <b>sintetiza</b> la oxitocina, la respuesta involucra al <b>hipotálamo</b>; si preguntan de dónde <b>se libera</b>, la respuesta es neurohipófisis. Leé el verbo. → La <b>adenohipófisis</b> sí es glandular y fabrica sus <b>siete</b> hormonas (GH, prolactina, TSH, ACTH, FSH, LH, MSH). → Blancos: <b>ADH</b> → túbulo colector renal, responde a la <b>osmolaridad</b> y concentra la orina; <b>oxitocina</b> → músculo liso uterino (parto) y mioepitelio mamario (eyección láctea). → <b>Las otras:</b> (A) La neurohipófisis no es glándula, es tejido nervioso: la afirmación es falsa. → (C) La adenohipófisis no sintetiza ADH ni oxitocina; produce las siete hormonas de la lista y se conecta con el hipotálamo por el sistema porta, no por el tallo nervioso. → (D) Los pituicitos son células gliales de sostén, no sintetizan nada; la afirmación es falsa."},
  {st: '<b>17 · NERVIOSO.</b> Un paciente entiende perfectamente lo que le dicen pero no logra formar las palabras. ¿Qué área está afectada y en qué lóbulo está?', opts: ['Área de Wernicke, en el lóbulo temporal', 'Área de Broca, en el lóbulo frontal', 'Corteza somatosensorial, en el lóbulo parietal', 'Cerebelo'], c: 1, ex: 'La inversión clásica del tema: <b>Broca = producir</b> (lenguaje expresivo, lóbulo <b>frontal</b>), <b>Wernicke = comprender</b> (lóbulo <b>temporal</b>). Comprensión conservada más producción alterada es Broca. Las dos están en el hemisferio izquierdo en el ~95 % de las personas. → <b>Las otras:</b> (A) Una lesión de Wernicke daría lo inverso: habla fluida pero sin comprensión. → (C) El parietal es <b>somatosensorial</b> (circunvolución poscentral), percepción espacial y cálculo. → (D) El cerebelo hace <b>coordinación, equilibrio y postura</b>, y además <b>no es un lóbulo cortical</b>. Es el distractor que la cátedra usó realmente en su pregunta de lóbulo temporal.'},
  {st: '<b>18 · NERVIOSO.</b> ¿Cuál de estas células gliales NO pertenece al SNC?', opts: ["Astrocito fibroso", "Oligodendrocito", "Célula de Schwann", "Célula ependimaria"], c: 2, ex: "Del <b>SNC</b>: <b>astrocito</b> (protoplásmico en la sustancia gris y fibroso en la blanca; barrera hematoencefálica, cicatriz glial, metabolismo), <b>oligodendrocito</b> (mielina del SNC), <b>microglía</b> (fagocitosis; la <b>única</b> de origen <b>mesodérmico</b>, viene de la médula ósea) y <b>ependimaria</b> (reviste ventrículos y canal del epéndimo, participa en el LCR). → Del <b>SNP</b>: <b>célula de Schwann</b> (mielina periférica) y <b>célula satélite</b> (rodea el soma de las neuronas en los ganglios). Las dos derivan de <b>cresta neural</b>. → <b>Las otras:</b> (A) El astrocito fibroso es del SNC. → (B) El oligodendrocito forma la mielina del SNC. → (D) La célula ependimaria reviste las cavidades del SNC. → La discriminación se pregunta en la forma cuál corresponde a este compartimento, con las cuatro opciones descriptas correctamente: no se puede eliminar por absurdo, hay que saber cuál es cuál."},
  {st: '<b>19 · NERVIOSO.</b> Se desarrolla un organoide neural a partir de precursores ectodérmicos para modelar neuroinflamación. ¿Qué le falta y por qué?', opts: ["Le faltan astrocitos, porque son de origen mesodérmico y no derivan del ectodermo de los precursores", "Le falta microglía, que es la única glía mesodérmica y hay que sumarla desde linaje hematopoyético", "Le faltan oligodendrocitos, porque derivan de la cresta neural y no del tubo neural de los precursores", "No le falta nada, porque el ectodermo da todo el tejido nervioso, microglía incluida, sin excepciones"], c: 1, ex: "Todo el tejido nervioso es <b>ectodérmico</b> salvo la <b>microglía</b>, y esa excepción tiene una consecuencia experimental exacta: un organoide derivado sólo de precursores ectodérmicos <b>no tiene microglía</b>, y sin microglía no hay fagocitosis ni respuesta inmune innata, o sea que no se puede modelar neuroinflamación. Como es la única glía mesodérmica (viene de la médula ósea), hay que coemergerla o agregarla desde linaje hematopoyético. → <b>Las otras:</b> (A) El astrocito es <b>ectodérmico</b>, así que los precursores sí lo generan. → (C) Los oligodendrocitos son del <b>tubo neural</b> (SNC); de la <b>cresta</b> derivan Schwann y satélite, que son del SNP, y la cresta también es ectodérmica. → (D) Es la trampa espejo: la excepción existe y es una sola, la microglía."},
  {st: '<b>20 · NERVIOSO.</b> Verdadero o falso: "una fibra amielínica no tiene células de Schwann". Elegí la justificación.', opts: ["Verdadero: sin vaina de mielina no hay célula de Schwann, y el axón queda desnudo dentro del endoneuro", "Falso: la célula de Schwann está, pero envuelve muchos axones sin formar vaina, sin neuroqueratina ni incisuras", "Falso: las fibras amielínicas del SNP están envueltas por oligodendrocitos que agrupan varios axones sin formar vaina", "Verdadero: por eso no tiene vaina, y el axón queda en contacto directo con el endoneuro sin ninguna célula glial"], c: 1, ex: "La diferencia no es la <b>presencia</b> de la célula de Schwann sino su <b>relación con los axones</b>: en la fibra <b>mielínica</b> una célula cubre <b>un segmento de un solo axón</b> y forma la vaina; en la <b>amielínica</b> una célula agrupa <b>varios axones</b> sin enrollarse sobre ellos. De ahí los cuatro negativos que se preguntan: sin vaina, sin neuroqueratina, sin incisuras de Schmidt-Lanterman y sin axones distinguibles al microscopio óptico. El <b>endoneuro</b>, en cambio, está en las dos. → Consecuencia de diseño: un andamio que alinee axones pero no favorezca la <b>mielinización por Schwann</b> no recupera velocidad de conducción, porque sin nodos de Ranvier no hay <b>conducción saltatoria</b>. A mayor mielinización y mayor calibre, mayor velocidad. → <b>Las otras:</b> (A) Falta la vaina, no la célula: la célula de Schwann está presente y el axón no queda desnudo. → (C) Los oligodendrocitos son del <b>SNC</b>: error de compartimento. → (D) Misma confusión que (A): la fibra amielínica está rodeada por Schwann, no en contacto directo con el endoneuro."},
]);

// ============================================================
// OPCIONES AL AZAR (las cuatro guías de Anatomía llevan este mismo bloque).
// Cada vez que se abre la página, las opciones de cada pregunta cambian de lugar, así la
// posición de la correcta no se aprende de memoria. Cada opción muestra su letra y las letras
// que cita la explicación ("(B)", "la b", "opción C") se cambian con ella, igual que los
// ordinales ("la primera opción") en las preguntas que se revisaron una por una. No se mueven
// "Ninguna...", "Todas..." ni "Ambas...", y quedan como están las preguntas cuya explicación
// nombra las opciones de una forma que no se puede reescribir sola. El generador de simulacros
// del 1er parcial usa las mismas funciones (globalThis.MEZCLA_OPC) para mezclar en cada simulacro.
// Claves: M madre, P 1er parcial, Q preguntas explicadas, S 2do parcial + unidad + # + índice.
// ============================================================
(function () {
  'use strict';
  const SUBJ = 'fiuba-anatomia-segundo-parcial', CLAVE = 'S';
  if (!globalThis.MEZCLA_OPC) {
    const LETRAS = 'ABCDEFGH';
    const ORDINAL = ['primera', 'segunda', 'tercera', 'cuarta'];
    // Explicaciones que nombran opciones por su orden y que se reescriben ("La tercera confunde...").
    const ORDINALES = new Set(['M2#5', 'M2#12', 'M3#1', 'M3#8', 'M4#9', 'M4#10', 'M4#11', 'M4#12', 'M5#5', 'M5#6', 'M5#7', 'M5#8', 'M5#12',
      'M6#6', 'M6#8', 'M6#9', 'M6#10', 'M6#11', 'M6#12', 'M10#1', 'M10#4', 'M10#6', 'M11#4', 'M11#6']);
    // Posiciones que no se mueven: 'todas' deja la pregunta como está.
    const QUIETAS = {
      'P6#8': 'todas',   // "los tres primeros son obvios y el cuarto parece del mismo grupo"
      'M3#5': [0, 1],    // "Las dos primeras opciones son la misma inversión"
      'P9#3': 'todas', 'Q6#0': 'todas', // "En la diapositiva la opción b dice...": la letra es la de la diapositiva
      'S7#4': 'todas',   // "De las cuatro opciones, C es la única parenteral"
      // Nombran opciones por su orden con giros que no están en la lista de arriba.
      'M4#5': 'todas', 'M5#0': 'todas', 'M6#0': 'todas', 'M6#2': 'todas', 'M11#2': 'todas', 'M12#3': 'todas',
      'M12#8': 'todas', 'M12#9': 'todas', 'M12#13': 'todas', 'M13#2': 'todas', 'M13#4': 'todas', 'M14#10': 'todas',
      'M14#12': 'todas', 'M15#0': 'todas', 'M15#2': 'todas', 'M15#8': 'todas', 'M13#8': 'todas',
      'M12#11': [0, 1],  // "Las dos primeras opciones son incoherentes"
    };
    const plano = (s) => String(s).replace(/<[^>]+>/g, '');
    const mezclar = (arr) => {
      const a = arr.slice();
      for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
      return a;
    };
    // p[lugar original] = lugar nuevo.
    function permutacion(q, id) {
      const n = q.opts.length, ident = [];
      for (let i = 0; i < n; i++) ident.push(i);
      if (QUIETAS[id] === 'todas') return ident;
      // Si una opción nombra a otras ("A y B son correctas", "todas las anteriores"), no se mezcla.
      if (q.opts.some((o) => /\banteriores\b|\b[A-D] y [A-D] son\b/i.test(plano(o)))) return ident;
      const quietas = new Set(QUIETAS[id] || []);
      q.opts.forEach((o, i) => { if (/^\s*(A ninguna|Ninguna|Todas|Ambas)\b/i.test(plano(o))) quietas.add(i); });
      const libres = ident.filter((i) => !quietas.has(i));
      const destinos = mezclar(libres);
      const p = ident.slice();
      libres.forEach((i, k) => { p[i] = destinos[k]; });
      return p;
    }
    function reescribirEx(ex, id, p, n) {
      if (!ex) return ex;
      const cambio = (x) => {
        const i = LETRAS.indexOf(x.toUpperCase());
        if (i < 0 || i >= n || p[i] === undefined) return x;
        const y = LETRAS[p[i]];
        return x === x.toUpperCase() ? y : y.toLowerCase();
      };
      // "(B)"
      ex = ex.replace(/\(([A-Ha-h])\)/g, (m, x) => '(' + cambio(x) + ')');
      // "la b", "La B", "las c", "opción B" (no "las opciones b) y c)" de una nota de transcripción)
      ex = ex.replace(/(^|[^A-Za-zÀ-ÿ0-9])([Ll]as?|[Oo]pci[oó]n(?:es)?) ([A-Ha-h])(?![A-Za-zÀ-ÿ0-9)\-])/g, (m, pre, a, x) => pre + a + ' ' + cambio(x));
      if (ORDINALES.has(id)) {
        // "la primera opción", "La tercera confunde", "La última opción", "opción 3"
        ex = ex.replace(/(^|[^A-Za-zÀ-ÿ])([Ll]a) (primera|segunda|tercera|cuarta|última)(?= (?:opción|es|se|usa|inventa|confunde|invierte|describe|cambia|atribuye|atribuyen|contradice|contradicen|trae|traen|pide|salta|mezcla|elige|le|fusiona|y la)(?![A-Za-zÀ-ÿ]))/g,
          (m, pre, a, o) => {
            const i = o === 'última' ? n - 1 : ORDINAL.indexOf(o);
            const j = p[i];
            return pre + a + ' ' + (o === 'última' && j === n - 1 ? 'última' : ORDINAL[j]);
          });
        ex = ex.replace(/(^|[^A-Za-zÀ-ÿ])([Oo]pci[oó]n) ([1-9])(?![0-9])/g, (m, pre, a, d) => {
          const i = +d - 1;
          return pre + a + ' ' + ((p[i] === undefined ? i : p[i]) + 1);
        });
      }
      return ex;
    }
    globalThis.MEZCLA_OPC = { permutacion: permutacion, reescribirEx: reescribirEx, LETRAS: LETRAS };
  }

  // Las preguntas fijas de esta guía: se mezclan antes de que app.js las dibuje (lo hace 0,1 s
  // después de DOMContentLoaded), y cada opción lleva su letra adelante.
  function mezclarPreguntas() {
    const Z = globalThis.MEZCLA_OPC, EX = window.EX || {};
    Object.keys(EX).forEach((k) => {
      if (k.indexOf(SUBJ + '-') !== 0) return;
      const unidad = k.slice(SUBJ.length + 1);
      if (!/^\d+[a-z]?$/.test(unidad)) return;
      EX[k].forEach((q, i) => {
        if (!q || !Array.isArray(q.opts) || typeof q.c !== 'number' || q._mezclada) return;
        const id = CLAVE + unidad + '#' + i;
        const p = Z.permutacion(q, id);
        const opts = [];
        q.opts.forEach((o, j) => { opts[p[j]] = o; });
        q.ex = Z.reescribirEx(q.ex, id, p, q.opts.length);
        q.c = p[q.c];
        q.opts = opts.map((o, j) => '<span class="op-letra" aria-hidden="true">' + Z.LETRAS[j] + '</span><span class="op-txt">' + o + '</span>');
        q._mezclada = true;
      });
    });
  }
  if (typeof document !== 'undefined' && typeof window !== 'undefined' && document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mezclarPreguntas);
  }
})();
